test("the command palette goes to a frame by its name, as a step Back undoes", async () => {
  const app = await setup();
  const { doc, w, click } = app;
  try {
    const { selected, key } = await rotationFixture(
      app,
      ["Kickoff", "Ideas", ""].map((text, n) =>
        item("frame", n * 3000, 0, { w: 800, h: 600, text, order: n }),
      ),
    );
    key("Escape");
    await new Promise((r) => setTimeout(r, 80));
    const before = location();
    function location() {
      return w.location.href;
    }
    const find = async (query) => {
      await click('[data-action="commands"]');
      const search = doc.querySelector("#command-search");
      search.value = query;
      search.dispatchEvent(new w.Event("input", { bubbles: true }));
      return [...doc.querySelectorAll("[data-command]")];
    };
    let options = await find("ideas");
    assert.equal(options[0].dataset.command, `frame:${selected[1].id}`);
    assert.match(options[0].textContent, /^IdeasFrames/);
    options[0].click();
    await new Promise((r) => setTimeout(r, 80));
    assert.equal(
      doc.querySelector("#board-announcer").textContent,
      "Showing frame 2 of 3: Ideas",
    );
    assert.match(location(), new RegExp(`object=${selected[1].id}`));
    assert.notEqual(location(), before);
    // An untitled frame is found by its place, as in Frames and navigation.
    options = await find("frame 3");
    assert.equal(options[0].dataset.command, `frame:${selected[2].id}`);
    options[0].click();
    await new Promise((r) => setTimeout(r, 80));
    assert.equal(
      doc.querySelector("#board-announcer").textContent,
      "Showing frame 3 of 3: Frame 3",
    );
    // With nothing typed, frames come after every command, not first.
    options = await find("");
    assert.ok(options.every((o) => !o.dataset.command.startsWith("frame:")));
    doc
      .querySelector("#command-search")
      .dispatchEvent(
        new w.KeyboardEvent("keydown", { key: "Escape", bubbles: true }),
      );
  } finally {
    await app.close();
  }
});

test("keyboard changes the canvas shows are said to screen readers", async () => {
  const app = await setup();
  const { doc } = app;
  try {
    const { selected, key } = await rotationFixture(app, [
      item("frame", 0, 0, { w: 400, h: 300, text: "Plan", order: 0 }),
      item("note", 50, 50, { w: 100, h: 100, text: "Inside" }),
      item("note", 600, 50, { w: 100, h: 100, text: "Outside" }),
    ]);
    const said = async () => {
      await new Promise((r) => setTimeout(r, 80));
      return doc.querySelector("#board-announcer").textContent;
    };
    const choose = async (text) => {
      key("Escape");
      doc
        .querySelector(
          `#board-outline [data-id="${selected.find((i) => i.text === text).id}"]`,
        )
        .click();
      await new Promise((r) => setTimeout(r, 350));
    };
    await choose("Inside");
    // Crossing the frame's edge is said once, not each step.
    for (let n = 0; n < 60; n++) key("ArrowRight", { shiftKey: true });
    assert.equal(await said(), "Out of the frame");
    for (let n = 0; n < 60; n++) key("ArrowLeft", { shiftKey: true });
    assert.equal(await said(), "In frame: Frame: Plan");
    key("ArrowLeft");
    doc.querySelector("#board-announcer").textContent = "";
    assert.equal(await said(), "");
    key("=", { ctrlKey: true, altKey: true, shiftKey: true });
    assert.match(await said(), /^Size: \d+ × \d+$/);
    await choose("Outside");
    key("PageDown");
    assert.equal(await said(), "Sent to back");
    key("PageUp");
    assert.equal(await said(), "Brought to front");
    key("a", { ctrlKey: true });
    key("g", { ctrlKey: true });
    assert.equal(await said(), "3 objects grouped");
    key("g", { ctrlKey: true, shiftKey: true });
    assert.equal(await said(), "Ungrouped");
    key("z", { ctrlKey: true });
    assert.equal(await said(), "Undone");
    key("z", { ctrlKey: true, shiftKey: true });
    assert.equal(await said(), "Redone");
    key("z", { ctrlKey: true, shiftKey: true });
    assert.equal(await said(), "Nothing to redo");
  } finally {
    await app.close();
  }
});

