test("Frames and navigation offers the order arrows only to people who may reorder, and not on locked frames", async () => {
  const room = "frame-arrows";
  const frames = ["First", "Second", "Third"].map((text, n) =>
    item("frame", n * 400, 0, {
      w: 300,
      h: 200,
      text,
      order: n,
      ...(n === 1 ? { locked: true } : {}),
    }),
  );
  const shared = await sharedEditors(room, frames);
  try {
    const [, b] = shared.apps;
    await b.click('[data-action="frames"]');
    const panel = b.doc.querySelector("#frames-panel");
    const arrows = (f) =>
      [...panel.querySelectorAll(`[data-order="${f.id}"]`)].map((a) =>
        a.disabled ? "off" : "on",
      );
    assert.deepEqual(arrows(frames[0]), ["off", "off"], "Next to a locked one");
    assert.deepEqual(arrows(frames[1]), [], "None on a locked frame");
    assert.deepEqual(arrows(frames[2]), ["off", "off"]);
    const hint = panel.querySelector("#frame-list-hint");
    assert.match(hint.textContent, /Alt/);
    panel.querySelector(`[data-frame="${frames[0].id}"]`).focus();
    // A viewer is offered none, and is not told about them.
    await shared.env.service.call(owner, {
      op: "role",
      room,
      uuid: collaborator.uuid,
      role: "viewer",
    });
    b.w.dispatchEvent(new b.w.Event("online"));
    await shared.until(
      () => b.doc.querySelector(".editor.shared-viewer"),
      "Viewer access received",
    );
    await shared.until(
      () => !panel.querySelector("[data-order]"),
      "The arrows go",
    );
    assert.equal(hint.textContent, "Arrow keys move between frames.");
    assert.equal(
      b.doc.activeElement,
      panel.querySelector(`[data-frame="${frames[0].id}"]`),
    );
    assert.equal(panel.querySelector("#add-frame"), null);
  } finally {
    await shared.close();
  }
});

