test("checkpoints restore content and trash preserves boards for recovery", async () => {
  const app = await setup();
  const { doc, click, tick } = app;
  const count = () => doc.querySelectorAll("#board-outline [data-id]").length;
  try {
    await click('[data-action="new"]');
    await click('[data-action="add-note"]');
    await click('[data-action="more-tools"]');
    await click('[data-feature="history"]');
    doc.querySelector("#checkpoint-label").value = "One idea";
    await click("#checkpoint-create");
    await click("dialog .dialog-header button");
    await click('[data-action="duplicate"]');
    assert.equal(count(), 2);
    await click('[data-action="more-tools"]');
    await click('[data-feature="history"]');
    const row = [...doc.querySelectorAll(".revision-row")].find((r) =>
      r.textContent.includes("One idea"),
    );
    assert.ok(row);
    row.querySelector("[data-revision]").click();
    await tick();
    assert.equal(count(), 1);
    // Restoring is one step: Undo takes it back, and the steps before it
    // are still there.
    assert.equal(doc.querySelector('[data-action="undo"]').disabled, false);
    await click('[data-action="undo"]');
    assert.equal(count(), 2);
    await click('[data-action="undo"]');
    assert.equal(count(), 1);
    await click('[data-action="redo"]');
    assert.equal(count(), 2);
    await click('[data-action="redo"]');
    assert.equal(count(), 1);
    await click('[data-action="home"]');
    await click("[data-more]");
    await click("#remove-board");
    await click("#confirm-delete");
    assert.equal(doc.querySelectorAll(".board-card").length, 0);
    doc.querySelector('[data-filter="trash"]').focus();
    await click('[data-filter="trash"]');
    assert.equal(doc.querySelectorAll(".board-card").length, 1);
    // A board in the trash is not starred: the Favorites list never shows it.
    assert.equal(doc.querySelector(".board-card [data-favorite]"), null);
    assert.ok(doc.querySelector(".board-card [data-more]"));
    // Its card does not open the board; its name says what it does instead.
    assert.match(
      doc.querySelector(".board-card [data-open]").getAttribute("aria-label"),
      /^Restore or delete /,
    );
    assert.equal(
      doc
        .querySelector(".board-card [data-more]")
        .getAttribute("aria-haspopup"),
      "dialog",
    );
    assert.equal(
      doc.activeElement.dataset.filter,
      "trash",
      "The keyboard stays on the chosen list",
    );
    assert.equal(
      doc.querySelector('[data-filter="trash"]').getAttribute("aria-current"),
      "page",
    );
    assert.ok(
      !doc.querySelector('[data-filter="all"]').hasAttribute("aria-current"),
    );
    await click("[data-open]");
    await click("#restore-board");
    // An emptied trash says so, rather than inviting a new board.
    await click('[data-filter="trash"]');
    assert.equal(doc.querySelectorAll(".board-card").length, 0);
    assert.equal(
      doc.querySelector(".empty-state h3").textContent,
      "Trash is empty",
    );
    await click('[data-filter="all"]');
    // Restoring put the keyboard back on the board's card.
    assert.ok(
      doc.querySelector(".board-card [data-more]"),
      "The restored board is listed",
    );
    // A trashed board can also be removed for good, with its versions.
    await click('[data-action="new"]');
    await click('[data-action="home"]');
    const cards = () => doc.querySelectorAll(".board-card").length;
    assert.equal(cards(), 2);
    await click("[data-more]");
    await click("#remove-board");
    await click("#confirm-delete");
    assert.equal(cards(), 1);
    assert.equal(
      doc.activeElement.dataset.filter,
      "all",
      "The keyboard goes to the chosen list once the card is gone",
    );
    await click('[data-filter="trash"]');
    await click("[data-open]");
    await click("#purge-board");
    assert.match(
      doc.querySelector("dialog[open]").textContent,
      /recovery versions/,
    );
    await click("#confirm-purge");
    assert.equal(cards(), 0);
    assert.equal(
      doc.querySelector(".empty-state h3").textContent,
      "Trash is empty",
    );
    assert.match(doc.querySelector("#toast").textContent, /permanently/);
    await click('[data-filter="all"]');
    assert.equal(cards(), 1);
    await click('[data-filter="all"]');
    await click("[data-open]");
    assert.equal(count(), 1);
  } finally {
    await app.close();
  }
});

