test("a playbook saved as reusable content keeps its steps' timings and instructions", async () => {
  const app = await setup();
  const { w, doc, click, tick } = app;
  const latest = async () =>
    (await storedBoards(app))
      .filter((b) => b.items.some((i) => i.text === "Warm up"))
      .sort((a, b) => b.updated - a.updated)[0];
  try {
    await rotationFixture(app, [
      item("frame", 0, 0, { text: "Warm up", order: 0, w: 600, h: 400 }),
      item("note", 50, 100, { text: "Check in" }),
    ]);
    await click('[data-action="facilitation"]');
    await click("#fac-tab-agenda");
    doc.querySelector(".fac-step-minutes").value = "7";
    doc.querySelector(".fac-step-text").value = "One word each.";
    doc
      .querySelector("#fac-agenda-form")
      .dispatchEvent(new w.Event("submit", { cancelable: true }));
    await tick();
    await click('[data-action="facilitation"]');
    // The frame and its note, still selected, are saved for reuse.
    await click('[data-action="organize"]');
    await click('[data-organize="snippet"]');
    doc.querySelector("#snippet-name").value = "Warm-up playbook";
    doc
      .querySelector("dialog form")
      .dispatchEvent(new w.Event("submit", { cancelable: true }));
    await tick();
    // Inserted on another board, the frame's copy takes its step along.
    await click('[data-action="home"]');
    await click('[data-action="new"]');
    await click('[data-action="templates"]');
    await click("[data-custom]");
    await new Promise((r) => setTimeout(r, 400));
    const inserted = await latest();
    const frame = inserted.items.find((i) => i.text === "Warm up");
    const steps = inserted.workshop?.agenda?.steps || [];
    assert.equal(steps.length, 1, JSON.stringify(inserted.workshop));
    assert.equal(steps[0].frame, frame.id);
    assert.equal(steps[0].minutes, 7);
    assert.equal(steps[0].text, "One word each.");
    // Undone and inserted again, the agenda holds one step, not one for
    // the frame undone too.
    await click('[data-action="undo"]');
    await click('[data-action="templates"]');
    await click("[data-custom]");
    await new Promise((r) => setTimeout(r, 400));
    const again = await latest();
    assert.deepEqual(
      again.workshop.agenda.steps.map((step) => step.frame),
      [again.items.find((i) => i.text === "Warm up").id],
    );
    // From the library home, it starts a new board with that agenda.
    await click('[data-action="home"]');
    await click('[data-action="templates"]');
    await click("[data-custom]");
    await new Promise((r) => setTimeout(r, 400));
    const fresh = await latest();
    assert.notEqual(fresh.id, inserted.id);
    assert.equal(fresh.workshop?.agenda?.steps?.[0]?.minutes, 7);
    assert.equal(
      fresh.workshop.agenda.steps[0].frame,
      fresh.items.find((i) => i.text === "Warm up").id,
    );
  } finally {
    await app.close();
  }
});

