test("a title longer than 200 code units is cut to a title the board can hold", async () => {
  const indexedDB = new IDBFactory();
  const app = await setup(undefined, { indexedDB });
  const { w, doc, click } = app;
  const stored = async () => {
    const db = await new Promise((resolve, reject) => {
      const request = indexedDB.open("whiteboard-v1");
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
    const rows = await new Promise((resolve, reject) => {
      const request = db.transaction("boards").objectStore("boards").getAll();
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
    db.close();
    return rows[0];
  };
  try {
    await click('[data-action="new"]');
    // A browser whose maxlength counts characters lets 101 emoji through,
    // which is 202 code units.
    const title = doc.querySelector("#board-title");
    title.value = "😀".repeat(101);
    title.dispatchEvent(new w.Event("change"));
    await new Promise((r) => setTimeout(r, 100));
    assert.equal(title.value, "😀".repeat(100));
    let row = await stored();
    assert.equal(row.title.length, 200);
    assert.doesNotThrow(() => validateBoard(row));
    await click('[data-action="home"]');
    await click("[data-more]");
    doc.querySelector("#rename").value = "é".repeat(150) + "😀".repeat(30);
    await click("#rename-board");
    await new Promise((r) => setTimeout(r, 100));
    row = await stored();
    assert.equal(row.title, "é".repeat(150) + "😀".repeat(25));
    assert.doesNotThrow(() => validateBoard(row));
  } finally {
    await app.close();
  }
});

test("a shared board's library card does not show content its workshop keeps from this person", async () => {
  const indexedDB = new IDBFactory();
  const rows = async (change) => {
    const db = await new Promise((resolve, reject) => {
      const request = indexedDB.open("whiteboard-v1");
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
    const store = db.transaction("boards", "readwrite").objectStore("boards");
    const [row] = await new Promise((resolve, reject) => {
      const request = store.getAll();
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
    change(row);
    await new Promise((resolve, reject) => {
      const request = store.put(row);
      request.onsuccess = resolve;
      request.onerror = () => reject(request.error);
    });
    db.close();
  };
  const first = await setup(undefined, { indexedDB });
  try {
    await first.click('[data-action="new"]');
    await new Promise((r) => setTimeout(r, 100));
    await first.click('[data-action="home"]');
  } finally {
    await first.close();
  }
  // The device's copy of a shared board holds everyone's content.
  const theirs = item("note", 0, 0, { text: "Bob's private idea" }),
    secret = item("note", 300, 0, { text: "Answer key" }),
    staged = item("frame", 0, 400, { w: 400, h: 300, text: "Reveal" }),
    inside = item("note", 20, 450, {
      text: "Next quarter's plan",
      parentId: staged.id,
    });
  await rows((row) => {
    row.shared = { server: "https://collab.test", room: "r", role: "editor" };
    row.items = [theirs, secret, staged, inside];
    row.workshop = {
      settings: {
        private: "r1",
        hide: [secret.id],
        stage: { frames: [staged.id], shown: 0 },
      },
      [contributionKey(theirs.id)]: { by: "bob", at: 1, round: "r1" },
    };
  });
  const native = Object.getPrototypeOf(createCanvas(1, 1).getContext("2d")),
    fillText = native.fillText,
    drawn = [];
  native.fillText = function (text, ...rest) {
    drawn.push(String(text));
    return fillText.call(this, text, ...rest);
  };
  const app = await setup(undefined, { indexedDB });
  try {
    for (let n = 0; n < 20 && !drawn.length; n++) await app.tick();
    const card = app.doc.querySelector(".board-card");
    assert.ok(card.querySelector("canvas[data-preview]"));
    assert.ok(drawn.length, "the preview was painted");
    const text = drawn.join(" ");
    for (const concealed of ["Bob's private", "Answer key", "Next quarter"])
      assert.doesNotMatch(text, new RegExp(concealed), text);
    assert.match(text, /Private note/);
    assert.match(card.textContent, /2 objects/);
  } finally {
    native.fillText = fillText;
    await app.close();
  }
});

