test("the headers show Sign in while signed out and the account once signed in", async () => {
  let signedIn = false;
  const app = await setup({
    env: "web",
    auth: {
      isSignedIn: () => signedIn,
      signIn: async () => {
        signedIn = true;
      },
      signOut: () => {
        signedIn = false;
      },
      getUser: async () => ({
        uuid: "u1",
        username: "alice",
        email: "alice@example.com",
      }),
    },
    fs: noCloudBoards(),
  });
  const { w, doc, click, tick } = app;
  try {
    const signIn = doc.querySelector(".library-top .account-signin");
    assert.ok(signIn, "The library header offers Sign in");
    assert.equal(signIn.textContent.trim(), "Sign in");
    assert.equal(doc.querySelector(".account-button"), null);
    // The library says where boards live while no one is signed in.
    assert.match(
      doc.querySelector(".sidebar-note").textContent,
      /Boards stay in this browser until you sign in\./,
    );
    assert.ok(doc.querySelector('.sidebar-note [data-action="sign-in"]'));
    signIn.focus();
    signIn.click();
    for (let n = 0; n < 40 && !doc.querySelector(".account-button"); n++)
      await tick();
    for (let n = 0; n < 40 && doc.querySelector(".sidebar-note"); n++)
      await tick();
    assert.equal(doc.querySelector(".sidebar-note"), null);
    assert.equal(
      doc.activeElement,
      doc.querySelector(".library-top .account-button"),
      "The keyboard stays on the account control while it loads",
    );
    for (let n = 0; n < 40 && doc.querySelector("[aria-busy]"); n++)
      await tick();
    const button = doc.querySelector(".library-top .account-button");
    assert.ok(button, "The header shows the account once signed in");
    assert.equal(
      doc.activeElement,
      button,
      "The keyboard stays on the account control once it has loaded",
    );
    assert.equal(doc.querySelector(".account-signin"), null);
    assert.equal(button.getAttribute("aria-haspopup"), "menu");
    assert.equal(button.getAttribute("aria-expanded"), "false");
    assert.match(button.getAttribute("aria-label"), /alice/);
    assert.equal(button.querySelector(".avatar").textContent, "A");
    assert.equal(
      doc.querySelector("#toast").textContent,
      "Signed in as alice.",
    );
    button.click();
    await tick();
    const menu = doc.querySelector(".library-top .account-menu");
    assert.ok(menu, "The avatar opens the account menu");
    assert.equal(menu.getAttribute("role"), "menu");
    assert.equal(
      doc.activeElement,
      menu.querySelector('[role="menuitem"]'),
      "Opening the menu focuses its first item",
    );
    assert.equal(button.getAttribute("aria-expanded"), "true");
    assert.match(menu.textContent, /alice/);
    assert.match(menu.textContent, /alice@example\.com/);
    // The name and email sit outside the menu items, so they describe it.
    const identity = doc.getElementById(menu.getAttribute("aria-describedby"));
    assert.ok(menu.contains(identity));
    assert.match(identity.textContent, /alice@example\.com/);
    assert.deepEqual(
      [...menu.querySelectorAll('[role="menuitem"]')].map((b) =>
        b.textContent.trim(),
      ),
      ["Sign out"],
    );
    w.eval(axe.source);
    const audit = await w.axe.run(doc.querySelector(".library-top"), {
      rules: { "color-contrast": { enabled: false } },
    });
    assert.deepEqual(
      Array.from(
        audit.violations,
        (v) => `${v.id}: ${v.nodes.map((n) => n.target).join(", ")}`,
      ),
      [],
    );
    menu.querySelector('[role="menuitem"]').focus();
    menu.dispatchEvent(
      new w.KeyboardEvent("keydown", { key: "Escape", bubbles: true }),
    );
    assert.equal(doc.querySelector(".account-menu"), null);
    assert.equal(button.getAttribute("aria-expanded"), "false");
    assert.equal(doc.activeElement, button, "Escape returns to the avatar");
    button.dispatchEvent(
      new w.KeyboardEvent("keydown", { key: "ArrowDown", bubbles: true }),
    );
    assert.equal(
      doc.activeElement,
      doc.querySelector('.account-menu [role="menuitem"]'),
      "Arrow down opens the menu on its first item",
    );
    doc.activeElement.dispatchEvent(
      new w.KeyboardEvent("keydown", { key: "ArrowUp", bubbles: true }),
    );
    assert.equal(doc.activeElement.textContent.trim(), "Sign out");
    doc
      .querySelector(".account-menu")
      .dispatchEvent(
        new w.KeyboardEvent("keydown", { key: "Escape", bubbles: true }),
      );
    await click('[data-action="new"]');
    const inEditor = doc.querySelector(".editor-header .account-button");
    assert.ok(inEditor, "The editor header shows the account too");
    inEditor.click();
    await tick();
    doc.querySelector('[data-account-action="sign-out"]').click();
    for (let n = 0; n < 40 && !doc.querySelector(".account-signin"); n++)
      await tick();
    assert.ok(
      doc.querySelector(".editor-header .account-signin"),
      "Signing out brings Sign in back without leaving the board",
    );
    assert.equal(
      doc.activeElement,
      doc.querySelector(".editor-header .account-signin"),
      "The keyboard moves to Sign in",
    );
    assert.ok(doc.querySelector("#canvas"));
    assert.equal(
      doc.querySelector("#toast").textContent,
      "Signed out. Your local boards are still available.",
    );
  } finally {
    await app.close();
  }
});
