test("PNG export contains actual raster bytes and board rendering uses Canvas", async () => {
  const app = await setup();
  try {
    await app.click('[data-template="brainstorm"]');
    // Opening a board can take more than a tick on a busy test machine.
    const settle = async (ready) => {
      for (let n = 0; n < 200 && !ready(); n++) await app.tick();
    };
    await settle(() => app.doc.querySelector("#canvas"));
    assert.equal(app.doc.querySelector("#canvas").tagName, "CANVAS");
    assert.equal(app.doc.querySelectorAll("#canvas svg").length, 0);
    // A title of only symbols still gives the file a name.
    const title = app.doc.querySelector("#board-title");
    title.value = "???";
    title.dispatchEvent(new app.w.Event("change"));
    await app.click('[data-action="export"]');
    app.doc.querySelector("#export-format").value = "png";
    app.doc
      .querySelector("dialog form")
      .dispatchEvent(
        new app.w.Event("submit", { bubbles: true, cancelable: true }),
      );
    await settle(() => app.downloads.length);
    assert.equal(app.downloads.length, 1);
    assert.equal(app.downloads[0].type, "image/png");
    assert.deepEqual(app.names, ["Whiteboard.png"]);
    assert.equal(
      app.doc.querySelector("#toast").textContent,
      "Export ready.",
      "The result is told once the dialog has closed",
    );
    const bytes = await new Promise((resolve) => {
      const reader = new app.w.FileReader();
      reader.onload = () => resolve(new Uint8Array(reader.result));
      reader.readAsArrayBuffer(app.downloads[0]);
    });
    assert.deepEqual([...bytes.slice(0, 8)], [137, 80, 78, 71, 13, 10, 26, 10]);
    // Vowel signs and accents typed as separate marks stay in the name.
    for (const name of ["नमस्ते दुनिया", "Réunion d’équipe"]) {
      title.value = name;
      title.dispatchEvent(new app.w.Event("change"));
      await app.click('[data-action="export"]');
      app.doc.querySelector("#export-format").value = "png";
      app.doc
        .querySelector("dialog form")
        .dispatchEvent(
          new app.w.Event("submit", { bubbles: true, cancelable: true }),
        );
      const count = app.names.length;
      await settle(() => app.names.length > count);
    }
    assert.deepEqual(app.names.slice(1), [
      "नमस्ते दुनिया.png",
      "Réunion d’équipe.png",
    ]);
  } finally {
    await app.close();
  }
});

function imageClipboard(app, write) {
  app.w.ClipboardItem = class {
    constructor(data) {
      this.data = data;
    }
    static supports(type) {
      return type === "image/png";
    }
  };
  Object.defineProperty(app.w.navigator, "clipboard", {
    configurable: true,
    value: { write },
  });
}
async function blobBytes(app, blob) {
  return new Promise((resolve, reject) => {
    const reader = new app.w.FileReader();
    reader.onload = () => resolve(Buffer.from(reader.result));
    reader.onerror = () => reject(reader.error);
    reader.readAsArrayBuffer(blob);
  });
}
async function pngCanvas(app, blob) {
  const bytes = await blobBytes(app, blob);
  const image = new NativeImage();
  await new Promise((resolve, reject) => {
    image.onload = resolve;
    image.onerror = reject;
    image.src = bytes;
  });
  const canvas = createCanvas(image.width, image.height);
  canvas.getContext("2d").drawImage(image, 0, 0);
  return canvas;
}

test("copy as image writes a real PNG of a locked frame and its contents without changing selection or history", async () => {
  const app = await setup();
  try {
    await app.click('[data-action="new"]');
    const frame = item("frame", 0, 0, {
      w: 400,
      h: 260,
      text: "Selected frame",
      locked: true,
    });
    const note = item("note", 60, 80, {
      w: 120,
      h: 100,
      parentId: frame.id,
      color: "#ff0000",
      text: "Included",
    });
    const outside = item("note", 600, 0, { text: "Exclude", color: "#0000ff" });
    dispatchTransfer(
      app,
      "paste",
      transferData(clipboardFormats([frame, note, outside])),
    );
    await app.click("#board-outline button");
    const selected = () =>
      [...app.doc.querySelectorAll('#board-outline [aria-pressed="true"]')].map(
        (b) => b.dataset.id,
      );
    const before = selected();
    const undo = app.doc.querySelector('[data-action="undo"]').disabled;
    const redo = app.doc.querySelector('[data-action="redo"]').disabled;
    let blob,
      writing = 0,
      clicked = false;
    imageClipboard(app, async ([entry]) => {
      assert.equal(
        clicked,
        true,
        "write is initiated in the user gesture, before rendering awaits fonts",
      );
      assert.deepEqual(Object.keys(entry.data), ["image/png"]);
      assert.equal(typeof entry.data["image/png"].then, "function");
      writing++;
      blob = await entry.data["image/png"];
    });
    clicked = true;
    app.doc.querySelector('[data-action="copy-image"]').click();
    clicked = false;
    await app.tick();
    assert.equal(writing, 1);
    assert.equal(blob.type, "image/png");
    const canvas = await pngCanvas(app, blob);
    assert.equal(canvas.width, 880);
    assert.equal(canvas.height, 600);
    assert.deepEqual(
      [...canvas.getContext("2d").getImageData(190, 330, 1, 1).data],
      [255, 0, 0, 255],
    );
    assert.deepEqual(
      [...canvas.getContext("2d").getImageData(4, 4, 1, 1).data],
      [255, 255, 255, 255],
    );
    assert.deepEqual(selected(), before);
    assert.equal(app.doc.querySelector('[data-action="undo"]').disabled, undo);
    assert.equal(app.doc.querySelector('[data-action="redo"]').disabled, redo);
    assert.match(app.doc.querySelector("#toast").textContent, /Image copied/);
    // Paste the actual clipboard PNG back through the existing file-transfer path.
    dispatchTransfer(
      app,
      "paste",
      transferData({}, [
        new app.w.File([blob], "Selection.png", { type: "image/png" }),
      ]),
    );
    await app.tick();
    await app.tick();
    assert.match(app.doc.querySelector("#board-outline").textContent, /Image:/);
    await app.click('[data-action="undo"]');
    assert.equal(app.doc.querySelectorAll("#board-outline button").length, 3);
  } finally {
    await app.close();
  }
});

test("copy image snapshots the requested objects, ignores repeat requests, caps output, and preserves text-field shortcuts", async () => {
  const app = await setup();
  let release;
  try {
    await app.click('[data-action="new"]');
    dispatchTransfer(
      app,
      "paste",
      transferData(
        clipboardFormats([
          item("rect", 0, 0, { w: 10000, h: 100, color: "#ff0000" }),
        ]),
      ),
    );
    Object.defineProperty(app.doc, "fonts", {
      value: {
        ready: new Promise((r) => {
          release = r;
        }),
      },
    });
    let calls = 0,
      blob;
    imageClipboard(app, async ([entry]) => {
      calls++;
      blob = await entry.data["image/png"];
    });
    const key = (target, extra = {}) => {
      const event = new app.w.KeyboardEvent("keydown", {
        key: "C",
        ctrlKey: true,
        shiftKey: true,
        bubbles: true,
        cancelable: true,
        ...extra,
      });
      target.dispatchEvent(event);
      return event.defaultPrevented;
    };
    assert.equal(key(app.doc.querySelector("#board-title")), false);
    assert.equal(calls, 0);
    assert.equal(key(app.doc.querySelector("#canvas")), true);
    assert.equal(calls, 1);
    key(app.doc.querySelector("#canvas"), { repeat: true });
    await app.click('[data-action="copy-image"]');
    assert.equal(calls, 1);
    await app.click('[data-color="#dce5f7"]');
    release();
    await app.tick();
    const image = await pngCanvas(app, blob);
    assert.equal(image.width, 4096);
    assert.ok(image.height <= 4096);
    assert.deepEqual(
      [...image.getContext("2d").getImageData(100, 25, 1, 1).data],
      [255, 0, 0, 255],
      "later recoloring does not change the image requested earlier",
    );
    assert.match(app.doc.querySelector("#toast").textContent, /Image copied/);
  } finally {
    release?.();
    await app.close();
  }
});

test("blocked image copy provides a PNG preview, a fresh-gesture retry, download, and translated accessible controls", async () => {
  const app = await setup();
  try {
    await app.click('[data-action="new"]');
    dispatchTransfer(
      app,
      "paste",
      transferData(
        clipboardFormats([item("note", 0, 0, { text: "Clipboard fallback" })]),
      ),
    );
    let calls = 0;
    imageClipboard(app, async ([entry]) => {
      calls++;
      if (calls === 1)
        throw new app.w.DOMException("Denied", "NotAllowedError");
      assert.equal(
        entry.data["image/png"].type,
        "image/png",
        "retry reuses a prepared Blob",
      );
    });
    const revoked = [];
    app.w.URL.revokeObjectURL = (url) => revoked.push(url);
    await app.click('[data-action="copy-image"]');
    assert.ok(app.doc.querySelector(".image-copy-preview img"));
    assert.equal(app.downloads[0].type, "image/png");
    const audit = await axe.run(app.doc.querySelector("dialog"), {
      rules: { "color-contrast": { enabled: false } },
    });
    assert.deepEqual(
      audit.violations.map((v) => v.id),
      [],
    );
    await app.click("#retry-image-copy");
    assert.equal(calls, 2);
    assert.equal(app.doc.querySelector("dialog"), null);
    assert.equal(revoked.length, 1);
    app.w.ClipboardItem = undefined;
    app.doc.querySelector("#language").value = "fr";
    app.doc.querySelector("#language").dispatchEvent(new app.w.Event("change"));
    await app.click("#board-outline button");
    await app.click('[data-action="more-tools"]');
    await app.click('[data-feature="copy-image"]');
    assert.equal(
      app.doc.querySelector("dialog").getAttribute("aria-label"),
      "Copier en tant qu’image",
    );
    assert.equal(app.doc.querySelector("#retry-image-copy"), null);
    assert.match(
      app.doc.querySelector("#image-copy-status").textContent,
      /Votre navigateur/,
    );
    await app.click("#download-selection-image");
    assert.equal(app.downloads.at(-1).type, "image/png");
    assert.equal(app.doc.querySelector("dialog"), null);
    assert.equal(revoked.length, 2);
  } finally {
    await app.close();
  }
});

test("leaving the board cancels a pending image copy; raster failures do not claim success or disturb the board", async () => {
  const app = await setup();
  let release;
  try {
    await app.click('[data-action="new"]');
    dispatchTransfer(
      app,
      "paste",
      transferData(clipboardFormats([item("note", 0, 0, { text: "Keep me" })])),
    );
    Object.defineProperty(app.doc, "fonts", {
      value: {
        ready: new Promise((r) => {
          release = r;
        }),
      },
    });
    let cancelled = false;
    imageClipboard(app, async ([entry]) => {
      try {
        await entry.data["image/png"];
      } catch (error) {
        cancelled = true;
        throw error;
      }
    });
    await app.click('[data-action="copy-image"]');
    await app.click('[data-action="home"]');
    release();
    await app.tick();
    assert.equal(cancelled, true);
    assert.equal(app.doc.querySelector("dialog"), null);
    await app.click("[data-open]");
    await app.click("#board-outline button");
    app.w.HTMLCanvasElement.prototype.toBlob = (callback) => callback(null);
    await app.click('[data-action="copy-image"]');
    assert.match(
      app.doc.querySelector("#toast").textContent,
      /Could not prepare/,
    );
    assert.equal(app.doc.querySelector("dialog"), null);
    assert.equal(app.doc.querySelectorAll("#board-outline button").length, 1);
  } finally {
    release?.();
    await app.close();
  }
});
test("dragging with a note, text, shape or frame tool draws it at that size, and a click places the default", async () => {
  const app = await setup();
  const { w, doc, click, tick } = app;
  const canvas = () => doc.querySelector("#canvas");
  const pointer = (type, x, y, extra = {}) =>
    canvas().dispatchEvent(
      new w.MouseEvent(type, {
        bubbles: true,
        cancelable: true,
        clientX: x,
        clientY: y,
        button: 0,
        ...extra,
      }),
    );
  const copy = () => {
    const data = transferData();
    dispatchTransfer(app, "copy", data);
    return JSON.parse(data.getData(CLIPBOARD_TYPE)).items;
  };
  const count = () => doc.querySelectorAll("#board-outline [data-id]").length;
  const key = (key, options = {}) =>
    canvas().dispatchEvent(
      new w.KeyboardEvent("keydown", {
        key,
        bubbles: true,
        cancelable: true,
        ...options,
      }),
    );
  try {
    await click('[data-action="new"]');
    canvas().getBoundingClientRect = () => ({
      left: 0,
      top: 0,
      width: 1000,
      height: 800,
    });
    await click('[data-action="toggle-snapping"]');
    // A drag draws the rectangle from corner to corner, in one undo step.
    await click('[data-action="tool-rect"]');
    pointer("pointerdown", 100, 100);
    pointer("pointermove", 104, 103);
    assert.equal(count(), 0, "A small movement is still a press");
    pointer("pointermove", 300, 250);
    assert.equal(count(), 0, "Nothing is added before the release");
    pointer("pointerup", 300, 250);
    await tick();
    assert.equal(count(), 1);
    let [rect] = copy();
    assert.equal(rect.type, "rect");
    assert.deepEqual([rect.w, rect.h].map(Math.round), [200, 150]);
    // Positions are read against the first rectangle's, as the view offsets.
    const origin = { x: rect.x - 100, y: rect.y - 100 };
    const at = (i) =>
      [i.x - origin.x, i.y - origin.y, i.w, i.h].map(Math.round);
    assert.equal(
      doc
        .querySelector('[data-action="tool-select"]')
        .getAttribute("aria-pressed"),
      "true",
      "The select tool follows, as after a click",
    );
    await click('[data-action="undo"]');
    assert.equal(count(), 0, "One undo removes the drawn rectangle");
    // Dragging up and left, with Shift, draws a square ending at the press.
    await click('[data-action="tool-ellipse"]');
    pointer("pointerdown", 500, 500);
    pointer("pointermove", 380, 440, { shiftKey: true });
    pointer("pointerup", 380, 440, { shiftKey: true });
    await tick();
    [rect] = copy();
    assert.equal(rect.type, "ellipse");
    assert.deepEqual(at(rect), [380, 380, 120, 120]);
    // Escape during the drag adds nothing and leaves the history alone.
    await click('[data-action="tool-rect"]');
    pointer("pointerdown", 600, 100);
    pointer("pointermove", 700, 200);
    key("Escape");
    pointer("pointerup", 700, 200);
    await tick();
    assert.equal(count(), 1);
    assert.equal(doc.querySelector('[data-action="redo"]').disabled, true);
    // A sticky note drawn by dragging opens for text at the dragged size.
    await click('[data-action="tool-note"]');
    pointer("pointerdown", 100, 400);
    pointer("pointermove", 400, 520);
    pointer("pointerup", 400, 520);
    await tick();
    assert.equal(count(), 2);
    assert.ok(doc.querySelector("#canvas-text-editor"), "The note is editing");
    await click('[data-action="finish-text"]');
    const note = copy()[0];
    assert.equal(note.type, "note");
    assert.deepEqual(at(note), [100, 400, 300, 120]);
    key("Delete");
    assert.equal(count(), 1);
    // Dragged text takes the width; its height follows the text as before.
    await click('[data-action="tool-text"]');
    pointer("pointerdown", 100, 600);
    pointer("pointermove", 520, 700);
    pointer("pointerup", 520, 700);
    await tick();
    assert.equal(count(), 2);
    assert.ok(doc.querySelector("#canvas-text-editor"), "The text is editing");
    await click('[data-action="finish-text"]');
    const text = copy()[0];
    assert.equal(text.type, "text");
    assert.equal(text.autoHeight, true);
    assert.deepEqual(at(text).slice(0, 3), [100, 600, 420]);
    assert.ok(text.h < 100, `The height follows one line of text (${text.h})`);
    key("Delete");
    assert.equal(count(), 1);
    // A click still places a rectangle of the default size, centred on
    // the point as in Miro.
    await click('[data-action="tool-rect"]');
    pointer("pointerdown", 600, 100);
    pointer("pointerup", 600, 100);
    await tick();
    assert.equal(count(), 2);
    assert.deepEqual(at(copy()[0]), [505, 20, 190, 160]);
    key("Delete");
    // A press that wobbled past the drag threshold, but not to the smallest
    // size a drag can draw, places the default too, not a 24-unit blob.
    await click('[data-action="tool-rect"]');
    pointer("pointerdown", 600, 100);
    pointer("pointermove", 612, 108);
    pointer("pointerup", 612, 108);
    await tick();
    assert.equal(count(), 2);
    assert.deepEqual(at(copy()[0]), [505, 20, 190, 160]);
    key("Delete");
    await click('[data-action="tool-text"]');
    pointer("pointerdown", 600, 100);
    pointer("pointermove", 640, 110);
    pointer("pointerup", 640, 110);
    await tick();
    await click('[data-action="finish-text"]');
    assert.equal(count(), 2);
    assert.deepEqual(at(copy()[0]).slice(0, 3), [600, 100, 280]);
    key("Delete");
    // A drag past that in one direction keeps the size dragged.
    await click('[data-action="tool-rect"]');
    pointer("pointerdown", 600, 100);
    pointer("pointermove", 700, 110);
    pointer("pointerup", 700, 110);
    await tick();
    assert.deepEqual(at(copy()[0]), [600, 100, 100, 24]);
    key("Delete");
    await click('[data-action="tool-rect"]');
    pointer("pointerdown", 600, 100);
    pointer("pointerup", 600, 100);
    await tick();
    assert.equal(count(), 2);
    // A frame drawn around objects takes them in; one drawn elsewhere is empty.
    await click('[data-action="tool-frame"]');
    pointer("pointerdown", 350, 300);
    pointer("pointermove", 850, 50);
    pointer("pointerup", 850, 50);
    await tick();
    assert.equal(count(), 3);
    const all = JSON.parse(
      (() => {
        key("a", { ctrlKey: true });
        const data = transferData();
        dispatchTransfer(app, "copy", data);
        return data.getData(CLIPBOARD_TYPE);
      })(),
    ).items;
    const frame = all.find((i) => i.type === "frame");
    assert.deepEqual(at(frame), [350, 50, 500, 250]);
    const ellipse = all.find((i) => i.type === "ellipse");
    assert.equal(
      ellipse.parentId,
      undefined,
      "The ellipse's middle is outside",
    );
    const rectangle = all.find((i) => i.type === "rect");
    assert.equal(
      rectangle.parentId,
      frame.id,
      "The rectangle's middle is inside",
    );
    await click('[data-action="undo"]');
    key("a", { ctrlKey: true });
    assert.ok(
      copy().every((i) => !i.parentId),
      "One undo frees the rectangle",
    );
    // A frame drawn tightly around a shape grows upward to keep its title
    // clear of the shape, which would otherwise hide it.
    key("Delete");
    await click('[data-action="tool-rect"]');
    pointer("pointerdown", 400, 400);
    pointer("pointermove", 600, 500);
    pointer("pointerup", 600, 500);
    await tick();
    await click('[data-action="tool-frame"]');
    pointer("pointerdown", 390, 390);
    pointer("pointermove", 700, 600);
    pointer("pointerup", 700, 600);
    await tick();
    key("a", { ctrlKey: true });
    const tight = copy(),
      box = tight.find((i) => i.type === "rect"),
      section = tight.find((i) => i.type === "frame");
    assert.equal(box.parentId, section.id);
    assert.ok(
      box.y - section.y >= 16 + 19 * 1.35,
      `The title fits above the shape (${box.y - section.y})`,
    );
    assert.equal(section.x, box.x - 10);
    assert.equal(
      section.y + section.h,
      box.y + 200,
      "The bottom stays where it was drawn",
    );
  } finally {
    await app.close();
  }
});

