function pendingSignInPuter() {
  let signedIn = false,
    release = null;
  const writes = [];
  return {
    writes,
    release: () => release?.(),
    get pending() {
      return !!release;
    },
    puter: {
      env: "web",
      auth: {
        isSignedIn: () => signedIn,
        signIn: async () => {
          await new Promise((r) => (release = r));
          release = null;
          signedIn = true;
        },
        signOut: () => (signedIn = false),
        getUser: async () => ({ uuid: "u1", username: "alice", email: "a@x" }),
      },
      fs: {
        read: async () => {
          throw { code: "subject_does_not_exist" };
        },
        readdir: async () => [],
        write: async (path, data) => {
          writes.push({ path, data: JSON.parse(data) });
        },
      },
    },
  };
}

test("Save to Puter saves the board it was asked on, however the sign-in that it waited for ended", async () => {
  // Two sign-ins left open: one ended from the library, one from another board.
  for (const openAnother of [false, true]) {
    const stub = pendingSignInPuter();
    const app = await setup(stub.puter);
    const { w, doc, click, tick } = app;
    const save = () =>
      doc.querySelector("#canvas").dispatchEvent(
        new w.KeyboardEvent("keydown", {
          key: "s",
          ctrlKey: true,
          bubbles: true,
          cancelable: true,
        }),
      );
    const rename = (title) => {
      const field = doc.querySelector("#board-title");
      field.value = title;
      field.dispatchEvent(new w.Event("change", { bubbles: true }));
    };
    const uploaded = () =>
      stub.writes
        .filter(
          (x) => x.path.endsWith(".json") && !x.path.endsWith("catalog.json"),
        )
        .map((x) => x.data.title);
    try {
      await click('[data-action="new"]');
      rename("Board A");
      await tick();
      save();
      await tick();
      assert.equal(stub.pending, true, "The sign-in window is open");
      await click('[data-action="home"]');
      if (openAnother) {
        await click('[data-action="new"]');
        rename("Board B");
        await tick();
      }
      stub.release();
      for (let n = 0; n < 10; n++) await tick();
      assert.doesNotMatch(doc.querySelector("#toast").textContent, /null/);
      assert.deepEqual(uploaded(), ["Board A"]);
    } finally {
      await app.close();
    }
  }
});

