test("an inserted template goes beside the board's content instead of covering it", async () => {
  const app = await setup();
  try {
    const { click, tick } = app;
    await rotationFixture(app, [
      item("note", 0, 0, { text: "My work" }),
      item("note", 600, 300, { text: "More work" }),
    ]);
    const insert = async (id) => {
      await click('[data-action="more-tools"]');
      await click('[data-feature="templates"]');
      await click(`[data-use="${id}"]`);
      await tick();
    };
    const overlap = (a, b) =>
      a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h;
    const box = (list) => {
      const x = Math.min(...list.map((i) => i.x)),
        y = Math.min(...list.map((i) => i.y));
      return {
        x,
        y,
        w: Math.max(...list.map((i) => i.x + i.w)) - x,
        h: Math.max(...list.map((i) => i.y + i.h)) - y,
      };
    };
    const items = async () =>
      (await storedBoards(app)).find((b) =>
        b.items.some((i) => i.text === "My work"),
      ).items;
    await insert("retro-msg");
    const once = await items();
    const mine = once.filter((i) => /work$/.test(i.text || "")),
      first = once.filter((i) => !mine.includes(i));
    assert.ok(first.length > 5);
    assert.ok(!overlap(box(first), box(mine)), "My work stays in view");
    await insert("retro-msg");
    const twice = await items(),
      second = twice.filter((i) => !once.some((o) => o.id === i.id));
    assert.equal(second.length, first.length);
    assert.ok(!overlap(box(second), box(first)), "Copies do not stack");
  } finally {
    await app.close();
  }
});

