test("a held arrow key moves objects as one undo step", async () => {
  const app = await setup();
  const { w, doc, click } = app;
  try {
    await click('[data-action="new"]');
    dispatchTransfer(
      app,
      "paste",
      transferData(clipboardFormats([item("rect", 0, 0, { text: "Held" })])),
    );
    await click('[data-action="tool-note"]');
    await click('[data-action="tool-select"]');
    const count = () => doc.querySelectorAll("#board-outline button").length;
    const [rect] = allClipboard(app);
    const key = (extra = {}) =>
      doc.querySelector("#canvas").dispatchEvent(
        new w.KeyboardEvent("keydown", {
          key: "ArrowRight",
          bubbles: true,
          cancelable: true,
          ...extra,
        }),
      );
    // The board is written for the press and once the key is released,
    // not on each of the repeats between.
    const { put } = IDBObjectStore.prototype;
    let writes = 0;
    IDBObjectStore.prototype.put = function (...args) {
      if (this.name === "boards") writes++;
      return put.apply(this, args);
    };
    try {
      key();
      for (let n = 0; n < 99; n++) key({ repeat: true });
      await app.tick();
      assert.equal(writes, 1);
      doc
        .querySelector("#canvas")
        .dispatchEvent(
          new w.KeyboardEvent("keyup", { key: "ArrowRight", bubbles: true }),
        );
      await app.tick();
      assert.equal(writes, 2);
      assert.equal(
        (await storedBoards(app)).find((b) => b.items.length)?.items[0].x,
        rect.x + 100,
      );
    } finally {
      IDBObjectStore.prototype.put = put;
    }
    assert.equal(selectedClipboard(app)[0].x, rect.x + 100);
    // Pressed again, it is a step of its own.
    key();
    key({ repeat: true });
    assert.equal(selectedClipboard(app)[0].x, rect.x + 102);
    await click('[data-action="undo"]');
    await click("#board-outline button");
    assert.equal(selectedClipboard(app)[0].x, rect.x + 100);
    await click('[data-action="undo"]');
    await click("#board-outline button");
    assert.equal(selectedClipboard(app)[0].x, rect.x);
    // The paste before the moves can still be undone.
    await click('[data-action="undo"]');
    assert.equal(count(), 0);
    await click('[data-action="redo"]');
    await click('[data-action="redo"]');
    await click("#board-outline button");
    assert.equal(selectedClipboard(app)[0].x, rect.x + 100);
    // A repeat after an undo starts a new step rather than joining one.
    await click('[data-action="undo"]');
    await click("#board-outline button");
    key({ repeat: true });
    await click('[data-action="undo"]');
    await click("#board-outline button");
    assert.equal(selectedClipboard(app)[0].x, rect.x);
  } finally {
    await app.close();
  }
});

test("a held resize shortcut grows the selection as one undo step and stops at the board's edge", async () => {
  const app = await setup();
  const { w, doc, click } = app;
  try {
    await click('[data-action="new"]');
    dispatchTransfer(
      app,
      "paste",
      transferData(
        clipboardFormats([item("rect", 0, 0, { w: 200, h: 100, text: "A" })]),
      ),
    );
    const [rect] = selectedClipboard(app);
    const key = (extra = {}) =>
      doc.querySelector("#canvas").dispatchEvent(
        new w.KeyboardEvent("keydown", {
          key: "+",
          code: "Equal",
          ctrlKey: true,
          altKey: true,
          shiftKey: true,
          bubbles: true,
          cancelable: true,
          ...extra,
        }),
      );
    key();
    for (let n = 0; n < 199; n++) key({ repeat: true });
    const [grown] = selectedClipboard(app);
    assert.ok(grown.w > 100000, "The held key keeps growing it");
    for (const [start, size] of [
      [grown.x, grown.w],
      [grown.y, grown.h],
    ])
      assert.ok(
        Math.abs(start) <= 1e6 && Math.abs(start + size) <= 1e6,
        "It stays on the board",
      );
    await click('[data-action="undo"]');
    await click("#board-outline button");
    const [undone] = selectedClipboard(app);
    assert.deepEqual([undone.w, undone.h], [rect.w, rect.h]);
    // The paste before the resize can still be undone.
    await click('[data-action="undo"]');
    assert.equal(doc.querySelectorAll("#board-outline button").length, 0);
  } finally {
    await app.close();
  }
});

