    pointer("pointerdown", at, { shiftKey: true });
    pointer("pointermove", { x: at.x + 6, y: at.y + 4 }, { shiftKey: true });
    pointer("pointermove", { x: at.x + 12, y: at.y }, { shiftKey: true });
    pointer("pointerup", { x: at.x + 12, y: at.y }, { shiftKey: true });
    await app.tick();
