test("undo and redo with empty history leave recovery versions untouched", async () => {
  const app = await setup();
  try {
    const { doc, w } = app;
    await app.click('[data-action="new"]');
    const canvas = doc.querySelector("#canvas");
    const key = (k, extra = {}) =>
      canvas.dispatchEvent(
        new w.KeyboardEvent("keydown", { key: k, bubbles: true, ...extra }),
      );
    const revisions = async () => {
      const db = await new Promise((resolve) => {
        const request = w.indexedDB.open("whiteboard-v1", 3);
        request.onsuccess = () => resolve(request.result);
      });
      return new Promise((resolve) => {
        const request = db
          .transaction("revisions")
          .objectStore("revisions")
          .getAll();
        request.onsuccess = () => {
          db.close();
          resolve(request.result.length);
        };
      });
    };
    for (let n = 0; n < 2; n++) {
      key("r");
      await app.tick();
      key("Escape");
      await app.tick();
    }
    for (let n = 0; n < 2; n++) key("z", { ctrlKey: true });
    await app.tick();
    const before = await revisions();
    for (let n = 0; n < 10; n++) key("z", { ctrlKey: true, repeat: true });
    await app.tick();
    assert.equal(await revisions(), before);
    for (let n = 0; n < 2; n++) key("z", { ctrlKey: true, shiftKey: true });
    await app.tick();
    const redone = await revisions();
    for (let n = 0; n < 10; n++)
      key("z", { ctrlKey: true, shiftKey: true, repeat: true });
    await app.tick();
    assert.equal(await revisions(), redone);
    assert.equal(doc.querySelectorAll("#board-outline button").length, 2);
  } finally {
    await app.close();
  }
});

test("undo on a shared board waits for an edit still on its way in", async () => {
  const env = environment();
  env.service.now = () => Date.now();
  env.dropEvents = true;
  const room = crypto.randomUUID();
  const seed = new SharedDocument();
  seed.commit({
    version: 1,
    id: room,
    title: "Shared",
    items: [
      item("note", 0, 0, { text: "A" }),
      item("note", 400, 0, { text: "B" }),
    ],
  });
  await env.service.call(owner, {
    op: "create",
    room,
    update: encode(seed.update()),
  });
  seed.destroy();
  let gate = null;
  const app = await setup(env.sdk(owner), { digestGate: () => gate });
  try {
    const { doc, w } = app;
    await app.click('[data-action="join-shared"]');
    doc.querySelector("#join-link").value =
      `https://whiteboard.test/#server=https%3A%2F%2Fwhiteboard-test.puter.work&board=${room}`;
    doc
      .querySelector("#join-link")
      .closest("form")
      .dispatchEvent(
        new w.Event("submit", { bubbles: true, cancelable: true }),
      );
    // The join dialog closes once the board is stored on the device, which
    // on a slow machine is after the board shows; until then the keyboard
    // belongs to the dialog and Delete reaches no object.
    for (
      let n = 0;
      n < 400 &&
      (doc.querySelector("#join-link") ||
        !doc.querySelector("#save-state")?.textContent.startsWith("Saved ·"));
      n++
    )
      await app.tick();
    const texts = () =>
      [...doc.querySelectorAll("#board-outline [data-id]")].map((b) =>
        b.textContent.trim(),
      );
    const remove = async (text) => {
      [...doc.querySelectorAll("#board-outline [data-id]")]
        .find((b) => b.textContent.includes(text))
        .click();
      await app.tick();
      doc
        .querySelector("#canvas")
        .dispatchEvent(
          new w.KeyboardEvent("keydown", { key: "Delete", bubbles: true }),
        );
    };
    // The device is slow to store each edit, so the second deletion is
    // still on its way into the shared document when Ctrl+Z is pressed.
    let release;
    gate = new Promise((resolve) => (release = resolve));
    await remove("A");
    await remove("B");
    await new Promise((resolve) => setTimeout(resolve, 30));
    doc.querySelector("#canvas").dispatchEvent(
      new w.KeyboardEvent("keydown", {
        key: "z",
        ctrlKey: true,
        bubbles: true,
      }),
    );
    await new Promise((resolve) => setTimeout(resolve, 30));
    gate = null;
    release();
    for (let n = 0; n < 40; n++) await app.tick();
    assert.deepEqual(texts(), ["Sticky note: B"]);
  } finally {
    await app.close();
  }
});

test("text being typed when the page is killed is put back when the board opens again", async () => {
  const app = await setup();
  let reopened;
  try {
    const { doc, w } = app;
    await app.click('[data-action="new"]');
    doc
      .querySelector("#canvas")
      .dispatchEvent(
        new w.KeyboardEvent("keydown", { key: "n", bubbles: true }),
      );
    for (let n = 0; n < 20 && !doc.querySelector("#canvas-text-editor"); n++)
      await app.tick();
    const input = doc.querySelector("#canvas-text-editor");
    assert.ok(input, "a new sticky note opens for typing");
    input.value = "Minutes of the meeting";
    input.dispatchEvent(new w.Event("input", { bubbles: true }));
    await new Promise((resolve) => setTimeout(resolve, 600));
    await app.tick();
    // The tab is killed while typing: nothing ends the edit, so the board
    // in storage still holds the note without its text.
    const draft = w.localStorage.getItem("whiteboard-text-draft");
    assert.ok(draft, "the text is kept on the device as it is typed");
    reopened = await setup(undefined, {
      url: w.location.href,
      indexedDB: w.indexedDB,
      preferences: { "whiteboard-text-draft": draft },
    });
    for (
      let n = 0;
      n < 50 && !reopened.doc.querySelector("#board-outline [data-id]");
      n++
    )
      await reopened.tick();
    assert.match(
      reopened.doc.querySelector("#board-outline [data-id]").textContent,
      /Minutes of the meeting/,
    );
    assert.match(reopened.doc.querySelector("#toast").textContent, /put back/);
    assert.equal(
      reopened.w.localStorage.getItem("whiteboard-text-draft"),
      null,
    );
    // Ending an edit leaves no draft behind.
    input.dispatchEvent(
      new w.KeyboardEvent("keydown", { key: "Escape", bubbles: true }),
    );
    assert.equal(w.localStorage.getItem("whiteboard-text-draft"), null);
  } finally {
    await reopened?.close();
    await app.close();
  }
});

test("local undo cannot change a shared board that is not connected", async () => {
  const env = environment(),
    puter = env.sdk(owner);
  const build = "faceb00cfaceb00c";
  await puter.kv.set("whiteboard-collaboration-worker-v1", {
    name: "whiteboard-test",
    server: "https://whiteboard-test.puter.work",
    path: "whiteboard/whiteboard-worker.js",
    build,
    builtAt: 200,
  });
  const exec = puter.workers.exec;
  puter.workers.exec = async (url, options) =>
    url.endsWith("/health") ? Response.json({ build }) : exec(url, options);
  const app = await setup(puter);
  app.w.fetch = async () =>
    new Response(`/* whiteboard-worker build=${build} at=200 */`);
  try {
    const { doc, w } = app;
    const settle = async (ready, what) => {
      for (let n = 0; n < 200 && !ready(); n++) await app.tick();
      assert.ok(ready(), what);
    };
    await app.click('[data-action="new"]');
    const canvas = () => doc.querySelector("#canvas");
    const key = (k, extra = {}) =>
      canvas().dispatchEvent(
        new w.KeyboardEvent("keydown", { key: k, bubbles: true, ...extra }),
      );
    key("r");
    await app.tick();
    key("Escape");
    await app.tick();
    await app.click('[data-action="share"]');
    await confirmShare(app);
    await settle(() => doc.querySelector("#share-link"), "The board is shared");
    doc.querySelector("dialog[open]").close();
    await app.click('[data-action="home"]');
    // Opened again while the board cannot be joined, the shared board is
    // here but not connected.
    const call = env.service.call.bind(env.service);
    env.service.call = async (user, input) => {
      if (input.op === "join")
        throw Object.assign(Error("Try again later."), { status: 503 });
      return call(user, input);
    };
    await app.click("[data-open]");
    await settle(
      () =>
        /Cannot reach the shared board/.test(
          doc.querySelector("#save-state")?.textContent,
        ),
      "The connection fails",
    );
    assert.equal(doc.querySelector("#board-title").disabled, true);
    doc.querySelector("#toast").textContent = "";
    key("z", { ctrlKey: true });
    await app.tick();
    assert.equal(doc.querySelectorAll("#board-outline [data-id]").length, 1);
    assert.doesNotMatch(
      doc.querySelector("#toast").textContent,
      /Saved|Undone/,
      "A refused undo does not report success",
    );
    // Refused edits do not report success.
    await app.click("#board-outline [data-id]");
    doc.querySelector("#toast").textContent = "";
    key("L", { ctrlKey: true, shiftKey: true });
    await app.tick();
    assert.equal(
      doc.querySelector("#toast").textContent,
      "Cannot reach the shared board. It is view only until it reconnects.",
    );
    assert.equal(allClipboard(app)[0].locked, undefined);
  } finally {
    await app.close();
  }
});
test("tool shortcuts, drawing, and quick-add respect the 5,000-object limit", async () => {
  const indexedDB = new IDBFactory();
  let app = await setup(undefined, { indexedDB });
  const b = {
    version: 1,
    id: crypto.randomUUID(),
    title: "Full",
    updated: Date.now(),
    items: Array.from({ length: 5000 }, (_, n) =>
      item("rect", (n % 100) * 30, Math.floor(n / 100) * 30, { w: 20, h: 20 }),
    ),
  };
  const database = await new Promise((resolve) => {
    const request = app.w.indexedDB.open("whiteboard-v1", 3);
    request.onsuccess = () => resolve(request.result);
  });
  await new Promise((resolve) => {
    const transaction = database.transaction("boards", "readwrite");
    transaction.objectStore("boards").put(b);
    transaction.oncomplete = resolve;
  });
  database.close();
  await app.close();
  app = await setup(undefined, { indexedDB });
  try {
    const { doc, w } = app;
    // A large board writes its object list while idle; count once it is whole.
    const outlined = async () => {
      const outline = doc.querySelector("#board-outline");
      for (let n = 0; n < 200 && outline.getAttribute("aria-busy"); n++)
        await app.tick();
      return outline.querySelectorAll("button").length;
    };
    for (let n = 0; n < 40 && !doc.querySelector(`[data-open="${b.id}"]`); n++)
      await app.tick();
    await app.click(`[data-open="${b.id}"]`);
    for (let n = 0; n < 200 && !doc.querySelector("#canvas"); n++)
      await app.tick();
    const canvas = doc.querySelector("#canvas");
    for (const key of ["n", "r"])
      canvas.dispatchEvent(
        new w.KeyboardEvent("keydown", { key, bubbles: true }),
      );
    await app.tick();
    assert.equal(doc.querySelector("#canvas-text-editor"), null);
    assert.equal(await outlined(), 5000);
    assert.equal(
      doc.querySelector("#toast").textContent,
      "A board can contain at most 5,000 objects.",
    );
    // Drawing a line or a pen stroke is refused the same way.
    canvas.getBoundingClientRect = () => ({
      left: 0,
      top: 0,
      width: 1000,
      height: 800,
    });
    const pointer = (type, x, y) =>
      canvas.dispatchEvent(
        new w.MouseEvent(type, {
          bubbles: true,
          button: 0,
          clientX: x,
          clientY: y,
        }),
      );
    for (const tool of ["pen", "arrow"]) {
      doc.querySelector("#toast").textContent = "";
      await app.click(`[data-action="tool-${tool}"]`);
      pointer("pointerdown", 100, 100);
      pointer("pointermove", 200, 160);
      pointer("pointerup", 200, 160);
      await app.tick();
      assert.equal(await outlined(), 5000);
      assert.equal(
        doc.querySelector("#toast").textContent,
        "A board can contain at most 5,000 objects.",
      );
    }
    // So is adding a table, which keeps its dialog open.
    doc.querySelector("#toast").textContent = "";
    await app.click('[data-action="more-tools"]');
    await app.click('[data-feature="table"]');
    doc.querySelector("dialog[open] form").requestSubmit();
    await app.tick();
    assert.equal(await outlined(), 5000);
    assert.equal(
      doc.querySelector("#toast").textContent,
      "A board can contain at most 5,000 objects.",
    );
    assert.ok(doc.querySelector("dialog[open] form"));
  } finally {
    await app.close();
  }
});

test("a table added from More tools sits in the middle of the view, as a new note does, or beside what is there", async () => {
  const app = await setup();
  try {
    const { doc } = app;
    const { key } = await rotationFixture(app, [
      item("rect", 4000, 4000, { w: 10, h: 10 }),
    ]);
    // The dropped object is selected; removing it leaves the view empty.
    key("Delete");
    await app.tick();
    const addTable = async () => {
      await app.click('[data-action="more-tools"]');
      await app.click('[data-feature="table"]');
      doc.querySelector("dialog[open] form").requestSubmit();
      await app.tick();
    };
    const latest = async () =>
      (await storedBoards(app)).find((b) => b.items.length).items;
    const middle = (i) => [i.x + i.w / 2, i.y + i.h / 2].map(Math.round);
    await addTable();
    const table = (await latest()).find((i) => i.type === "table");
    await app.click('[data-action="undo"]');
    await app.click('[data-action="add-note"]');
    const note = (await latest()).find((i) => i.type === "note");
    assert.deepEqual(middle(table), middle(note));
    // With the note there, a new table goes beside it rather than over it.
    await addTable();
    const next = (await latest()).find((i) => i.type === "table");
    assert.ok(
      next.x >= note.x + note.w ||
        note.x >= next.x + next.w ||
        next.y >= note.y + note.h ||
        note.y >= next.y + next.h,
    );
  } finally {
    await app.close();
  }
});

test("the object outline is one Tab stop, moved through with the arrow keys", async () => {
  const app = await setup();
  try {
    const { doc, w } = app;
    await rotationFixture(
      app,
      Array.from({ length: 40 }, (_, n) =>
        item("note", (n % 8) * 220, Math.floor(n / 8) * 220, {
          text: `Note ${n}`,
        }),
      ),
    );
    const buttons = () => [...doc.querySelectorAll("#board-outline button")];
    const stops = () => buttons().filter((b) => b.tabIndex === 0);
    assert.equal(buttons().length, 40);
    assert.equal(stops().length, 1);
    const key = (target, key) =>
      target.dispatchEvent(
        new w.KeyboardEvent("keydown", {
          key,
          bubbles: true,
          cancelable: true,
        }),
      );
    stops()[0].focus();
    const start = buttons().indexOf(doc.activeElement);
    key(doc.activeElement, "ArrowDown");
    assert.equal(buttons().indexOf(doc.activeElement), start + 1);
    key(doc.activeElement, "End");
    assert.equal(doc.activeElement, buttons().at(-1));
    key(doc.activeElement, "Home");
    assert.equal(doc.activeElement, buttons()[0]);
    key(doc.activeElement, "ArrowUp");
    assert.equal(doc.activeElement, buttons()[0]);
    // The object the keyboard was on stays the way back in.
    key(doc.activeElement, "ArrowRight");
    assert.deepEqual(stops(), [buttons()[1]]);
    // Choosing an object makes it the stop once the keyboard has left.
    doc.querySelector("#canvas").focus();
    await app.click(`#board-outline [data-id="${buttons()[7].dataset.id}"]`);
    await app.tick();
    assert.deepEqual(stops(), [buttons()[7]]);
    assert.equal(
      doc.getElementById(
        doc.querySelector("#board-outline").getAttribute("aria-describedby"),
      ).textContent,
      "Arrow keys, Home and End move between objects. Page Down and Page Up move to the next or previous frame.",
    );
  } finally {
    await app.close();
  }
});

test("the object outline and Board objects list each frame with what it holds, and Page Down and Page Up move between frames", async () => {
  const app = await setup();
  try {
    const { doc, w } = app;
    // Frames come last in the board's own order, and in presentation
    // order Plan comes before Ideas.
    const loose = item("note", 2000, 0, { text: "Loose" }),
      idea = item("note", 40, 80, { text: "Idea" }),
      step = item("note", 1040, 80, { text: "Step" }),
      ideas = item("frame", 0, 0, {
        w: 600,
        h: 400,
        text: "Ideas",
        order: 2,
      }),
      plan = item("frame", 1000, 0, {
        w: 600,
        h: 400,
        text: "Plan",
        order: 1,
      });
    idea.parentId = ideas.id;
    step.parentId = plan.id;
    await rotationFixture(app, [loose, idea, step, ideas, plan]);
    const names = (selector) =>
      [...doc.querySelectorAll(selector)].map((b) => b.textContent);
    const expected = ["Plan", "Step", "Ideas", "Idea", "Loose"];
    assert.deepEqual(
      names("#board-outline button").map((n) => n.replace(/^.*: /, "")),
      expected,
    );
    const buttons = () => [...doc.querySelectorAll("#board-outline button")];
    const key = (key) =>
      doc.activeElement.dispatchEvent(
        new w.KeyboardEvent("keydown", {
          key,
          bubbles: true,
          cancelable: true,
        }),
      );
    buttons()[0].focus();
    key("PageDown");
    assert.equal(doc.activeElement, buttons()[2], "Ideas");
    key("PageDown");
    assert.equal(doc.activeElement, buttons()[2], "No frame after Ideas");
    key("ArrowDown");
    key("ArrowDown");
    key("PageUp");
    assert.equal(doc.activeElement, buttons()[2], "Back to Ideas");
    key("PageUp");
    assert.equal(doc.activeElement, buttons()[0], "Back to Plan");
    await app.click('[data-action="objects"]');
    assert.deepEqual(
      names("dialog .object-list [data-object]").map((n) =>
        n.replace(/^.*: /, ""),
      ),
      expected,
    );
  } finally {
    await app.close();
  }
});

test("Board objects is one Tab stop, moved through with the arrow keys and Page Down, listing every frame with its objects under it", async () => {
  const app = await setup();
  try {
    const { doc, w } = app;
    // More objects than the list shows at once, in 30 frames.
    const objects = [];
    for (let f = 0; f < 30; f++) {
      const frame = item("frame", f * 1000, 0, {
        w: 800,
        h: 800,
        text: `Workstream ${f + 1}`,
        order: f + 1,
      });
      for (let n = 0; n < 12; n++) {
        const note = item(
          "note",
          f * 1000 + 20 + (n % 4) * 190,
          20 + Math.floor(n / 4) * 220,
          { text: `Task ${f + 1}.${n + 1}` },
        );
        note.parentId = frame.id;
        objects.push(note);
      }
      objects.push(frame);
    }
    await rotationFixture(app, objects);
    await app.click('[data-action="objects"]');
    const buttons = () => [...doc.querySelectorAll("dialog [data-object]")];
    const frames = () => buttons().filter((b) => b.hasAttribute("data-frame"));
    assert.ok(buttons().length <= 300, "the list stays short");
    assert.equal(frames().length, 30, "every frame is listed");
    assert.ok(
      frames().every((f) => {
        const next = buttons()[buttons().indexOf(f) + 1];
        return next && !next.hasAttribute("data-frame");
      }),
      "each frame is followed by some of what it holds",
    );
    assert.equal(
      buttons().filter((b) => b.tabIndex === 0).length,
      1,
      "the list is one Tab stop",
    );
    // What a frame holds is set in under it, named as before.
    const [first, second] = buttons();
    assert.ok(!first.hasAttribute("data-in-frame"));
    assert.ok(second.hasAttribute("data-in-frame"));
    assert.match(second.textContent, /Task 1\.1$/);
    const key = (key) =>
      doc.activeElement.dispatchEvent(
        new w.KeyboardEvent("keydown", {
          key,
          bubbles: true,
          cancelable: true,
        }),
      );
    first.focus();
    key("ArrowDown");
    assert.equal(doc.activeElement, second);
    assert.equal(second.tabIndex, 0);
    assert.equal(first.tabIndex, -1);
    key("PageDown");
    assert.equal(doc.activeElement, frames()[1]);
    key("PageUp");
    assert.equal(doc.activeElement, first);
    key("End");
    assert.equal(doc.activeElement, buttons().at(-1));
    key("Home");
    assert.equal(doc.activeElement, first);
    // A frame found by its name brings everything it holds.
    const search = doc.querySelector("#object-search");
    search.value = "Workstream 30";
    search.dispatchEvent(new w.Event("input", { bubbles: true }));
    assert.equal(buttons().length, 13);
    assert.match(buttons().at(-1).textContent, /Task 30\.12$/);
    assert.equal(buttons().filter((b) => b.tabIndex === 0).length, 1);
    await app.click(`[data-object="${buttons().at(-1).dataset.object}"]`);
    assert.equal(doc.querySelector("dialog"), null);
    assert.equal(doc.activeElement.id, "canvas");
  } finally {
    await app.close();
  }
});

test("choosing an object in the object outline brings it into view, keeping the zoom", async () => {
  const app = await setup();
  try {
    const { doc } = app;
    await rotationFixture(app, [
      item("note", 0, 0, { text: "Near" }),
      item("note", 50000, 0, { text: "Far" }),
    ]);
    const [near, far] = selectedClipboard(app).sort((a, b) => a.x - b.x);
    const onScreen = (i) => {
      const v = renderedView(app),
        x = v.x + i.x * v.z,
        y = v.y + i.y * v.z;
      return x >= 0 && y >= 0 && x + i.w * v.z <= 1200 && y + i.h * v.z <= 900;
    };
    await app.click('[data-action="reset-zoom"]');
    await app.click(`#board-outline [data-id="${near.id}"]`);
    const zoom = renderedView(app).z;
    assert.ok(onScreen(near));
    assert.ok(!onScreen(far));
    await app.click(`#board-outline [data-id="${far.id}"]`);
    assert.ok(onScreen(far), "the chosen object is shown");
    assert.equal(renderedView(app).z, zoom, "at the same zoom");
    assert.equal(doc.activeElement.id, "canvas");
    // One already in view leaves the view where it is.
    const before = renderedView(app);
    await app.click(`#board-outline [data-id="${far.id}"]`);
    assert.deepEqual(renderedView(app), before);
    await app.click(`#board-outline [data-id="${near.id}"]`);
    assert.ok(onScreen(near));
    assert.equal(renderedView(app).z, zoom);
  } finally {
    await app.close();
  }
});

test("Fit board on a board too spread out to show whole shows its busiest part and says so, also on opening it", async () => {
  const app = await setup();
  try {
    const { doc } = app;
    const west = item("frame", -400000, 0, {
        w: 1000,
        h: 800,
        text: "West",
        order: 1,
      }),
      east = item("frame", 400000, 0, {
        w: 1000,
        h: 800,
        text: "East",
        order: 2,
      }),
      lone = item("note", -399900, 100, { text: "West note" });
    lone.parentId = west.id;
    const busy = [0, 1, 2].map((n) => {
      const i = item("note", 400100 + n * 250, 100, { text: `East ${n}` });
      i.parentId = east.id;
      return i;
    });
    await rotationFixture(app, [west, east, lone, ...busy]);
    const placed = allClipboard(app);
    const named = (text) => placed.find((i) => i.text === text);
    const onScreen = (i) => {
      const v = renderedView(app),
        x = v.x + i.x * v.z,
        y = v.y + i.y * v.z;
      return x >= 0 && y >= 0 && x + i.w * v.z <= 1200 && y + i.h * v.z <= 900;
    };
    const shownEast = () =>
      ["East", "East 0", "East 1", "East 2"].every((t) => onScreen(named(t)));
    await app.click('[data-action="fit"]');
    assert.ok(shownEast(), "the frame holding the most objects is shown");
    assert.ok(!onScreen(named("West note")));
    assert.match(
      doc.querySelector("#toast").textContent,
      /too spread out to show whole/,
    );
    // Opening the board fits it the same way.
    await app.click('[data-action="reset-zoom"]');
    await app.click('[data-action="home"]');
    app.w.HTMLCanvasElement.prototype.getBoundingClientRect = () => ({
      left: 0,
      top: 0,
      right: 1200,
      bottom: 900,
      width: 1200,
      height: 900,
    });
    const deadline = Date.now() + 3000;
    while (!doc.querySelector("[data-open]") && Date.now() < deadline)
      await app.tick();
    await app.click("[data-open]");
    assert.ok(shownEast());
  } finally {
    await app.close();
  }
});

