test("imported and duplicated board titles stay within the title limit", async () => {
  const app = await setup();
  try {
    const { doc, w } = app;
    let fileInput;
    const nativeClick = w.HTMLInputElement.prototype.click;
    w.HTMLInputElement.prototype.click = function () {
      if (this.type === "file") fileInput = this;
      else nativeClick.call(this);
    };
    await app.click('[data-action="import"]');
    const payload = { version: 1, title: "T".repeat(200), items: [] };
    const file = new w.File([JSON.stringify(payload)], "long.json");
    file.text = async () => w.JSON.stringify(payload);
    Object.defineProperty(fileInput, "files", { value: [file] });
    fileInput.dispatchEvent(new w.Event("change"));
    for (let n = 0; n < 40 && !doc.querySelector("#canvas"); n++)
      await app.tick();
    const imported = doc.querySelector("#board-title").value;
    assert.equal(imported.length, 200);
    assert.ok(imported.endsWith(" (imported)"));
    await app.click('[data-action="home"]');
    // The original is starred; its copy is not.
    await app.click("[data-favorite]");
    await app.click("[data-more]");
    // A double click makes one copy.
    doc.querySelector("#copy-board").click();
    await app.click("#copy-board");
    const copies = doc.querySelectorAll("[data-favorite]");
    assert.equal(copies.length, 2);
    assert.equal(
      [...copies].filter((b) => b.getAttribute("aria-pressed") === "true")
        .length,
      1,
    );
    const titles = [...doc.querySelectorAll(".board-card h3")].map(
      (h) => h.textContent,
    );
    const copy = titles.find((title) => title.endsWith(" (copy)"));
    assert.ok(copy, titles.join("\n"));
    assert.equal(copy.length, 200);
    assert.equal(
      titles.filter((title) => title.endsWith(" (copy)")).length,
      1,
      titles.join("\n"),
    );
  } finally {
    await app.close();
  }
});

test("object properties stay valid for objects outside the old 60–2,000 range", async () => {
  const app = await setup();
  try {
    const { doc, w } = app;
    const big = item("frame", 0, 0, { w: 2500.4, h: 2100, text: "Big" }),
      small = item("rect", 3000, 0, { w: 30, h: 20, text: "Small" });
    await rotationFixture(app, [big, small]);
    for (const [name, text] of [
      ["Big", "Bigger"],
      ["Small", "Smaller"],
    ]) {
      const button = [...doc.querySelectorAll("#board-outline button")].find(
        (b) => b.textContent.endsWith(name),
      );
      button.click();
      await app.tick();
      await app.click('[data-action="properties"]');
      const form = doc.querySelector("#edit-form");
      form.querySelector("#object-text").value = text;
      assert.equal(form.checkValidity(), true, name);
      form.dispatchEvent(new w.Event("submit", { cancelable: true }));
      await app.tick();
    }
    const names = [...doc.querySelectorAll("#board-outline button")].map(
      (b) => b.textContent,
    );
    assert.ok(names.some((n) => n.endsWith("Bigger")));
    assert.ok(names.some((n) => n.endsWith("Smaller")));
    const copied = allClipboard(app);
    assert.equal(copied.find((i) => i.text === "Bigger").w, 2500.4);
  } finally {
    await app.close();
  }
});

async function sharedEditors(
  room,
  items,
  count = 2,
  assets = [],
  { peers = true, hub = createPeerHub() } = {},
) {
  const env = environment(),
    seed = new SharedDocument();
  env.service.now = () => Date.now();
  seed.commit({ version: 1, id: room, title: "Shared", items });
  await env.service.call(owner, {
    op: "create",
    room,
    update: encode(seed.update()),
  });
  seed.destroy();
  for (const data of assets)
    await env.service.call(owner, {
      op: "asset.put",
      room,
      asset: await hash(data),
      data,
    });
  const invite = await env.service.call(owner, {
      op: "invite",
      room,
      role: "editor",
    }),
    apps = [];
  const until = async (fn, message) => {
    const end = Date.now() + 8000;
    while (!(await fn()) && Date.now() < end)
      await new Promise((r) => setTimeout(r, 25));
    assert.ok(await fn(), message);
  };
  try {
    for (let n = 0; n < count; n++) {
      const sdk = env.sdk(n ? collaborator : owner);
      if (peers) sdk.peer = hub.peer;
      const app = await setup(sdk);
      apps.push(app);
      await app.click('[data-action="join-shared"]');
      app.doc.querySelector("#join-link").value =
        `https://whiteboard.test/#server=https%3A%2F%2Fwhiteboard-test.puter.work&board=${room}&invite=${n ? invite.token : ""}`;
      app.doc
        .querySelector("#join-link")
        .closest("form")
        .dispatchEvent(new app.w.Event("submit", { cancelable: true }));
      await until(
        () =>
          !app.doc.querySelector("#join-link") &&
          app.doc.querySelector("#canvas"),
        "Joined shared board",
      );
      app.doc.querySelector("#canvas").getBoundingClientRect = () => ({
        left: 0,
        top: 0,
        width: 1000,
        height: 800,
      });
      await app.click('[data-action="fit"]');
    }
  } catch (error) {
    for (const app of apps) await app.close();
    throw error;
  }
  return {
    env,
    apps,
    until,
    close: () => Promise.all(apps.map((app) => app.close())),
  };
}

test("someone typing in an object another person deletes is told who deleted it and can copy their text", async () => {
  const typeInto = async (app, id, text) => {
    await app.click(`#board-outline [data-id="${id}"]`);
    app.doc.querySelector("#canvas").dispatchEvent(
      new app.w.KeyboardEvent("keydown", {
        key: "Enter",
        bubbles: true,
        cancelable: true,
      }),
    );
    await app.tick();
    const editor = app.doc.querySelector("#canvas-text-editor");
    editor.value = text;
    editor.dispatchEvent(new app.w.Event("input", { bubbles: true }));
    await app.tick();
  };
  const told = (app) => {
    const el = app.doc.querySelector("#toast");
    return el.classList.contains("visible") ? el.textContent : "";
  };
  for (const peers of [true, false]) {
    const note = item("note", 100, 100, { text: "Draft" });
    const shared = await sharedEditors(
      `deleted-while-editing-${peers}`,
      [note],
      2,
      [],
      { peers },
    );
    const [a, b] = shared.apps;
    const copied = [];
    Object.defineProperty(a.w.navigator, "clipboard", {
      configurable: true,
      value: { writeText: async (text) => void copied.push(text) },
    });
    try {
      await typeInto(a, note.id, "Draft plus my thought");
      await b.click(`#board-outline [data-id="${note.id}"]`);
      // The person deleting it is seen selecting it first, when their
      // presence can arrive at all.
      if (peers)
        await shared.until(
          () => a.doc.querySelector(".participant-selection"),
          "B's selection reaches A",
        );
      await b.click('[data-action="delete"]');
      await shared.until(
        () => !a.doc.querySelector("#canvas-text-editor"),
        "A's editor closes",
      );
      assert.equal(
        told(a).replace(/Copy text$/, ""),
        peers
          ? "Bob deleted this object while you were editing it."
          : "This object was deleted by someone else while you were editing it.",
      );
      a.doc.querySelector("#toast .toast-action").click();
      await a.tick();
      assert.deepEqual(copied, ["Draft plus my thought"]);
      assert.equal(told(a), "Text copied.");
    } finally {
      await shared.close();
    }
  }
});

test("a change of this person's role is told once and a restricted role stays shown", async () => {
  const room = "role-told",
    note = item("note", 100, 100, { text: "Draft" });
  const shared = await sharedEditors(room, [note]);
  const [, b] = shared.apps;
  const toastEl = b.doc.querySelector("#toast");
  const tag = () => b.doc.querySelector(".board-tag").textContent;
  const hint = () => b.doc.querySelector("#tool-hint").textContent;
  const setRole = async (role) => {
    toastEl.classList.remove("visible");
    await shared.env.service.call(owner, {
      op: "role",
      room,
      uuid: collaborator.uuid,
      role,
    });
    b.w.dispatchEvent(new b.w.Event("online"));
  };
  try {
    // The role known on joining is not a change.
    assert.doesNotMatch(toastEl.textContent, /You can now/);
    assert.equal(tag(), "Shared board");
    await setRole("viewer");
    await shared.until(
      () => b.doc.querySelector(".editor.shared-viewer"),
      "Viewer access arrives",
    );
    assert.ok(toastEl.classList.contains("visible"));
    assert.equal(toastEl.textContent, "You can now only view this board.");
    assert.equal(tag(), "Shared board · View only");
    // The screen reader's tool hint does not offer editing.
    assert.equal(hint(), "Select objects to read them · Space to pan");
    // The access words sit apart, so a short row never cuts them.
    assert.equal(
      b.doc.querySelector(".board-tag .board-tag-access").textContent,
      "View only",
    );
    assert.equal(
      b.doc.querySelector(".board-tag").title,
      "Shared board · View only",
    );
    // Told once, not again with each later check-in.
    toastEl.classList.remove("visible");
    b.w.dispatchEvent(new b.w.Event("online"));
    await new Promise((r) => setTimeout(r, 300));
    assert.equal(toastEl.classList.contains("visible"), false);
    await setRole("commenter");
    await shared.until(
      () => b.doc.querySelector(".editor.shared-commenter"),
      "Commenter access arrives",
    );
    assert.equal(
      toastEl.textContent,
      "You can now comment on this board, but not change its content.",
    );
    assert.equal(tag(), "Shared board · Comment only");
    assert.equal(
      hint(),
      "Select objects to read them · Comment (C) to discuss · Space to pan",
    );
    await setRole("editor");
    await shared.until(
      () => !b.doc.querySelector(".editor.shared-viewer"),
      "Edit access returns",
    );
    assert.equal(toastEl.textContent, "You can now edit this board.");
    assert.equal(tag(), "Shared board");
    assert.equal(
      hint(),
      "Select and move · Double-click to edit · Space to pan",
    );
    // Becoming a facilitator, and ceasing to be one, are told too.
    await setRole("facilitator");
    await shared.until(
      () => toastEl.classList.contains("visible"),
      "Facilitator access arrives",
    );
    assert.equal(
      toastEl.textContent,
      "You can now manage this board's participants and run its facilitation.",
    );
    await setRole("editor");
    await shared.until(
      () => toastEl.classList.contains("visible"),
      "Facilitator access ends",
    );
    assert.equal(
      toastEl.textContent,
      "You can still edit this board, but no longer manage its participants or facilitation.",
    );
  } finally {
    await shared.close();
  }
});

test("screen readers hear who joins, leaves and is editing an object", async () => {
  const note = item("note", 100, 100, { text: "Draft" });
  const shared = await sharedEditors("presence-heard", [note]);
  const [a, b] = shared.apps;
  const said = () => a.doc.querySelector("#board-announcer").textContent;
  const described = () => {
    const button = a.doc.querySelector(`#board-outline [data-id="${note.id}"]`),
      id = button.getAttribute("aria-describedby");
    return (id && a.doc.getElementById(id)?.textContent) || "";
  };
  try {
    // A check-in brings the roster with the person who joined.
    a.w.dispatchEvent(new a.w.Event("online"));
    await shared.until(() => said() === "Bob joined", "The join is said");
    assert.equal(described(), "Butter color.");
    await b.click(`#board-outline [data-id="${note.id}"]`);
    b.doc.querySelector("#canvas").dispatchEvent(
      new b.w.KeyboardEvent("keydown", {
        key: "Enter",
        bubbles: true,
        cancelable: true,
      }),
    );
    await shared.until(
      () => described() === "Being edited by Bob. Butter color.",
      "The outline says who is editing the note",
    );
    await b.click('[data-action="home"]');
    await shared.until(() => described() === "Butter color.", "Editing ends");
    a.w.dispatchEvent(new a.w.Event("online"));
    await shared.until(() => said() === "Bob left", "The departure is said");
  } finally {
    await shared.close();
  }
});

test("what is said behind an open modal dialog is said inside it as well", async () => {
  const frame = item("frame", 0, 0, { w: 400, h: 300, title: "Agenda" });
  const shared = await sharedEditors("presence-behind-dialog", [frame]);
  const [a, b] = shared.apps;
  // jsdom does not track the top layer: an open dialog stands in for a
  // modal one, as showModal is the only way the board opens them.
  const matches = a.w.Element.prototype.matches;
  a.w.HTMLDialogElement.prototype.matches = function (selector) {
    return selector === ":modal" ? this.open : matches.call(this, selector);
  };
  const mirrored = (id) =>
    a.doc.querySelector(`dialog[open] > .dialog-announcer[data-for="${id}"]`)
      ?.textContent;
  try {
    a.w.dispatchEvent(new a.w.Event("online"));
    await shared.until(
      () =>
        a.doc.querySelector("#board-announcer").textContent === "Bob joined",
      "The join is said",
    );
    await a.click('[data-action="present"]');
    await a.click("#start-presentation");
    assert.ok(a.doc.querySelector("dialog[open]"), "Presenting");
    await b.click('[data-action="home"]');
    a.w.dispatchEvent(new a.w.Event("online"));
    // The page's region is inert behind the dialog, so the dialog says it.
    await shared.until(
      () => mirrored("board-announcer") === "Bob left",
      "The departure is said inside the presentation",
    );
    assert.equal(
      a.doc.querySelector("#board-announcer").textContent,
      "Bob left",
    );
  } finally {
    await shared.close();
  }
});

