test("a Puter drive write that fails after the shared room exists leaves the board shared", async () => {
  const env = environment(),
    puter = env.sdk(owner),
    build = "faceb00cfaceb00c";
  await puter.fs.write("whiteboard/catalog.json", "[]");
  await puter.kv.set("whiteboard-collaboration-worker-v1", {
    name: "whiteboard-test",
    server: "https://whiteboard-test.puter.work",
    path: "whiteboard/whiteboard-worker.js",
    build,
    builtAt: 200,
  });
  const exec = puter.workers.exec;
  puter.workers.exec = (url, options) =>
    url.endsWith("/health")
      ? Promise.resolve(Response.json({ build }))
      : exec(url, options);
  const write = puter.fs.write.bind(puter.fs);
  puter.fs.write = (path, ...rest) => {
    if (/^whiteboard\/[0-9a-f-]{36}\.json$/.test(path))
      return Promise.reject(Error("Drive is full"));
    return write(path, ...rest);
  };
  const app = await setup(puter),
    { doc, w, click, tick } = app;
  w.fetch = async () =>
    new Response(`/* whiteboard-worker build=${build} at=200 */`);
  try {
    await click('[data-action="new"]');
    await click('[data-action="share"]');
    await confirmShare(app);
    const deadline = Date.now() + 5000;
    while (!doc.querySelector("#share-link") && Date.now() < deadline)
      await tick();
    assert.ok(doc.querySelector("#share-link"), "Sharing completes");
    assert.equal(doc.querySelector(".board-tag").textContent, "Shared board");
    assert.notEqual(
      doc.querySelector("#save-state").textContent,
      "Sharing failed · try again",
    );
    assert.match(
      doc.querySelector("#toast").textContent,
      /copy in Puter could not be updated/,
    );
  } finally {
    await app.close();
  }
});

test("a click followed at once by a drag moves the object instead of opening its editor", async () => {
  const app = await setup();
  const { doc } = app;
  try {
    const { pointer, selected } = await rotationFixture(app, [
      item("note", 0, 0, { text: "Drag me" }),
    ]);
    const note = selected[0];
    const centre = { x: note.x + note.w / 2, y: note.y + note.h / 2 };
    pointer("pointerdown", centre);
    pointer("pointerup", centre);
    await app.tick();
    // Still within the double-click window, a press that moves is a drag.
    const away = { x: centre.x + 60, y: centre.y + 40 };
    pointer("pointerdown", centre);
    pointer("pointermove", away);
    pointer("pointerup", away);
    await app.tick();
    assert.equal(doc.querySelector("#canvas-text-editor"), null);
    assert.equal(selectedClipboard(app)[0].x, note.x + 60, "The note moved");
    // Two presses that stay put open the editor, on the second release.
    pointer("pointerdown", away);
    pointer("pointerup", away);
    await app.tick();
    pointer("pointerdown", away);
    assert.equal(doc.querySelector("#canvas-text-editor"), null);
    pointer("pointerup", away);
    await app.tick();
    assert.ok(doc.querySelector("#canvas-text-editor"), "Editing begins");
  } finally {
    await app.close();
  }
});

test("a double click on a word puts the caret there and selects that word, not all the text", async () => {
  const app = await setup();
  const { doc } = app;
  try {
    const { pointer, selected } = await rotationFixture(app, [
      item("rect", 0, 0, {
        w: 400,
        h: 120,
        text: "alpha beta gamma",
        textAlign: "center",
      }),
      item("note", 600, 0, { w: 200, h: 200, text: "one two" }),
    ]);
    const [shape, note] = selected;
    // The middle of the first line: 16px of padding above 19px text.
    const centre = { x: shape.x + shape.w / 2, y: shape.y + 28 };
    for (let n = 0; n < 2; n++) {
      pointer("pointerdown", centre);
      pointer("pointerup", centre);
    }
    await app.tick();
    const editor = doc.querySelector("#canvas-text-editor");
    assert.ok(editor, "Editing begins");
    assert.deepEqual(
      [editor.selectionStart, editor.selectionEnd],
      [6, 10],
      "The word under the pointer is selected",
    );
    simulateCanvasTextInput(app, "delta");
    editor.dispatchEvent(
      new app.w.KeyboardEvent("keydown", {
        key: "Enter",
        ctrlKey: true,
        bubbles: true,
      }),
    );
    assert.equal(selectedClipboard(app)[0].text, "alpha delta gamma");
    // Below the text, the caret goes to its end and nothing is selected.
    const below = { x: note.x + note.w / 2, y: note.y + note.h - 10 };
    for (let n = 0; n < 2; n++) {
      pointer("pointerdown", below);
      pointer("pointerup", below);
    }
    await app.tick();
    const noteEditor = doc.querySelector("#canvas-text-editor");
    assert.deepEqual(
      [noteEditor.selectionStart, noteEditor.selectionEnd],
      [7, 7],
    );
    // Enter still selects all the text, ready to be replaced.
    noteEditor.dispatchEvent(
      new app.w.KeyboardEvent("keydown", { key: "Escape", bubbles: true }),
    );
    doc.querySelector("#canvas").dispatchEvent(
      new app.w.KeyboardEvent("keydown", {
        key: "Enter",
        bubbles: true,
        cancelable: true,
      }),
    );
    const entered = doc.querySelector("#canvas-text-editor");
    assert.deepEqual([entered.selectionStart, entered.selectionEnd], [0, 7]);
  } finally {
    await app.close();
  }
});

test("two clicks half a second apart, the Windows double-click time, open the editor", async () => {
  const app = await setup();
  const { doc } = app;
  try {
    const { pointer, selected } = await rotationFixture(app, [
      item("note", 0, 0, { text: "Slow" }),
    ]);
    const note = selected[0];
    const centre = { x: note.x + note.w / 2, y: note.y + note.h / 2 };
    const clicked = app.w.performance.now();
    pointer("pointerdown", centre);
    pointer("pointerup", centre);
    // Timers run late on a busy machine; the second click comes as soon as
    // 420 ms have passed, well over the old 400 ms window.
    while (app.w.performance.now() - clicked < 420)
      await new Promise((r) => setTimeout(r, 5));
    pointer("pointerdown", centre);
    pointer("pointerup", centre);
    await app.tick();
    assert.ok(doc.querySelector("#canvas-text-editor"), "Editing begins");
  } finally {
    await app.close();
  }
});

test("keyboard zoom and fit during a drag change the view under it and the drag goes on", async () => {
  const app = await setup();
  const { doc } = app;
  try {
    const { pointer, selected, key } = await rotationFixture(app, [
      item("rect", 0, 0, { w: 200, h: 100, text: "Dragged" }),
    ]);
    const start = selected[0];
    for (const [n, shortcut] of [
      { key: "=", ctrlKey: true },
      { key: "0", ctrlKey: true },
      { key: "-", metaKey: true },
      { key: "1", code: "Digit1", altKey: true },
      { key: "2", code: "Digit2", altKey: true },
    ].entries()) {
      const [before] = selectedClipboard(app);
      const centre = { x: before.x + 100, y: before.y + 50 };
      const zoom = renderedView(app).z;
      pointer("pointerdown", centre);
      pointer("pointermove", { x: centre.x + 30, y: centre.y });
      key(shortcut.key, { cancelable: true, ...shortcut });
      if (n < 3)
        assert.notEqual(renderedView(app).z, zoom, `${shortcut.key} zooms`);
      pointer("pointermove", { x: centre.x + 80, y: centre.y + 40 });
      pointer("pointerup", { x: centre.x + 80, y: centre.y + 40 });
      const [after] = selectedClipboard(app);
      assert.deepEqual(
        [Math.round(after.x - before.x), Math.round(after.y - before.y)],
        [80, 40],
        `The drag goes on after ${shortcut.key}`,
      );
    }
    for (let n = 0; n < 5; n++) await app.click('[data-action="undo"]');
    assert.deepEqual(allClipboard(app), [start], "Each drag is one undo step");
    assert.equal(doc.querySelector("#canvas-text-editor"), null);
  } finally {
    await app.close();
  }
});

test("dragging to the canvas edge pans the board towards it until the drag ends or leaves the edge", async () => {
  const app = await setup();
  const { doc } = app;
  const wait = (ms) => new Promise((r) => setTimeout(r, ms));
  try {
    const { selected, key } = await rotationFixture(app, [
      item("note", 0, 0, { w: 200, h: 200, text: "Edge" }),
    ]);
    const [note] = selected;
    let v = renderedView(app);
    const sx = v.x + (note.x + 100) * v.z,
      sy = v.y + (note.y + 100) * v.z;
    const mouse = (type, x, y) =>
      canvasPointer(app, type, 1, x, y, { pointerType: "mouse" });
    mouse("pointerdown", sx, sy);
    mouse("pointermove", 1190, sy);
    await wait(300);
    const panned = renderedView(app);
    assert.ok(panned.x < v.x - 40, "The board pans towards the right edge");
    // The note stays under the pointer as the board moves.
    const moving = selectedClipboard(app)[0];
    assert.ok(
      Math.abs(panned.x + (moving.x + 100) * panned.z - 1190) < 1,
      "The note follows the pointer",
    );
    // Back from the edge, the panning stops.
    mouse("pointermove", 600, sy);
    v = renderedView(app);
    await wait(100);
    assert.equal(renderedView(app).x, v.x);
    // Released at the edge, it stops too, and the drag is one undo step.
    mouse("pointermove", 1199, sy);
    await wait(100);
    mouse("pointerup", 1199, sy);
    v = renderedView(app);
    await wait(100);
    assert.equal(renderedView(app).x, v.x, "The release stops the panning");
    await app.click('[data-action="undo"]');
    assert.deepEqual(allClipboard(app), [note]);
    // Escape ends a marquee at the top edge and its panning.
    mouse("pointerdown", 600, 800);
    mouse("pointermove", 600, 2);
    await wait(100);
    assert.ok(renderedView(app).y > v.y, "The board pans down from the top");
    key("Escape", { cancelable: true });
    v = renderedView(app);
    await wait(100);
    assert.equal(renderedView(app).y, v.y, "Escape stops the panning");
    mouse("pointerup", 600, 2);
    assert.equal(doc.querySelector("#canvas-text-editor"), null);
  } finally {
    await app.close();
  }
});

test("a click that wobbles a pixel inside an empty frame does not select the frame", async () => {
  const app = await setup();
  const { doc } = app;
  try {
    const { pointer, selected } = await rotationFixture(app, [
      item("frame", 0, 0, { w: 400, h: 300, text: "Empty" }),
    ]);
    const frame = selected[0];
    const nothingSelected = () => doc.querySelector("#selection-tools").hidden;
    const outside = { x: frame.x + frame.w + 200, y: frame.y + frame.h + 200 };
    pointer("pointerdown", outside);
    pointer("pointerup", outside);
    await app.tick();
    assert.ok(nothingSelected(), "A click outside clears the selection");
    const inside = { x: frame.x + frame.w / 2, y: frame.y + frame.h / 2 };
    pointer("pointerdown", inside);
    pointer("pointermove", { x: inside.x + 1, y: inside.y + 1 });
    pointer("pointerup", { x: inside.x + 1, y: inside.y + 1 });
    await app.tick();
    assert.ok(nothingSelected(), "A wobbling click is still a click");
    pointer("pointerdown", { x: frame.x - 20, y: frame.y - 20 });
    pointer("pointermove", { x: frame.x + 80, y: frame.y + 80 });
    pointer("pointerup", { x: frame.x + 80, y: frame.y + 80 });
    await app.tick();
    assert.ok(!nothingSelected(), "A real marquee selects the frame");
  } finally {
    await app.close();
  }
});

