test("a wheel turn in the middle of a right-button pan keeps the pan going", async () => {
  const app = await setup();
  const { doc, w } = app;
  try {
    await rotationFixture(app, [item("note", 0, 0, { text: "Far" })]);
    const press = (type, x, y) =>
      canvasPointer(app, type, 7, x, y, { pointerType: "mouse", button: 2 });
    const start = renderedView(app);
    press("pointerdown", 500, 400);
    press("pointermove", 540, 420);
    assert.equal(renderedView(app).x, start.x + 40);
    assert.equal(renderedView(app).y, start.y + 20);
    doc.querySelector("#canvas").dispatchEvent(
      new w.WheelEvent("wheel", {
        deltaY: -120,
        clientX: 540,
        clientY: 420,
        ctrlKey: true,
        bubbles: true,
        cancelable: true,
      }),
    );
    const zoomed = renderedView(app);
    assert.ok(zoomed.z > start.z, "The wheel zoomed");
    // The pan goes on from where the wheel left the view.
    press("pointermove", 600, 450);
    const after = renderedView(app);
    assert.equal(after.z, zoomed.z, "The zoom is kept");
    assert.equal(after.x, zoomed.x + 60);
    assert.equal(after.y, zoomed.y + 30);
    press("pointerup", 600, 450);
  } finally {
    await app.close();
  }
});

