test("a Shift marquee keeps a protected object that was already selected", async () => {
  const app = await setup();
  const { w, doc, click } = app;
  try {
    await click('[data-action="new"]');
    const canvas = doc.querySelector("#canvas");
    dispatchTransfer(
      app,
      "drop",
      transferData(
        clipboardFormats([
          item("rect", 0, 0, { text: "Frozen", locked: true }),
          item("rect", 500, 0, { text: "Free" }),
        ]),
      ),
      canvas,
      { clientX: 200, clientY: 200 },
    );
    const pressed = () =>
      [...doc.querySelectorAll('#board-outline [aria-pressed="true"]')]
        .map((b) => b.textContent.match(/Frozen|Free/)[0])
        .sort();
    await click("#board-outline button");
    assert.deepEqual(pressed(), ["Frozen"]);
    // A Shift marquee over the free object adds it, as Shift-click would.
    const v = renderedView(app);
    const at = (x, y) => ({
      clientX: v.x + x * v.z,
      clientY: v.y + y * v.z,
    });
    for (const [type, p] of [
      ["pointerdown", at(450, -50)],
      ["pointermove", at(750, 250)],
      ["pointerup", at(750, 250)],
    ])
      canvas.dispatchEvent(
        new w.MouseEvent(type, {
          bubbles: true,
          button: 0,
          shiftKey: true,
          ...p,
        }),
      );
    assert.deepEqual(pressed(), ["Free", "Frozen"]);
  } finally {
    await app.close();
  }
});

test("the connection endpoints dialog lists a long board in part, with a search", async () => {
  const app = await setup();
  const { doc, w, click } = app;
  try {
    const shapes = Array.from({ length: 320 }, (_, n) =>
      item("rect", (n % 20) * 150, Math.floor(n / 20) * 150, {
        w: 100,
        h: 100,
        text: n === 319 ? "Needle" : `Shape ${n + 1}`,
      }),
    );
    const line = item("arrow", 0, 0, {
      w: 100,
      h: 0,
      startId: shapes[0].id,
      endId: shapes[319].id,
    });
    await rotationFixture(app, [...shapes, line]);
    const placed = selectedClipboard(app);
    const arrow = placed.find((i) => i.type === "arrow");
    await click(`#board-outline [data-id="${arrow.id}"]`);
    await click('[data-action="connection-endpoints"]');
    const dialog = doc.querySelector("dialog[open]");
    const radios = (end) => [
      ...dialog.querySelectorAll(`#connection-${end} input[type="radio"]`),
    ];
    assert.ok(radios("start").length <= 302, `${radios("start").length}`);
    assert.match(dialog.textContent, /Showing the first 300 of 320/);
    // The attached object is listed even past the cut.
    assert.ok(radios("end").some((r) => r.checked && r.value === arrow.endId));
    const search = dialog.querySelector('.connection-search[data-end="end"]');
    search.value = "needle";
    search.dispatchEvent(new w.Event("input", { bubbles: true }));
    assert.deepEqual(
      radios("end").map((r) => [r.value === arrow.endId, r.checked]),
      [
        [false, false],
        [true, true],
      ],
    );
    search.value = "shape 2";
    search.dispatchEvent(new w.Event("input", { bubbles: true }));
    const listed = radios("end");
    assert.ok(listed.length > 2 && listed.length <= 302);
    assert.ok(
      listed.some((r) => r.checked && r.value === arrow.endId),
      "The chosen object stays listed while searching",
    );
    const enter = new w.KeyboardEvent("keydown", {
      key: "Enter",
      bubbles: true,
      cancelable: true,
    });
    search.dispatchEvent(enter);
    assert.equal(enter.defaultPrevented, true);
    assert.ok(doc.querySelector("dialog[open]"));
  } finally {
    await app.close();
  }
});

test("the eraser end of a stylus rubs out the drawings it passes over in one undo step", async () => {
  const app = await setup();
  const { doc, click } = app;
  try {
    const stroke = (x) =>
      item("pen", x, 0, {
        w: 10,
        h: 200,
        points: [
          [0, 0],
          [10, 200],
        ],
      });
    const note = item("note", 300, 0, { text: "Kept" });
    const { pointer } = await rotationFixture(app, [
      stroke(0),
      stroke(100),
      stroke(200),
      note,
    ]);
    const placed = selectedClipboard(app);
    const at = (id) => {
      const i = placed.find((i) => i.id === id);
      return { x: i.x + 5, y: i.y + 100 };
    };
    const pens = placed.filter((i) => i.type === "pen"),
      kept = placed.find((i) => i.type === "note");
    const outline = () =>
      doc.querySelectorAll("#board-outline [data-id]").length;
    assert.equal(outline(), 4);
    click('[data-action="tool-select"]');
    // Eraser contact (button 5, buttons bit 32) in select mode.
    pointer("pointerdown", at(pens[0].id), {
      pointerType: "pen",
      button: 5,
      buttons: 32,
    });
    pointer("pointermove", at(pens[1].id), { pointerType: "pen", buttons: 32 });
    pointer("pointermove", at(kept.id), { pointerType: "pen", buttons: 32 });
    pointer("pointerup", at(kept.id), { pointerType: "pen", button: 5 });
    await app.tick();
    assert.equal(outline(), 2, "Two strokes are erased, the note stays");
    assert.ok(doc.querySelector(`#board-outline [data-id="${pens[2].id}"]`));
    await click('[data-action="undo"]');
    assert.equal(outline(), 4, "One undo step brings both strokes back");
    // Erasing nothing adds no undo step.
    await click('[data-action="redo"]');
    assert.equal(outline(), 2);
    pointer(
      "pointerdown",
      { x: -500, y: -500 },
      {
        pointerType: "pen",
        button: 5,
        buttons: 32,
      },
    );
    pointer(
      "pointerup",
      { x: -500, y: -500 },
      { pointerType: "pen", button: 5 },
    );
    await app.tick();
    await click('[data-action="undo"]');
    assert.equal(outline(), 4);
  } finally {
    await app.close();
  }
});

test("a board open in two tabs refuses a save over the other tab's edits instead of losing them", async () => {
  const indexedDB = new IDBFactory();
  const first = await setup(undefined, { indexedDB });
  let second;
  try {
    const addNote = async (app) => {
      const canvas = app.doc.querySelector("#canvas");
      canvas.focus();
      canvas.dispatchEvent(
        new app.w.KeyboardEvent("keydown", { key: "n", bubbles: true }),
      );
      await app.tick();
      app.doc
        .querySelector("#canvas-text-editor")
        .dispatchEvent(
          new app.w.KeyboardEvent("keydown", { key: "Escape", bubbles: true }),
        );
      await app.tick();
    };
    const stored = async () => {
      const db = await new Promise((resolve, reject) => {
        const request = indexedDB.open("whiteboard-v1");
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
      });
      const rows = await new Promise((resolve, reject) => {
        const request = db.transaction("boards").objectStore("boards").getAll();
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
      });
      db.close();
      return rows.find((b) => !b.deletedAt);
    };
    await first.click('[data-action="new"]');
    await addNote(first);
    await new Promise((r) => setTimeout(r, 100));
    assert.equal((await stored()).items.length, 1);
    // A second tab opens the same board from its library and adds a note.
    second = await setup(undefined, { indexedDB });
    const id = (await stored()).id;
    await second.click(`[data-open="${id}"]`);
    await addNote(second);
    await new Promise((r) => setTimeout(r, 100));
    assert.equal((await stored()).items.length, 2);
    // The first tab's next save would drop the second tab's note.
    await addNote(first);
    await new Promise((r) => setTimeout(r, 100));
    assert.equal((await stored()).items.length, 2, "The newer copy stays");
    assert.equal(
      first.doc.querySelector("#toast").textContent,
      "This board changed in another tab. Your changes here are kept in Version history. Reload to see the latest copy.",
    );
    assert.equal(
      first.doc.querySelector("#save-state").textContent,
      "Not saved",
    );
  } finally {
    await second?.close();
    await first.close();
  }
});

test("edits a save refused for another tab's copy are kept as one version that a reload can restore", async () => {
  const indexedDB = new IDBFactory();
  const first = await setup(undefined, { indexedDB });
  let second, reloaded;
  try {
    const addNote = async (app) => {
      const canvas = app.doc.querySelector("#canvas");
      canvas.focus();
      canvas.dispatchEvent(
        new app.w.KeyboardEvent("keydown", { key: "n", bubbles: true }),
      );
      await app.tick();
      app.doc
        .querySelector("#canvas-text-editor")
        .dispatchEvent(
          new app.w.KeyboardEvent("keydown", { key: "Escape", bubbles: true }),
        );
      await app.tick();
      await new Promise((r) => setTimeout(r, 100));
    };
    const rows = async (store) => {
      const db = await new Promise((resolve, reject) => {
        const request = indexedDB.open("whiteboard-v1");
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
      });
      const result = await new Promise((resolve, reject) => {
        const request = db.transaction(store).objectStore(store).getAll();
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
      });
      db.close();
      return result;
    };
    const refused = async () =>
      (await rows("revisions")).filter(
        (r) => r.label === "Unsaved changes from another tab",
      );
    await first.click('[data-action="new"]');
    await addNote(first);
    const id = (await rows("boards"))[0].id;
    second = await setup(undefined, { indexedDB });
    await second.click(`[data-open="${id}"]`);
    await addNote(second);
    // The first tab goes on editing its older copy: each save is refused,
    // and one version holds the latest of what it refused.
    await addNote(first);
    await addNote(first);
    await addNote(first);
    assert.equal((await rows("boards"))[0].items.length, 2);
    let kept = await refused();
    assert.equal(kept.length, 1);
    assert.equal(kept[0].board.items.length, 4);
    assert.equal(kept[0].kept, true);
    assert.equal(
      first.doc.querySelector("#toast").textContent,
      "This board changed in another tab. Your changes here are kept in Version history. Reload to see the latest copy.",
    );
    // Reloaded, the tab shows the other tab's copy, and its own edits are
    // in Version history.
    await first.close();
    reloaded = await setup(undefined, { indexedDB });
    await reloaded.click(`[data-open="${id}"]`);
    await reloaded.click('[data-action="more-tools"]');
    await reloaded.click('[data-feature="history"]');
    const row = () =>
      [...reloaded.doc.querySelectorAll("#local-revisions .revision-row")].find(
        (r) => r.textContent.includes("Unsaved changes from another tab"),
      );
    for (let n = 0; n < 40 && !row(); n++) await reloaded.tick();
    assert.match(row()?.textContent || "", /4 objects/);
  } finally {
    await reloaded?.close();
    await second?.close();
    await first.close().catch(() => {});
  }
});

test("a favorite, trash or permanent delete made in another tab survives this tab's saves", async () => {
  const indexedDB = new IDBFactory();
  const first = await setup(undefined, { indexedDB });
  let second;
  try {
    const addNote = async (app) => {
      const canvas = app.doc.querySelector("#canvas");
      canvas.focus();
      canvas.dispatchEvent(
        new app.w.KeyboardEvent("keydown", { key: "n", bubbles: true }),
      );
      await app.tick();
      app.doc
        .querySelector("#canvas-text-editor")
        .dispatchEvent(
          new app.w.KeyboardEvent("keydown", { key: "Escape", bubbles: true }),
        );
      await app.tick();
      await new Promise((r) => setTimeout(r, 100));
    };
    const rows = async () => {
      const db = await new Promise((resolve, reject) => {
        const request = indexedDB.open("whiteboard-v1");
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
      });
      const all = await new Promise((resolve, reject) => {
        const request = db.transaction("boards").objectStore("boards").getAll();
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
      });
      db.close();
      return all;
    };
    await first.click('[data-action="new"]');
    await addNote(first);
    assert.equal((await rows()).length, 1);
    // The other tab stars the board from its library.
    second = await setup(undefined, { indexedDB });
    await second.click("[data-favorite]");
    assert.equal((await rows())[0].favorite, true);
    await addNote(first);
    assert.equal((await rows())[0].favorite, true, "The star stays");
    assert.equal((await rows())[0].items.length, 2, "The note is saved");
    assert.equal(
      first.doc.querySelector("#save-state").textContent,
      "Saved on this device",
    );
    // The other tab moves it to the trash.
    await second.click("[data-more]");
    await second.click("#remove-board");
    await second.click("#confirm-delete");
    assert.ok((await rows())[0].deletedAt);
    await addNote(first);
    assert.ok((await rows())[0].deletedAt, "The board stays in the trash");
    assert.equal((await rows())[0].items.length, 3);
    // This tab's library shows the choices made elsewhere.
    await first.click('[data-action="home"]');
    assert.equal(first.doc.querySelectorAll(".board-card").length, 0);
    await first.click('[data-filter="trash"]');
    assert.equal(first.doc.querySelectorAll(".board-card").length, 1);
    await first.click("[data-open]");
    await first.click("#restore-board");
    assert.equal((await rows())[0].deletedAt, undefined);
    await first.click('[data-filter="all"]');
    await first.click("[data-open]");
    // The other tab, whose library still shows the board in the trash,
    // deletes it for good; this tab's edits no longer save.
    await second.click('[data-filter="trash"]');
    await second.click("[data-open]");
    await second.click("#purge-board");
    await second.click("#confirm-purge");
    assert.equal((await rows()).length, 0);
    await addNote(first);
    assert.equal((await rows()).length, 0, "A deleted board does not return");
    assert.equal(
      first.doc.querySelector("#toast").textContent,
      "This board was deleted in another tab.",
    );
    assert.equal(
      first.doc.querySelector("#save-state").textContent,
      "Not saved",
    );
  } finally {
    await second?.close();
    await first.close();
  }
});

test("a library change refused for another tab's change shows that tab's copy and says why", async () => {
  const indexedDB = new IDBFactory();
  const first = await setup(undefined, { indexedDB });
  let second;
  try {
    await first.click('[data-action="new"]');
    await first.click('[data-action="home"]');
    second = await setup(undefined, { indexedDB });
    // The other tab renames the board from its editor.
    await second.click("[data-open]");
    const title = second.doc.querySelector("#board-title");
    title.value = "Renamed elsewhere";
    title.dispatchEvent(new second.w.Event("change"));
    await new Promise((r) => setTimeout(r, 100));
    // A rename here is refused, and the card shows the other tab's name.
    await first.click("[data-more]");
    first.doc.querySelector("#rename").value = "Renamed here";
    await first.click("#rename-board");
    assert.equal(
      first.doc.querySelector("#toast").textContent,
      "This board changed in another tab. Reload to see the latest copy.",
    );
    assert.equal(
      first.doc.querySelector(".board-card h3").textContent,
      "Renamed elsewhere",
    );
    // A star still takes, as it changes no edit.
    await first.click("[data-favorite]");
    assert.equal(
      first.doc.querySelector("[data-favorite]").getAttribute("aria-pressed"),
      "true",
    );
    // The other tab deletes the board for good; a star here says so and
    // the card goes.
    await second.click('[data-action="home"]');
    await second.click("[data-more]");
    await second.click("#remove-board");
    await second.click("#confirm-delete");
    await second.click('[data-filter="trash"]');
    await second.click("[data-open]");
    await second.click("#purge-board");
    await second.click("#confirm-purge");
    await first.click("[data-favorite]");
    assert.equal(
      first.doc.querySelector("#toast").textContent,
      "This board was deleted in another tab.",
    );
    assert.equal(first.doc.querySelectorAll(".board-card").length, 0);
    assert.equal(first.doc.activeElement.dataset.filter, "favorites");
  } finally {
    await second?.close();
    await first.close();
  }
});

