test("PNG export of a large board is as large as the device allows, down to 4,096 pixels", async () => {
  const app = await setup();
  try {
    const { doc, w } = app;
    const encode = w.HTMLCanvasElement.prototype.toBlob;
    // Sizes are read as the canvas is encoded; a browser that cannot make
    // a canvas that large hands back no image.
    let sizes = [],
      refuse = () => false;
    w.HTMLCanvasElement.prototype.toBlob = function (cb) {
      sizes.push([this.width, this.height]);
      if (refuse(this.width, this.height)) return cb(null);
      cb(new w.Blob(["png"], { type: "image/png" }));
    };
    const exported = async (items) => {
      if (doc.querySelector('[data-action="home"]')) {
        await app.click('[data-action="home"]');
        await app.tick();
      }
      await rotationFixture(app, items);
      sizes = [];
      await app.click('[data-action="export"]');
      doc.querySelector("#export-format").value = "png";
      doc
        .querySelector("dialog form")
        .dispatchEvent(
          new w.Event("submit", { bubbles: true, cancelable: true }),
        );
      for (let n = 0; n < 80 && !app.downloads.length; n++) await app.tick();
      assert.ok(app.downloads.pop(), "downloaded");
      return sizes.at(-1);
    };
    const wide = [item("rect", 0, 0, { w: 20000, h: 1200 })],
      large = [item("rect", 0, 0, { w: 6000, h: 4000 })];
    try {
      assert.equal(Math.max(...(await exported(wide))), 16384);
      let [width, height] = await exported(large);
      assert.ok(
        width * height <= 64e6 && width * height > 63e6,
        `${width}x${height}`,
      );
      // iPhone and iPad canvases hold 16.7 megapixels.
      w.matchMedia = (q) => ({
        matches: q.includes("coarse"),
        addEventListener() {},
      });
      [width, height] = await exported(large);
      assert.ok(width * height <= 4096 * 4096 && width * height > 16e6);
      w.matchMedia = () => ({ matches: false, addEventListener() {} });
      refuse = (width, height) => width * height > 4096 * 4096;
      [width, height] = await exported(large);
      assert.ok(width * height <= 4096 * 4096 && width * height > 16e6);
      refuse = (width, height) => Math.max(width, height) > 4096;
      assert.equal(Math.max(...(await exported(large))), 4096);
    } finally {
      w.HTMLCanvasElement.prototype.toBlob = encode;
    }
  } finally {
    await app.close();
  }
});

test("a vote timed by the board timer keeps to it when the timer is extended, paused, resumed or reset", async () => {
  const app = await setup();
  try {
    const { doc, w } = app;
    await rotationFixture(app, [
      item("note", 0, 0, { text: "Idea A" }),
      item("note", 300, 0, { text: "Idea B" }),
    ]);
    await app.click('.canvas-navigation [data-action="facilitation"]');
    await app.click("#fac-tab-vote");
    doc.querySelector("#fac-vote-minutes").value = "1";
    doc
      .querySelector("#fac-vote-form")
      .dispatchEvent(new w.Event("submit", { cancelable: true }));
    await app.tick();
    const saved = async () => {
      await app.tick();
      const b = (await storedBoards(app)).find((b) => b.workshop?.vote);
      return { vote: b.workshop.vote, timer: b.timer };
    };
    let { vote, timer } = await saved();
    assert.equal(timer.id, `vote-${vote.id}`);
    assert.equal(vote.endsAt, timer.endsAt);
    await app.click('[data-action="timer"]');
    doc.querySelector('[data-timer-extra="300000"]').click();
    ({ vote, timer } = await saved());
    assert.equal(timer.duration, 360000);
    assert.equal(vote.endsAt, timer.endsAt);
    assert.match(
      doc.querySelector("#workshop-banner").textContent,
      /[56]:[0-9]{2}$/,
    );
    // Paused, the vote stays open however long the pause lasts.
    doc.querySelector('[data-timer-command="pause"]').click();
    ({ vote } = await saved());
    assert.equal(vote.endsAt, 0);
    assert.equal(vote.state, "active");
    doc.querySelector('[data-timer-command="resume"]').click();
    ({ vote, timer } = await saved());
    assert.ok(vote.endsAt > Date.now() + 300000);
    assert.equal(vote.endsAt, timer.endsAt);
    // A new countdown is the timer's own; the vote keeps its deadline.
    const before = vote.endsAt;
    doc.querySelector('[data-timer-command="stop"]').click();
    ({ vote } = await saved());
    assert.equal(vote.endsAt, 0);
    doc.querySelector("#timer-minutes").value = "2";
    doc
      .querySelector("#timer-form")
      .dispatchEvent(new w.Event("submit", { cancelable: true }));
    ({ vote, timer } = await saved());
    assert.notEqual(timer.id, `vote-${vote.id}`);
    assert.equal(vote.endsAt, 0);
    assert.ok(before > 0);
  } finally {
    await app.close();
  }
});

test("a timed vote leaves a running board timer alone, and ending it early stops its own", async () => {
  const app = await setup();
  try {
    const { doc, w } = app;
    await rotationFixture(app, [
      item("note", 0, 0, { text: "Idea A" }),
      item("note", 300, 0, { text: "Idea B" }),
    ]);
    const saved = async () => {
      await app.tick();
      const b = (await storedBoards(app)).find((b) => b.timer);
      return { vote: b.workshop?.vote, timer: b.timer };
    };
    // A ten-minute timebox is counting down, as for an agenda step.
    await app.click('[data-action="timer"]');
    doc.querySelector("#timer-minutes").value = "10";
    doc
      .querySelector("#timer-form")
      .dispatchEvent(new w.Event("submit", { cancelable: true }));
    const { timer: timebox } = await saved();
    assert.equal(timebox.duration, 600000);
    await app.click('.canvas-navigation [data-action="facilitation"]');
    await app.click("#fac-tab-vote");
    const option = doc.querySelector("#fac-vote-timer");
    assert.equal(option.checked, false, "The vote does not take the timer");
    assert.match(
      doc.querySelector(`#${option.getAttribute("aria-describedby")}`)
        .textContent,
      /voting banner/,
    );
    doc.querySelector("#fac-vote-minutes").value = "1";
    doc
      .querySelector("#fac-vote-form")
      .dispatchEvent(new w.Event("submit", { cancelable: true }));
    let { vote, timer } = await saved();
    assert.deepEqual(timer, timebox, "The timebox keeps counting");
    assert.ok(vote.endsAt > 0, "The vote still has its time limit");
    await app.click('[data-fac="vote-end"]');
    ({ timer } = await saved());
    assert.deepEqual(timer, timebox, "Ending the vote leaves it alone too");
    // With the timer free, a vote shows its limit there by default, and
    // ending it early stops that countdown rather than ringing later.
    await app.click('[data-action="timer"]');
    doc.querySelector('[data-timer-command="stop"]').click();
    await app.tick();
    if (!doc.querySelector("#fac-tab-vote"))
      await app.click('.canvas-navigation [data-action="facilitation"]');
    await app.click("#fac-tab-vote");
    await app.click('[data-fac="vote-clear"]');
    assert.equal(doc.querySelector("#fac-vote-timer").checked, true);
    assert.equal(doc.querySelector("#fac-vote-timer-busy"), null);
    doc.querySelector("#fac-vote-minutes").value = "2";
    doc
      .querySelector("#fac-vote-form")
      .dispatchEvent(new w.Event("submit", { cancelable: true }));
    ({ vote, timer } = await saved());
    assert.equal(timer.id, `vote-${vote.id}`);
    assert.equal(timer.state, "running");
    await app.click('[data-fac="vote-end"]');
    ({ vote, timer } = await saved());
    assert.equal(vote.state, "ended");
    assert.equal(timer.state, "idle");
  } finally {
    await app.close();
  }
});

