test("joining a shared board from the editor starts without the previous export region", async () => {
  const env = environment(),
    room = "join-from-editor",
    seed = new SharedDocument();
  env.service.now = () => Date.now();
  seed.commit({
    version: 1,
    id: room,
    title: "Joined",
    items: [item("rect", 0, 0, { w: 100, h: 100 })],
  });
  await env.service.call(owner, {
    op: "create",
    room,
    update: encode(seed.update()),
  });
  seed.destroy();
  const app = await setup(env.sdk(owner));
  try {
    const { doc, w } = app;
    await rotationFixture(app, [item("rect", 0, 0, { w: 200, h: 100 })]);
    await app.click('[data-action="more-tools"]');
    await app.click('[data-feature="region"]');
    canvasPointer(app, "pointerdown", 1, 100, 100, { pointerType: "mouse" });
    canvasPointer(app, "pointermove", 1, 400, 300, { pointerType: "mouse" });
    canvasPointer(app, "pointerup", 1, 400, 300, { pointerType: "mouse" });
    await app.click('[data-action="commands"]');
    paletteQuery(app, "Join shared board");
    await app.click('[data-command="join-shared"]');
    doc.querySelector("#join-link").value =
      `https://whiteboard.test/#server=https%3A%2F%2Fwhiteboard-test.puter.work&board=${room}`;
    doc
      .querySelector("#join-link")
      .closest("form")
      .dispatchEvent(new w.Event("submit", { cancelable: true }));
    for (let n = 0; n < 200 && doc.querySelector("#join-link"); n++)
      await app.tick();
    assert.equal(doc.querySelector("#board-title").value, "Joined");
    await app.click('[data-action="export"]');
    assert.equal(
      doc.querySelector('#export-scope option[value="region"]'),
      null,
    );
  } finally {
    await app.close();
  }
});

test("the Trash view lists only what is in the trash, without templates or imports", async () => {
  const app = await setup();
  try {
    const { doc } = app;
    assert.ok(doc.querySelector('[aria-labelledby="start-heading"]'));
    assert.ok(doc.querySelector('[data-action="import"]'));
    await app.click('[data-filter="trash"]');
    assert.equal(
      doc.querySelector("#boards-heading").textContent.trim(),
      "Trash 0",
    );
    assert.equal(doc.querySelector('[aria-labelledby="start-heading"]'), null);
    assert.equal(doc.querySelector('[data-action="import"]'), null);
    assert.equal(doc.querySelector('[data-action="migrate-miro"]'), null);
    // Search and sorting still apply to what the trash holds.
    assert.ok(doc.querySelector("#search"));
    assert.ok(doc.querySelector("#sort"));
    await app.click('[data-filter="all"]');
    assert.ok(doc.querySelector('[aria-labelledby="start-heading"]'));
    assert.ok(doc.querySelector('[data-action="migrate-miro"]'));
  } finally {
    await app.close();
  }
});
test("the board header keeps language and appearance behind one Preferences button", async () => {
  const app = await setup();
  try {
    const { doc, w } = app;
    await app.click('[data-action="new"]');
    const popover = doc.querySelector(".editor-actions details.preferences");
    assert.ok(popover, "The header has a Preferences disclosure");
    assert.equal(
      popover.querySelector("summary").getAttribute("aria-label"),
      "Preferences",
    );
    // Both selects live inside it, and nowhere else in the header.
    assert.ok(popover.querySelector("#language"));
    assert.ok(popover.querySelector("#theme"));
    assert.equal(doc.querySelectorAll(".editor-actions select").length, 2);
    assert.equal(popover.open, false);
    // Changing the language draws the header again with the popover open
    // and the keyboard still on the language control.
    doc.querySelector("#language").value = "fr";
    doc.querySelector("#language").dispatchEvent(new w.Event("change"));
    await app.tick();
    const reopened = doc.querySelector(".editor-actions details.preferences");
    assert.equal(reopened.open, true);
    assert.equal(doc.activeElement, doc.querySelector("#language"));
    assert.equal(
      reopened.querySelector("summary").getAttribute("aria-label"),
      "Préférences",
    );
    // Escape closes it and hands focus back to its button.
    reopened.dispatchEvent(
      new w.KeyboardEvent("keydown", { key: "Escape", bubbles: true }),
    );
    assert.equal(reopened.open, false);
    assert.equal(doc.activeElement, reopened.querySelector("summary"));
    doc.querySelector("#language").value = "en";
    doc.querySelector("#language").dispatchEvent(new w.Event("change"));
    await app.tick();
  } finally {
    await app.close();
  }
});
test("redrawing keeps rendered icons and unchanged labels in place", async () => {
  const app = await setup();
  try {
    const { doc, w } = app;
    await app.click('[data-action="new"]');
    const icon = doc.querySelector('[data-action="undo"] svg');
    assert.ok(icon, "Icons are rendered");
    let writes = 0;
    const observer = new w.MutationObserver((records) => {
      writes += records.length;
    });
    observer.observe(doc.querySelector(".editor-actions"), {
      subtree: true,
      childList: true,
      attributes: true,
    });
    await app.click('[data-action="zoom-in"]');
    await app.click('[data-action="zoom-out"]');
    await app.tick();
    observer.disconnect();
    assert.equal(doc.querySelector('[data-action="undo"] svg'), icon);
    assert.equal(writes, 0);
    doc.querySelector("#language").value = "fr";
    doc.querySelector("#language").dispatchEvent(new w.Event("change"));
    await app.tick();
    assert.equal(
      doc.querySelector('[data-action="export"]').getAttribute("aria-label"),
      "Exporter le tableau",
    );
    assert.ok(doc.querySelector('[data-action="export"] svg'));
  } finally {
    await app.close();
  }
});

test("French shortcut help, palette categories and result counts are translated", async () => {
  const app = await setup();
  try {
    const { doc, w } = app;
    await app.click('[data-action="new"]');
    await app.click('[data-action="commands"]');
    paletteQuery(app, "Undo");
    await app.tick();
    assert.equal(doc.querySelector("#command-count").textContent, "1 result");
    doc.querySelector("dialog[open]").close();
    doc.querySelector("#language").value = "fr";
    doc.querySelector("#language").dispatchEvent(new w.Event("change"));
    await app.tick();
    await app.click('[data-action="more-tools"]');
    await app.click('[data-feature="help"]');
    const keys = [...doc.querySelectorAll("dialog[open] .shortcuts kbd")].map(
      (k) => k.textContent,
    );
    for (const english of ["Arrow keys", "Escape", " or ", "Shift", "drag"])
      assert.ok(
        !keys.some((k) => k.includes(english)),
        `${english} is translated: ${keys.join(" | ")}`,
      );
    doc.querySelector("dialog[open]").close();
    await app.click('[data-action="commands"]');
    paletteQuery(app, "Partager");
    await app.tick();
    const categories = [
      ...doc.querySelectorAll("#command-results .command-label small"),
    ].map((s) => s.textContent);
    assert.ok(!categories.includes("Share") && !categories.includes("View"));
    assert.equal(
      doc.querySelector("#commands-prev").textContent,
      "Résultats précédents",
    );
    // Shortcuts name keys as the French tooltips and shortcuts list do,
    // and the French name of a tool finds it.
    const results = async (query) => {
      paletteQuery(app, query);
      await app.tick();
      return [...doc.querySelectorAll("#command-results .command-option")].map(
        (o) => [o.dataset.command, o.querySelector("kbd")?.textContent || ""],
      );
    };
    const redo = (await results("Rétablir")).find(([id]) => id === "redo");
    assert.equal(redo[1], "Ctrl/Cmd+Maj+Z");
    assert.ok(
      (await results("supprimer")).some(([, k]) => k === "Suppr"),
      "Delete reads Suppr",
    );
    const connector = (await results("connecteur")).map(([id]) => id);
    assert.ok(connector.includes("tool-arrow"), connector.join());
    assert.ok(connector.includes("arrange:connect"), connector.join());
  } finally {
    await app.close();
  }
});

test("saved reusable content lands in the middle of the view without zooming", async () => {
  const app = await setup();
  const { w, doc, click, tick } = app;
  try {
    const { key } = await rotationFixture(app, [
      item("note", 0, 0, { text: "Small piece" }),
      item("rect", 4000, 0, { w: 200, h: 100, text: "Far away" }),
    ]);
    // Only the note is saved.
    const save = async (name) => {
      await click('[data-action="organize"]');
      await click('[data-organize="snippet"]');
      doc.querySelector("#snippet-name").value = name;
      doc
        .querySelector("dialog form")
        .dispatchEvent(new w.Event("submit", { cancelable: true }));
      await tick();
    };
    const until = async (check) => {
      const deadline = Date.now() + 5000;
      while (!check() && Date.now() < deadline) await tick();
    };
    await click("#board-outline [data-id]");
    await save("Small piece");
    const before = renderedView(app);
    await click('[data-action="more-tools"]');
    await click('[data-feature="templates"]');
    await until(() => doc.querySelector("[data-custom]"));
    await click("[data-custom]");
    const [copy] = selectedClipboard(app);
    const v = renderedView(app);
    assert.deepEqual(v, before, "The view stays where it was");
    const middle = {
      x: v.x + (copy.x + copy.w / 2) * v.z,
      y: v.y + (copy.y + copy.h / 2) * v.z,
    };
    assert.ok(Math.abs(middle.x - 600) <= 30, JSON.stringify(middle));
    assert.ok(Math.abs(middle.y - 450) <= 30, JSON.stringify(middle));
    // A piece larger than the view zooms out to show all of it.
    key("a", { ctrlKey: true });
    await tick();
    await save("Wide piece");
    await click('[data-action="more-tools"]');
    await click('[data-feature="templates"]');
    await until(() => doc.querySelectorAll("[data-custom]").length === 2);
    const wide = [...doc.querySelectorAll("[data-custom]")].find((b) =>
      b
        .closest("[data-custom-row], .revision-row")
        ?.textContent.includes("Wide piece"),
    );
    wide.click();
    await tick();
    assert.ok(renderedView(app).z < before.z, "Zoomed out to fit");
  } finally {
    await app.close();
  }
});

