test("a selected frame's context menu presents from it or exports it", async () => {
  const app = await setup();
  const { doc, tick, click } = app;
  try {
    const { key, selected } = await rotationFixture(app, [
      item("frame", 0, 0, { w: 500, h: 300, text: "Intro", order: 0 }),
      item("frame", 600, 0, { w: 500, h: 300, text: "Ideas", order: 1 }),
      item("note", 0, 500, { text: "Loose" }),
    ]);
    const byText = (text) => selected.find((i) => i.text === text);
    const menu = async (id) => {
      await click(`#board-outline [data-id="${id}"]`);
      key("F10", { shiftKey: true, cancelable: true });
      await tick();
      return [...doc.querySelectorAll('#context-menu [role="menuitem"]')].map(
        (b) => b.dataset.command,
      );
    };
    const close = () =>
      doc
        .querySelector("#context-menu")
        ?.dispatchEvent(
          new app.w.KeyboardEvent("keydown", { key: "Escape", bubbles: true }),
        );
    assert.ok(!(await menu(byText("Loose").id)).includes("frames:export"));
    close();
    const commands = await menu(byText("Ideas").id);
    assert.ok(commands.includes("frames:present"), commands.join(" "));
    assert.ok(commands.includes("frames:export"));
    doc.querySelector('#context-menu [data-command="frames:export"]').click();
    await tick();
    assert.equal(doc.querySelector("#export-scope").value, "frames");
    assert.deepEqual(
      [...doc.querySelectorAll("#export-frames input:checked")].map(
        (i) => i.value,
      ),
      [byText("Ideas").id],
      "Only the selected frame is chosen",
    );
    doc.querySelector("dialog[open]").close();
    await menu(byText("Ideas").id);
    doc.querySelector('#context-menu [data-command="frames:present"]').click();
    await tick();
    await click("#start-presentation");
    assert.match(
      doc.querySelector("#slide-count").textContent,
      /^2 \/ 2/,
      "It starts at the selected frame",
    );
    await click("#slide-exit");
  } finally {
    await app.close();
  }
});

test("the object outline tells facilitators which objects participants cannot see", async () => {
  const app = await setup();
  const { doc, click } = app;
  try {
    const { selected } = await rotationFixture(app, [
      item("note", 0, 0, { text: "Answer key" }),
      item("note", 400, 0, { text: "Prompt" }),
    ]);
    const key = selected.find((i) => i.text === "Answer key");
    const description = (id) => {
      const button = doc.querySelector(`#board-outline [data-id="${id}"]`);
      const ref = button.getAttribute("aria-describedby");
      return ref ? doc.getElementById(ref)?.textContent || "" : "";
    };
    doc.querySelector(`#board-outline [data-id="${key.id}"]`).click();
    await click('[data-action="hide-objects"]');
    assert.match(description(key.id), /Hidden from participants/);
    const other = selected.find((i) => i.text === "Prompt");
    assert.doesNotMatch(description(other.id), /Hidden/);
    await click('[data-action="show-objects"]');
    assert.doesNotMatch(description(key.id), /Hidden/);
  } finally {
    await app.close();
  }
});

