test("sticky notes people add from the keyboard while looking at the same place sit side by side", async () => {
  const room = "keyboard-notes";
  const shared = await sharedEditors(room, [], 2);
  const [a, b] = shared.apps;
  const server = async () =>
    (await shared.env.service.load(room)).doc
      .snapshot()
      .items.filter((i) => i.type === "note");
  const press = async (app) => {
    app.doc.querySelector("#canvas").focus();
    app.doc.body.dispatchEvent(
      new app.w.KeyboardEvent("keydown", { key: "n", bubbles: true }),
    );
    await app.tick();
    app.doc
      .querySelector("#canvas-text-editor")
      ?.dispatchEvent(
        new app.w.KeyboardEvent("keydown", { key: "Escape", bubbles: true }),
      );
    await app.tick();
  };
  try {
    // Each starts looking for room in their own direction once they know
    // who else is on the board.
    for (const app of shared.apps)
      app.w.dispatchEvent(new app.w.Event("online"));
    await shared.until(
      () =>
        shared.apps.every((app) =>
          app.doc.querySelector(".participants")?.textContent.startsWith("2"),
        ),
      "Both know who is present",
    );
    await press(a);
    await shared.until(
      async () => (await server()).length === 1,
      "The first note is saved",
    );
    b.w.dispatchEvent(new b.w.Event("online"));
    await shared.until(
      () => b.doc.querySelectorAll("#board-outline [data-id]").length === 1,
      "The other person sees it",
    );
    await press(b);
    // And the first person adds another, in a row.
    await press(a);
    await shared.until(
      async () => (await server()).length === 3,
      "Every note is saved",
    );
    const notes = await server();
    for (const [n, p] of notes.entries())
      for (const q of notes.slice(n + 1))
        assert.ok(
          p.x >= q.x + q.w ||
            q.x >= p.x + p.w ||
            p.y >= q.y + q.h ||
            q.y >= p.y + p.h,
          `${p.x},${p.y} and ${q.x},${q.y} overlap`,
        );
  } finally {
    await shared.close();
  }
});

test("shared sticky notes name who added them, in the outline and on request on the board", async () => {
  const room = "note-authors";
  const shared = await sharedEditors(room, [], 2);
  const [a, b] = shared.apps;
  try {
    b.doc.querySelector("#canvas").focus();
    b.doc.body.dispatchEvent(
      new b.w.KeyboardEvent("keydown", { key: "n", bubbles: true }),
    );
    await b.tick();
    b.doc
      .querySelector("#canvas-text-editor")
      ?.dispatchEvent(
        new b.w.KeyboardEvent("keydown", { key: "Escape", bubbles: true }),
      );
    let note;
    await shared.until(async () => {
      const board = (await shared.env.service.load(room)).doc.snapshot();
      note = board.items.find((i) => i.type === "note");
      return note;
    }, "The note is saved");
    // Nothing is added to the board to say so: the worker knows whose
    // browser session first wrote it.
    const board = (await shared.env.service.load(room)).doc.snapshot();
    assert.equal(board.workshop, undefined);
    // The other person's object list names who added it.
    a.w.dispatchEvent(new a.w.Event("online"));
    const described = () => {
      const button = a.doc.querySelector(
        `#board-outline [data-id="${note.id}"]`,
      );
      const id = button?.getAttribute("aria-describedby");
      return id && a.doc.getElementById(id)?.textContent;
    };
    await shared.until(
      () => described()?.includes(`Added by ${collaborator.username}`),
      "The outline says who added the note",
    );
    // While anonymous input is on, notes no workshop recorded name no one.
    await commitAs(shared.env.service, owner, room, (board) => {
      board.workshop = { settings: { anonymous: true } };
    });
    a.w.dispatchEvent(new a.w.Event("online"));
    await shared.until(
      () => !described()?.includes("Added by"),
      "Anonymous input hides who added notes",
    );
    // Seeing authors on the board is a choice kept on the device.
    const box = a.doc.querySelector("#show-authors");
    assert.equal(box.checked, false);
    box.checked = true;
    box.dispatchEvent(new a.w.Event("change"));
    await a.tick();
    assert.equal(a.w.localStorage.getItem("whiteboard-show-authors"), "true");
    assert.match(a.doc.querySelector("#toast").textContent, /show who added/);
  } finally {
    await shared.close();
  }
});

