test("the tour offered while a shared board reconnects follows the person's role", async () => {
  const shared = await sharedEditors("tour-while-connecting", [
    item("note", 0, 0, { text: "A" }),
  ]);
  const [, b] = shared.apps;
  try {
    await b.click('[data-action="home"]');
    await shared.until(() => b.doc.querySelector("[data-open]"), "Library");
    b.w.localStorage.removeItem("whiteboard-tour-v1");
    // The board opens from this device while the server has not yet
    // answered, so the role is the one it last gave.
    const exec = b.w.puter.workers.exec;
    const held = [];
    b.w.puter.workers.exec = (url, options) =>
      new Promise((resolve) => held.push(() => resolve(exec(url, options))));
    await b.click("[data-open]");
    await shared.until(() => b.doc.querySelector("#canvas"), "Board opened");
    assert.equal(
      b.doc.querySelector('[data-action="tool-note"]').disabled,
      true,
      "Tools wait for the connection",
    );
    await b.click('#tour-offer [data-action="tour"]');
    const titles = [];
    for (let n = 0; n < 12 && b.doc.querySelector(".tour-bubble"); n++) {
      titles.push(b.doc.querySelector("#tour-title").textContent);
      b.doc.querySelector("#tour-next").click();
    }
    assert.equal(titles.length, 8, titles.join(" / "));
    b.w.puter.workers.exec = exec;
    for (const release of held) release();
    await new Promise((r) => setTimeout(r, 300));
  } finally {
    await shared.close();
  }
});

test("the comments panel follows a change between viewer and commenter access", async () => {
  const room = "viewer-to-commenter";
  const shared = await sharedEditors(room, [item("note", 0, 0, { text: "A" })]);
  const role = async (value) => {
    await shared.env.service.call(owner, {
      op: "role",
      room,
      uuid: collaborator.uuid,
      role: value,
    });
    b.w.dispatchEvent(new b.w.Event("online"));
  };
  const [, b] = shared.apps;
  try {
    await role("viewer");
    await shared.until(
      () => b.doc.querySelector(".editor.shared-viewer"),
      "Viewer access received",
    );
    await b.click('[data-action="comments"]');
    assert.equal(b.doc.querySelector("#comment-new").disabled, true);
    // Only a presence check-in reports the change; no synchronization
    // redraws the board meanwhile.
    const exec = b.w.puter.workers.exec;
    let held = [];
    b.w.puter.workers.exec = (url, options) =>
      JSON.parse(options.body).op === "sync"
        ? new Promise((resolve) => held.push(() => resolve(exec(url, options))))
        : exec(url, options);
    await role("commenter");
    await shared.until(
      () => !b.doc.querySelector("#comment-new").disabled,
      "Commenters can start a discussion without redrawing the board",
    );
    b.w.puter.workers.exec = exec;
    for (const release of held) release();
    held = [];
    await role("viewer");
    await shared.until(
      () => b.doc.querySelector("#comment-new").disabled,
      "Viewers can no longer start a discussion",
    );
    // Let the check-in and synchronization finish before closing.
    await new Promise((r) => setTimeout(r, 500));
  } finally {
    await shared.close();
  }
});

test("removing someone from the Participants dialog takes a second press, and saved changes are said", async () => {
  const shared = await sharedEditors("participants-remove", [
    item("note", 0, 0, { text: "A" }),
  ]);
  const [a, b] = shared.apps;
  try {
    await a.click('[data-action="participants"]');
    const select = () =>
      [...a.doc.querySelectorAll("#participant-list select")].find(
        (s) => !s.disabled,
      );
    await shared.until(() => select(), "A member who can be changed");
    const roles = [];
    const exec = a.w.puter.workers.exec;
    a.w.puter.workers.exec = (url, options) => {
      const body = JSON.parse(options.body);
      if (body.op === "role") roles.push(body.role);
      return exec(url, options);
    };
    // Arrow keys on a closed menu, or a slip, can only choose a role.
    assert.ok(![...select().options].some((o) => o.value === "removed"));
    const status = a.doc.querySelector("#participant-status");
    assert.equal(status.getAttribute("role"), "status");
    select().value = "viewer";
    select().dispatchEvent(new a.w.Event("change", { bubbles: true }));
    await shared.until(() => status.textContent === "Role changed.", "Said");
    assert.deepEqual(roles, ["viewer"]);
    const remove = select()
      .closest(".participant-row")
      .querySelector("[data-remove-member]");
    assert.equal(remove.textContent, "Remove");
    remove.focus();
    remove.click();
    for (let n = 0; n < 5; n++) await a.tick();
    assert.deepEqual(roles, ["viewer"], "The first press only asks");
    assert.equal(remove.textContent, "Confirm remove");
    assert.match(remove.getAttribute("aria-label"), /^Confirm remove /);
    remove.click();
    await shared.until(
      () => status.textContent === "Participant removed.",
      "Removal is said",
    );
    assert.deepEqual(roles, ["viewer", "removed"]);
    assert.equal(remove.isConnected, false, "Removed people leave the list");
    assert.equal(a.doc.activeElement, a.doc.querySelector("#access-search"));
    assert.equal(
      a.doc.querySelector("#access-removed").parentElement.hidden,
      false,
      "They can be shown again",
    );
    await shared.until(
      () =>
        /Access changed/.test(b.doc.querySelector("#save-state").textContent),
      "Bob loses access",
    );
    a.w.puter.workers.exec = exec;
  } finally {
    await shared.close();
  }
});

test("the Participants dialog shows when a guest's access ends, and renews it", async () => {
  const shared = await sharedEditors("participants-guest-ends", [
    item("note", 0, 0, { text: "A" }),
  ]);
  const [a] = shared.apps;
  try {
    const exec = a.w.puter.workers.exec;
    const renewed = [];
    const until = new Date(2030, 0, 15, 12).getTime();
    a.w.puter.workers.exec = async (url, options) => {
      const body = JSON.parse(options.body);
      if (body.op === "renew") {
        renewed.push(body.uuid);
        return Response.json({
          member: {
            uuid: body.uuid,
            role: "editor",
            guest: true,
            accessEnds: until,
          },
        });
      }
      const response = await exec(url, options);
      if (body.op !== "members") return response;
      const data = await response.json();
      data.members = [
        ...data.members.map((m) =>
          m.role === "owner"
            ? m
            : {
                ...m,
                guest: true,
                accessEnds: Date.now() - 1000,
                inactive: true,
              },
        ),
        {
          uuid: "u-later",
          username: "Lee",
          role: "viewer",
          guest: true,
          accessEnds: until,
        },
        { uuid: "u-gone", username: "Gone", role: "viewer", inactive: true },
      ];
      return Response.json(data);
    };
    await a.click('[data-action="participants"]');
    const row = (name) =>
      [...a.doc.querySelectorAll(".participant-row")].find(
        (r) => r.querySelector(".participant-name").textContent === name,
      );
    await shared.until(() => row("Gone"), "Board access is listed");
    const note = (name) =>
      row(name).querySelector(".participant-note span").textContent;
    const renew = (name) => row(name).querySelector("[data-renew-member]");
    assert.equal(note("Lee"), "Access until Jan 15, 2030");
    assert.equal(renew("Lee").hidden, false);
    assert.equal(note("Gone"), "Can no longer open this board");
    assert.equal(renew("Gone").hidden, true);
    const bob = [...a.doc.querySelectorAll(".participant-name")]
      .map((n) => n.textContent)
      .find((n) => !["Lee", "Gone"].includes(n) && note(n));
    assert.equal(note(bob), "Guest access ended");
    assert.equal(
      renew(bob).getAttribute("aria-label"),
      `Renew access for ${bob}`,
    );
    renew(bob).click();
    const status = a.doc.querySelector("#participant-status");
    await shared.until(
      () => status.textContent === "Access renewed until Jan 15, 2030.",
      "Renewal is said",
    );
    assert.equal(renewed.length, 1);
    assert.equal(note(bob), "Access until Jan 15, 2030");
    a.w.puter.workers.exec = exec;
    a.doc.querySelector("dialog").close();
    for (let n = 0; n < 10; n++) await a.tick();
  } finally {
    await shared.close();
  }
});

