test("viewers see no drop target and cannot drop content onto a shared board", async () => {
  const room = "viewer-drop-target";
  const shared = await sharedEditors(room, [item("note", 0, 0, { text: "A" })]);
  const [a, b] = shared.apps;
  const drag = (app, type) => {
    const data = transferData({ "text/plain": "Hello" });
    const event = dispatchTransfer(app, type, data);
    return { event, data };
  };
  try {
    drag(a, "dragenter");
    const editor = drag(a, "dragover");
    assert.equal(editor.data.dropEffect, "copy");
    assert.ok(
      a.doc.querySelector(".canvas-wrap").classList.contains("drop-target"),
    );
    drag(a, "dragleave");
    await shared.env.service.call(owner, {
      op: "role",
      room,
      uuid: collaborator.uuid,
      role: "viewer",
    });
    b.w.dispatchEvent(new b.w.Event("online"));
    await shared.until(
      () => b.doc.querySelector(".editor").classList.contains("shared-viewer"),
      "Bob becomes a viewer",
    );
    drag(b, "dragenter");
    const viewer = drag(b, "dragover");
    assert.equal(
      b.doc.querySelector(".canvas-wrap").classList.contains("drop-target"),
      false,
    );
    // Still handled, so the browser does not open a dropped file instead.
    assert.equal(viewer.event.defaultPrevented, true);
    assert.equal(viewer.data.dropEffect, "none");
    // Let the role change's check-ins finish before closing.
    await new Promise((r) => setTimeout(r, 500));
  } finally {
    await shared.close();
  }
});

test("viewers are refused as insert tools open, not after filling them in", async () => {
  const room = "viewer-insert-refusals";
  const shared = await sharedEditors(room, [item("note", 0, 0, { text: "A" })]);
  const [, b] = shared.apps;
  try {
    await shared.env.service.call(owner, {
      op: "role",
      room,
      uuid: collaborator.uuid,
      role: "viewer",
    });
    b.w.dispatchEvent(new b.w.Event("online"));
    await shared.until(
      () => b.doc.querySelector(".editor").classList.contains("shared-viewer"),
      "Bob becomes a viewer",
    );
    let picked = 0;
    const nativeClick = b.w.HTMLInputElement.prototype.click;
    b.w.HTMLInputElement.prototype.click = function () {
      if (this.type === "file") picked++;
      else nativeClick.call(this);
    };
    for (const feature of ["link", "table", "components", "icons", "file"]) {
      b.doc.querySelector("#toast").textContent = "";
      await b.click('[data-action="more-tools"]');
      await b.click(`dialog[open] [data-feature="${feature}"]`);
      assert.equal(b.doc.querySelector("dialog[open]"), null, feature);
      assert.match(b.doc.querySelector("#toast").textContent, /read-only/);
    }
    assert.equal(picked, 0, "no file picker opens");
    // Add image in the tool rail is unavailable, like the other insert tools.
    const image = b.doc.querySelector('.left-rail [data-action="image"]');
    assert.equal(image.disabled, true);
    image.disabled = false;
    await b.click('.left-rail [data-action="image"]');
    assert.equal(picked, 0, "Add image refuses before the file picker");
    // Ideas are not generated when they could not be added.
    b.doc.querySelector("#toast").textContent = "";
    await b.click('[data-action="ai"]');
    b.doc.querySelector('[data-ai="generate"]').disabled = false;
    await b.click('[data-ai="generate"]');
    assert.equal(b.doc.querySelector("#ai-generate"), null);
    assert.match(b.doc.querySelector("#toast").textContent, /read-only/);
    await new Promise((r) => setTimeout(r, 500));
  } finally {
    await shared.close();
  }
});

test("refusals tell viewers and commenters why and what they can do instead", async () => {
  const note = item("note", 100, 100, { w: 200, h: 200, text: "A" });
  const viewerReason =
    "This board is read-only for you. Ask the owner or a facilitator for access to edit or comment.";
  const commenterReason =
    "This board's content is read-only for you. Choose Comment (C) to discuss it.";
  // Each role is given once, on a board of its own.
  const as = async (role, className, check) => {
    const room = `role-aware-refusals-${role}`;
    const shared = await sharedEditors(room, [note]);
    const [, b] = shared.apps;
    try {
      await shared.env.service.call(owner, {
        op: "role",
        room,
        uuid: collaborator.uuid,
        role,
      });
      b.w.dispatchEvent(new b.w.Event("online"));
      await shared.until(
        () => b.doc.querySelector(`.editor.${className}`),
        `Bob becomes a ${role}`,
      );
      const toast = () => b.doc.querySelector("#toast").textContent;
      const press = async (key) => {
        b.doc.querySelector("#toast").textContent = "";
        b.doc
          .querySelector("#canvas")
          .dispatchEvent(
            new b.w.KeyboardEvent("keydown", { key, bubbles: true }),
          );
        await b.tick();
        return toast();
      };
      await check(b, press, toast);
      await new Promise((r) => setTimeout(r, 500));
    } finally {
      await shared.close();
    }
  };
  await as("viewer", "shared-viewer", async (b, press, toast) => {
    // A tool key that cannot be used says why rather than nothing.
    assert.equal(await press("n"), viewerReason);
    assert.equal(await press("c"), viewerReason);
    // So does trying to drag an object.
    b.doc.querySelector("#toast").textContent = "";
    const v = renderedView(b);
    const at = (x, y) => [v.x + x * v.z, v.y + y * v.z];
    for (const [type, x] of [
      ["pointerdown", 200],
      ["pointermove", 240],
      ["pointerup", 240],
    ])
      canvasPointer(b, type, 1, ...at(x, x), { pointerType: "mouse" });
    await b.tick();
    assert.equal(toast(), viewerReason);
    // Unavailable tools carry the reason for their tooltips.
    const noteTool = b.doc.querySelector('[data-action="tool-note"]');
    assert.equal(noteTool.disabled, true);
    assert.equal(noteTool.dataset.disabledReason, viewerReason);
    const over = new b.w.MouseEvent("pointerover", { bubbles: true });
    Object.defineProperty(over, "pointerType", { value: "mouse" });
    noteTool.dispatchEvent(over);
    await new Promise((r) => setTimeout(r, 350));
    const tip = b.doc.querySelector(".ui-tooltip");
    assert.equal(tip.hidden, false);
    assert.equal(
      tip.querySelector("span").textContent,
      `Sticky note. ${viewerReason}`,
    );
    assert.equal(tip.querySelector("kbd").hidden, true);
    // Comments say why there is no New comment.
    await b.click('[data-action="comments"]');
    const access = b.doc.querySelector("#comment-access");
    assert.equal(b.doc.querySelector("#comment-new").disabled, true);
    assert.equal(access.hidden, false);
    assert.equal(access.textContent, viewerReason);
  });
  await as("commenter", "shared-commenter", async (b, press) => {
    const noteTool = b.doc.querySelector('[data-action="tool-note"]');
    assert.equal(noteTool.dataset.disabledReason, commenterReason);
    assert.equal(
      b.doc.querySelector('[data-action="tool-comment"]').dataset
        .disabledReason,
      undefined,
    );
    assert.equal(await press("n"), commenterReason);
    await b.click('[data-action="comments"]');
    assert.equal(b.doc.querySelector("#comment-access").hidden, true);
  });
});

test("moving many drawings at once shows the move live to others", async () => {
  const strokes = Array.from({ length: 8 }, (_, n) =>
    item("pen", 100, 100 + n * 20, {
      w: 300,
      h: 10,
      points: Array.from({ length: 256 }, (_, k) => [
        k * 1.1719 + 0.123456789012345,
        5 + Math.sin(k / 7) * 4.987654321,
      ]),
    }),
  );
  const shared = await sharedEditors("many-drawings-move", strokes);
  const [a, b] = shared.apps;
  const pointer = (app, type, p) => {
    const v = renderedView(app);
    canvasPointer(app, type, 1, v.x + p.x * v.z, v.y + p.y * v.z, {
      pointerType: "mouse",
    });
  };
  try {
    await shared.until(() => {
      pointer(b, "pointermove", { x: 50, y: 50 });
      return !!a.doc.querySelector(".participant-cursor");
    }, "Bob's cursor reaches Alice");
    b.doc.querySelector("#canvas").dispatchEvent(
      new b.w.KeyboardEvent("keydown", {
        key: "a",
        ctrlKey: true,
        bubbles: true,
        cancelable: true,
      }),
    );
    await b.tick();
    await shared.until(
      () => a.doc.querySelectorAll(".participant-selection").length === 8,
      "Alice sees Bob's selection",
    );
    const left = () =>
      parseFloat(a.doc.querySelector(".participant-selection").style.left);
    const before = left();
    // On the first stroke, away from the selection's corner handles.
    const [px, py] = strokes[0].points[64];
    const start = { x: 100 + px, y: 100 + py };
    pointer(b, "pointerdown", start);
    for (let dx = 20; dx <= 200; dx += 20)
      pointer(b, "pointermove", { x: start.x + dx, y: start.y });
    await shared.until(
      () => left() > before + 100,
      "Alice sees the drawings move while Bob drags",
    );
    pointer(b, "pointerup", { x: start.x + 200, y: start.y });
    await shared.until(async () => {
      const { doc } = await shared.env.service.load("many-drawings-move");
      try {
        return doc.snapshot().items.every((i) => i.x === 300);
      } finally {
        doc.destroy();
      }
    }, "The move is saved");
    await new Promise((r) => setTimeout(r, 1500));
  } finally {
    await shared.close();
  }
});

test("a shared board whose server cannot be reached says it is retrying and why it is view only", async () => {
  const note = item("note", 0, 0, { text: "A" });
  const shared = await sharedEditors("server-unreachable", [note], 1);
  const [a] = shared.apps;
  try {
    await a.click('[data-action="home"]');
    for (let n = 0; n < 20; n++) await a.tick();
    // Every request to the board's server fails; the browser is online.
    shared.env.offline = true;
    a.doc.querySelector("[data-open]").click();
    const state = () => a.doc.querySelector("#save-state")?.textContent;
    await shared.until(
      () => state() === "Cannot reach the shared board · retrying · view only",
      "The status says it is retrying, view only",
    );
    await a.click(`#board-outline [data-id="${note.id}"]`);
    await a.click('[data-action="delete"]');
    assert.equal(
      a.doc.querySelector("#toast").textContent,
      "Cannot reach the shared board. It is view only until it reconnects.",
    );
    shared.env.offline = false;
    await shared.until(
      () => /live/.test(state()),
      "It connects by itself once the server is back",
    );
  } finally {
    await shared.close();
  }
});

test("reopening a shared board whose waiting edits cannot be saved yet keeps it editable and says why", async () => {
  const notes = [
    item("note", 0, 0, { text: "A" }),
    item("note", 300, 0, { text: "B" }),
  ];
  const shared = await sharedEditors("first-upload-fails", notes, 1);
  const [a] = shared.apps;
  // The board's server is up but refuses to save edits for a while.
  const call = shared.env.service.call.bind(shared.env.service);
  let busy = true;
  shared.env.service.call = (identity, input) =>
    busy && input.op === "commit"
      ? Promise.reject(Object.assign(Error("Worker busy"), { status: 503 }))
      : call(identity, input);
  const state = () => a.doc.querySelector("#save-state")?.textContent;
  try {
    await a.click(`#board-outline [data-id="${notes[0].id}"]`);
    await a.click('[data-action="delete"]');
    await shared.until(
      () => state() === "Offline · changes saved on this device",
      "The edit waits on this device",
    );
    await a.click('[data-action="home"]');
    for (let n = 0; n < 20; n++) await a.tick();
    a.doc.querySelector("[data-open]").click();
    await shared.until(
      () => a.doc.querySelector(`#board-outline [data-id="${notes[1].id}"]`),
      "The board opens",
    );
    for (let n = 0; n < 40; n++) await a.tick();
    assert.equal(state(), "Offline · changes saved on this device");
    assert.notEqual(a.doc.querySelector("#toast").textContent, "Worker busy");
    // Still editable: another deletion is taken.
    await a.click(`#board-outline [data-id="${notes[1].id}"]`);
    await a.click('[data-action="delete"]');
    assert.equal(
      a.doc.querySelector(`#board-outline [data-id="${notes[1].id}"]`),
      null,
    );
    busy = false;
    await shared.until(
      () => /live/.test(state()),
      "The waiting edits are saved once the server takes them",
    );
    await shared.until(async () => {
      const { doc } = await shared.env.service.load("first-upload-fails");
      try {
        return doc.snapshot().items.length === 0;
      } finally {
        doc.destroy();
      }
    }, "Both deletions reach the board");
  } finally {
    await shared.close();
  }
});

test("reopening a shared board while it connects leaves one live session", async () => {
  const room = "reopen-while-connecting";
  const shared = await sharedEditors(
    room,
    [item("note", 0, 0, { text: "a" })],
    1,
  );
  const [app] = shared.apps;
  const presences = () =>
    [...shared.env.data.keys()].filter((k) =>
      k.startsWith(`wb:${room}:presence:`),
    );
  try {
    await app.click('[data-action="home"]');
    for (let n = 0; n < 10; n++) await app.tick();
    assert.equal(presences().length, 0);
    const puter = app.w.puter,
      getUser = puter.auth.getUser;
    puter.auth.getUser = async () => {
      await new Promise((r) => setTimeout(r, 300));
      return getUser();
    };
    app.doc.querySelector("[data-open]").click();
    await app.tick();
    await app.click('[data-action="home"]');
    app.doc.querySelector("[data-open]").click();
    for (let n = 0; n < 80; n++) await app.tick();
    puter.auth.getUser = getUser;
    assert.equal(presences().length, 1, "one session checks in");
    await app.click('[data-action="home"]');
    for (let n = 0; n < 40; n++) await app.tick();
    assert.equal(presences().length, 0, "and none remains after leaving");
  } finally {
    await shared.close();
  }
});

test("leaving a shared board right after an edit sends it, and warns on closing when it could not", async () => {
  const room = "leave-right-after-edit";
  const shared = await sharedEditors(
    room,
    [item("note", 0, 0, { text: "a" })],
    1,
  );
  const [app] = shared.apps;
  const saved = async () => {
    const { doc } = await shared.env.service.load(room);
    try {
      return doc.snapshot().title;
    } finally {
      doc.destroy();
    }
  };
  const closing = () => {
    const e = new app.w.Event("beforeunload", { cancelable: true });
    app.w.dispatchEvent(e);
    return e.defaultPrevented;
  };
  const rename = (value) => {
    const title = app.doc.querySelector("#board-title");
    title.value = value;
    title.dispatchEvent(new app.w.Event("change"));
  };
  try {
    rename("Renamed just before leaving");
    await app.click('[data-action="home"]');
    await shared.until(
      async () => (await saved()) === "Renamed just before leaving",
      "Sent on leaving",
    );
    await shared.until(() => !closing(), "Nothing left to warn about");
    // Offline, the edit waits on this device and closing the tab warns.
    await shared.until(
      () => app.doc.querySelector("[data-open]"),
      "The library shows the board",
    );
    app.doc.querySelector("[data-open]").click();
    await shared.until(
      () => app.doc.querySelector("#board-title"),
      "The board opens again",
    );
    await shared.until(
      () =>
        !app.doc.querySelector("#board-title").disabled &&
        [...shared.env.data.keys()].some((k) =>
          k.startsWith(`wb:${room}:presence:`),
        ),
      "Connected",
    );
    shared.env.offline = true;
    rename("Renamed offline");
    await app.click('[data-action="home"]');
    await shared.until(
      () => !app.doc.querySelector("#canvas"),
      "Back in the library",
    );
    assert.equal(closing(), true);
    shared.env.offline = false;
    // Opening it again sends it.
    await shared.until(
      () => app.doc.querySelector("[data-open]"),
      "The library shows the board again",
    );
    app.doc.querySelector("[data-open]").click();
    await shared.until(
      async () => (await saved()) === "Renamed offline",
      "Sent after reopening",
    );
    await shared.until(() => !closing(), "No warning once sent");
    await new Promise((r) => setTimeout(r, 500));
  } finally {
    await shared.close();
  }
});

