test("a shared edit is sent and received without structuredClone for each object", async () => {
  const notes = Array.from({ length: 200 }, (_, n) =>
    item("note", (n % 20) * 220, Math.floor(n / 20) * 220, {
      text: `Idea ${n}`,
    }),
  );
  const shared = await sharedEditors("plain-copies", notes);
  const [a, b] = shared.apps;
  const state = (app) => app.doc.querySelector("#save-state").textContent;
  try {
    for (const app of [a, b])
      await shared.until(() => /^Saved ·/.test(state(app)), "Saved");
    // Joining has finished.
    await new Promise((r) => setTimeout(r, 1000));
    // Boards are plain data: copying one object at a time with
    // structuredClone() made each edit of a large board take a long time.
    let calls = 0;
    for (const app of [a, b]) {
      const copy = app.w.structuredClone;
      app.w.structuredClone = (value) => {
        calls++;
        return copy(value);
      };
    }
    const title = a.doc.querySelector("#board-title");
    title.value = "Renamed";
    title.dispatchEvent(new a.w.Event("change"));
    await shared.until(
      () => b.doc.title.startsWith("Renamed"),
      "the new name reaches Bob",
    );
    await shared.until(() => /^Saved ·/.test(state(a)), "Saved again");
    assert.ok(calls < 40, `${calls} objects copied with structuredClone`);
  } finally {
    await shared.close();
  }
});

