function simulateCanvasTextInput(app, text) {
  const input = app.doc.querySelector("#canvas-text-editor");
  const start = input.selectionStart,
    end = input.selectionEnd,
    direction = input.selectionDirection;
  input.focus();
  input.setSelectionRange(start, end, direction);
  input.dispatchEvent(
    new app.w.InputEvent("beforeinput", {
      inputType: "insertText",
      data: text,
      bubbles: true,
      cancelable: true,
    }),
  );
  const selection = app.w.getSelection(),
    range = selection.getRangeAt(0);
  range.deleteContents();
  const node = app.doc.createTextNode(text);
  range.insertNode(node);
  range.setStartAfter(node);
  range.collapse(true);
  selection.removeAllRanges();
  selection.addRange(range);
  input.dispatchEvent(
    new app.w.InputEvent("input", {
      inputType: "insertText",
      data: text,
      bubbles: true,
    }),
  );
}

async function createGeneratedText(app, mode) {
  if (mode === "command") {
    await app.click('[data-action="commands"]');
    paletteQuery(app, app.doc.documentElement.lang === "fr" ? "texte" : "text");
    await app.click('[data-command="add:text"]');
  } else if (mode === "keyboard") {
    const canvas = app.doc.querySelector("#canvas");
    canvas.focus();
    canvas.dispatchEvent(
      new app.w.KeyboardEvent("keydown", {
        key: "t",
        bubbles: true,
        cancelable: true,
      }),
    );
  } else {
    await app.click('[data-action="tool-text"]');
    canvasPointer(app, "pointerdown", 91, 700, 500, { pointerType: mode });
    canvasPointer(app, "pointerup", 91, 700, 500, { pointerType: mode });
  }
  await app.tick();
  const input = app.doc.querySelector("#canvas-text-editor");
  assert.ok(input);
  assert.equal(app.doc.activeElement, input);
  return input;
}

test("generated basic text captions retain their source declarations across every creation path, language switches and reopening", async () => {
  const app = await setup(),
    { doc, w, click, tick } = app;
  const setLanguage = async (value) => {
    doc.querySelector("#language").value = value;
    doc.querySelector("#language").dispatchEvent(new w.Event("change"));
    await tick();
  };
  try {
    for (const source of ["en", "fr"]) {
      for (const mode of ["mouse", "pen", "touch", "command", "keyboard"]) {
        await setLanguage(source);
        await click('[data-action="new"]');
        doc.querySelector("#canvas").getBoundingClientRect = () => ({
          left: 0,
          top: 0,
          width: 1000,
          height: 800,
        });
        const input = await createGeneratedText(app, mode);
        const text = source === "fr" ? "Votre texte" : "Your text";
        assert.equal(input.value, text);
        assert.ok(input.querySelector(`[lang="${source}"]`));
        assert.equal(
          input.querySelector(`[lang="${source}"]`).textContent,
          text,
        );
        await click('[data-action="finish-text"]');
        const [saved] = allClipboard(app);
        validateBoard({ ...board(), items: [saved] });
        assert.equal(saved.text, text);
        assert.equal(saved.lang, undefined);
        assert.deepEqual(saved.textRuns, [
          { start: 0, end: text.length, style: { lang: source } },
        ]);
        await setLanguage(source === "fr" ? "en" : "fr");
        assert.equal(
          doc.querySelector(
            `#board-outline [data-id="${saved.id}"] [lang="${source}"]`,
          ).textContent,
          text,
        );
        await click('[data-action="undo"]');
        assert.equal(doc.querySelectorAll("#board-outline button").length, 0);
        await click('[data-action="redo"]');
        assert.deepEqual(allClipboard(app), [saved]);
        await click('[data-action="home"]');
        await click("[data-open]");
        assert.deepEqual(allClipboard(app), [saved]);
        assert.equal(
          doc.querySelector(
            `#board-outline [data-id="${saved.id}"] [lang="${source}"]`,
          ).textContent,
          text,
        );
        await click('[data-action="home"]');
      }
    }
  } finally {
    await tick();
    await app.close();
  }
});

test("new text prompt languages do not classify replacements and explicit whole or passage declarations remain editable", async () => {
  const app = await setup(),
    { doc, w, click, tick } = app;
  const declare = async (scope, language) => {
    await click("#content-language-options");
    doc.querySelector("#content-language-scope").value = scope;
    doc
      .querySelector("#content-language-scope")
      .dispatchEvent(new w.Event("change"));
    doc.querySelector("#content-language-tag").value = language;
    doc
      .querySelector("#content-language-save")
      .closest("form")
      .dispatchEvent(
        new w.Event("submit", { bubbles: true, cancelable: true }),
      );
    await tick();
  };
  try {
    doc.querySelector("#language").value = "fr";
    doc.querySelector("#language").dispatchEvent(new w.Event("change"));
    await click('[data-action="new"]');
    let input = await createGeneratedText(app, "command");
    assert.ok(input.querySelector('[lang="fr"]'));
    simulateCanvasTextInput(app, "An authored heading");
    await click('[data-action="finish-text"]');
    let [saved] = allClipboard(app);
    assert.equal(saved.text, "An authored heading");
    assert.equal(saved.lang, undefined);
    assert.equal(saved.textRuns, undefined);
    await click('[data-action="undo"]');
    assert.equal(allClipboard(app)[0].text, "Votre texte");
    assert.deepEqual(allClipboard(app)[0].textRuns, [
      { start: 0, end: 11, style: { lang: "fr" } },
    ]);
    await click('[data-action="redo"]');
    assert.deepEqual(allClipboard(app), [saved]);
    await click('[data-action="home"]');
    await click('[data-action="new"]');
    input = await createGeneratedText(app, "command");
    input.setSelectionRange(6, 11);
    simulateCanvasTextInput(app, "heading");
    await click('[data-action="finish-text"]');
    [saved] = allClipboard(app);
    assert.equal(saved.text, "Votre heading");
    assert.deepEqual(saved.textRuns, [
      { start: 0, end: 6, style: { lang: "fr" } },
    ]);
    await click('[data-action="home"]');
    await click('[data-action="new"]');
    input = await createGeneratedText(app, "command");
    await declare("text", "fr-CA");
    simulateCanvasTextInput(app, "Bonjour à tous. Hello again.");
    input.setSelectionRange(16, 28);
    await declare("text", "en-CA");
    await declare("object", "fr-CA");
    await click('[data-action="finish-text"]');
    [saved] = allClipboard(app);
    assert.equal(saved.lang, "fr-CA");
    assert.deepEqual(saved.textRuns, [
      { start: 0, end: 16, style: { lang: "fr-CA" } },
      { start: 16, end: 28, style: { lang: "en-CA" } },
    ]);
    doc.querySelector("#language").value = "en";
    doc.querySelector("#language").dispatchEvent(new w.Event("change"));
    await tick();
    assert.equal(
      doc.querySelector(`#board-outline [data-id="${saved.id}"] [lang="en-CA"]`)
        .textContent,
      "Hello again.",
    );
    await click('[data-action="home"]');
    await click("[data-open]");
    assert.deepEqual(allClipboard(app), [saved]);
    const scan = await axe.run(doc.querySelector("#board-outline"), {
      rules: { "color-contrast": { enabled: false } },
    });
    assert.deepEqual(
      scan.violations.map((v) => v.id),
      [],
    );
    // Identical unknown historical text is not assigned a generated declaration.
    await click('[data-action="home"]');
    await rotationFixture(app, [item("text", 0, 0, { text: "Your text" })]);
    const legacy = allClipboard(app).find((i) => i.text === "Your text");
    assert.equal(legacy.lang, undefined);
    assert.equal(legacy.textRuns, undefined);
  } finally {
    await tick();
    await app.close();
  }
});

test("shared basic text creation preserves the generated language while replacement and undo synchronize independently", async () => {
  const room = "generated-text-language";
  const shared = await sharedEditors(room, []);
  try {
    const [a, b] = shared.apps;
    a.doc.querySelector("#language").value = "fr";
    a.doc.querySelector("#language").dispatchEvent(new a.w.Event("change"));
    const input = await createGeneratedText(a, "command");
    await shared.until(
      () =>
        b.doc.querySelector('#board-outline [lang="fr"]')?.textContent ===
        "Votre texte",
      "Generated source declaration reaches the English peer",
    );
    const [seed] = allClipboard(b);
    validateBoard({ ...board(), items: [seed] });
    assert.deepEqual(seed.textRuns, [
      { start: 0, end: 11, style: { lang: "fr" } },
    ]);
    input.select();
    simulateCanvasTextInput(a, "An authored heading");
    await a.click('[data-action="finish-text"]');
    await shared.until(
      async () =>
        (await storedSharedBoard(b, room))?.items[0]?.text ===
        "An authored heading",
      "Replacement synchronizes",
    );
    const [replacement] = allClipboard(b);
    assert.equal(replacement.lang, undefined);
    assert.equal(replacement.textRuns, undefined);
    await a.click('[data-action="undo"]');
    await shared.until(
      () =>
        b.doc.querySelector('#board-outline [lang="fr"]')?.textContent ===
        "Votre texte",
      "Undo restores the source declaration",
    );
    await a.click('[data-action="redo"]');
    await shared.until(
      async () =>
        (await storedSharedBoard(b, room))?.items[0]?.text ===
        "An authored heading",
      "Redo restores replacement",
    );
    assert.deepEqual(allClipboard(b), [replacement]);
    await b.click('[data-action="home"]');
    await b.click("[data-open]");
    await shared.until(
      () =>
        b.doc
          .querySelector("#board-outline")
          ?.textContent.includes("An authored heading"),
      "Shared replacement reopens",
    );
    assert.deepEqual(allClipboard(b), [replacement]);
  } finally {
    for (const app of shared.apps) await app.tick();
    await shared.close();
  }
});

