for (const language of ["en", "fr"])
  test(`built PowerPoint export retains authored title, note and cell languages in ${language}`, async () => {
    const app = await setup(undefined, {
      preferences: { "whiteboard-language": language },
    });
    const { w, doc, click, tick, downloads } = app;
    try {
      assert.equal(doc.querySelector("#language").value, language);
      const frame = item("frame", 0, 0, {
        w: 900,
        h: 620,
        text: "Hello bonjour",
        lang: "en-CA",
        textRuns: [{ start: 6, end: 13, style: { lang: "fr-CA" } }],
      });
      await rotationFixture(app, [
        frame,
        item("note", 20, 70, {
          text: "Bonjour hello",
          lang: "fr",
          textRuns: [{ start: 8, end: 13, style: { lang: "en-GB" } }],
          parentId: frame.id,
        }),
        item("table", 20, 300, {
          cells: [["Bonjour", "hello"]],
          lang: "fr",
          cellLanguages: { "0,1": { lang: "en-GB" } },
          parentId: frame.id,
        }),
      ]);
      const before = selectedClipboard(app);
      assert.equal(before.find((i) => i.type === "frame").lang, "en-CA");
      assert.equal(
        before.find((i) => i.type === "frame").textRuns[0].style.lang,
        "fr-CA",
      );
      assert.equal(
        before.find((i) => i.type === "note").textRuns[0].style.lang,
        "en-GB",
      );
      assert.equal(
        before.find((i) => i.type === "table").cellLanguages["0,1"].lang,
        "en-GB",
      );
      await click('[data-action="export"]');
      for (const [id, value] of [
        ["export-format", "pptx"],
        ["export-scope", "frames"],
      ]) {
        const field = doc.querySelector(`#${id}`);
        field.value = value;
        field.dispatchEvent(new w.Event("change", { bubbles: true }));
      }
      await click('dialog [type="submit"]');
      for (let n = 0; n < 200 && !downloads.length; n++) await tick();
      assert.equal(downloads.length, 1);
      const bytes = await new Promise((resolve, reject) => {
        const reader = new w.FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = reject;
        reader.readAsArrayBuffer(downloads[0]);
      });
      const { readZip } = await import("../src/unzip.js");
      const zip = readZip(bytes);
      const runs = async (path) => {
        const xml = new w.DOMParser().parseFromString(
          await zip.text(path),
          "application/xml",
        );
        assert.equal(xml.querySelector("parsererror"), null);
        return [...xml.getElementsByTagNameNS("*", "r")].map((run) => ({
          text: run.getElementsByTagNameNS("*", "t")[0].textContent,
          lang: run.getElementsByTagNameNS("*", "rPr")[0].getAttribute("lang"),
        }));
      };
      assert.deepEqual(await runs("ppt/slides/slide1.xml"), [
        { text: "Hello ", lang: "en-CA" },
        { text: "bonjour", lang: "fr-CA" },
      ]);
      assert.deepEqual(await runs("ppt/notesSlides/notesSlide1.xml"), [
        { text: "Bonjour ", lang: "fr" },
        { text: "hello", lang: "en-GB" },
        { text: "Bonjour | ", lang: "fr" },
        { text: "hello", lang: "en-GB" },
      ]);
      assert.deepEqual(
        selectedClipboard(app),
        before,
        "export retains objects and their metadata",
      );
    } finally {
      await app.close();
    }
  });

for (const foreign of ["pointerup", "pointercancel", "lostpointercapture"])
  test(`Quick connect ignores another pointer's ${foreign} during a drag`, async () => {
    const app = await setup();
    const { doc, w, click } = app;
    try {
      await click('[data-action="new"]');
      const canvas = doc.querySelector("#canvas");
      canvas.getBoundingClientRect = () => ({
        left: 0,
        top: 0,
        width: 1000,
        height: 800,
      });
      dispatchTransfer(
        app,
        "drop",
        transferData(
          clipboardFormats([
            item("rect", 0, 0, { w: 200, h: 160 }),
            item("ellipse", 500, 200, { w: 200, h: 160 }),
          ]),
        ),
        canvas,
        { clientX: 200, clientY: 200 },
      );
      const original = allClipboard(app);
      await click(`#board-outline [data-id="${original[0].id}"]`);
      const port = doc.querySelector('[data-quick-direction="right"]');
      const pointer = (type, id, x = 800, y = 480) => {
        const event = new w.MouseEvent(type, {
          bubbles: true,
          cancelable: true,
          button: 0,
          clientX: x,
          clientY: y,
        });
        Object.defineProperties(event, {
          pointerId: { value: id },
          pointerType: { value: "touch" },
        });
        port.dispatchEvent(event);
      };
      pointer("pointerdown", 41, 430, 280);
      pointer("pointermove", 41);
      assert.equal(doc.querySelectorAll("#board-outline button").length, 3);
      pointer(foreign, 42);
      assert.equal(
        doc.querySelectorAll("#board-outline button").length,
        3,
        "The owning pointer's draft stays active",
      );
      pointer("pointercancel", 41);
      assert.deepEqual(
        allClipboard(app),
        original,
        "The owning pointer can still cancel without a saved connection",
      );
      assert.equal(doc.querySelector('[data-action="redo"]').disabled, true);
      await click(`#board-outline [data-id="${original[0].id}"]`);
      pointer("pointerdown", 41, 430, 280);
      pointer("pointermove", 41);
      pointer("pointerup", 41);
      const connected = allClipboard(app);
      assert.equal(connected.length, 3);
      assert.equal(connected[2].startId, original[0].id);
      assert.equal(connected[2].endId, original[1].id);
      await click('[data-action="undo"]');
      assert.deepEqual(allClipboard(app), original);
      await click('[data-action="redo"]');
      assert.deepEqual(allClipboard(app), connected);
      await click('[data-action="home"]');
      await click("[data-open]");
      assert.deepEqual(
        allClipboard(app),
        connected,
        "Only the completed connection persists",
      );
      await click('[data-action="home"]');
    } finally {
      await app.close();
    }
  });

