for (const captionHeight of [68, 600])
  test(`CSV keyboard focus reveals the chosen content with a ${captionHeight}px caption without changing authored export data`, async () => {
    const app = await setup();
    try {
      await rotationFixture(app, [
        item("table", 0, 0, {
          cells: [
            ["Bonjour à tous.", "Autre colonne"],
            ["Une valeur", "42"],
          ],
          lang: "fr-CA",
          w: 500,
          h: 200,
        }),
      ]);
      const undo = app.doc.querySelector('[data-action="undo"]').disabled;
      await app.click('[data-action="export"]');
      const format = app.doc.querySelector("#export-format");
      format.value = "csv";
      format.dispatchEvent(new app.w.Event("change", { bubbles: true }));
      const dialog = app.doc.querySelector("dialog[open]"),
        group = app.doc.querySelector("#export-sheet"),
        radio = group.querySelector('input[value^="table:"]');
      const rect = (x, y, w, h) => ({
        x,
        y,
        left: x,
        top: y,
        right: x + w,
        bottom: y + h,
        width: w,
        height: h,
      });
      dialog.getBoundingClientRect = () => rect(14, 20, 292, 360);
      group.getBoundingClientRect = () =>
        rect(39, 253 - dialog.scrollTop, 227, 180);
      radio.getBoundingClientRect = () =>
        rect(
          41,
          365 + (captionHeight - 18) / 2 - dialog.scrollTop - group.scrollTop,
          18,
          18,
        );
      const label = radio.closest("label");
      label.getBoundingClientRect = () =>
        rect(39, 365 - dialog.scrollTop - group.scrollTop, 227, captionHeight);
      // A browser viewport adaptor implements native reveal; the before geometry
      // comes from the real narrow Safari dialog and remains clipped without it.
      app.w.HTMLElement.prototype.scrollIntoView = function () {
        for (const container of [group, dialog]) {
          const target = this.getBoundingClientRect(),
            visible = container.getBoundingClientRect();
          if (target.top < visible.top && target.bottom > visible.bottom)
            continue;
          if (target.bottom > visible.bottom)
            container.scrollTop +=
              target.height > visible.height
                ? target.top - visible.top
                : target.bottom - visible.bottom;
          else if (target.top < visible.top)
            container.scrollTop -=
              target.height > visible.height
                ? visible.bottom - target.bottom
                : visible.top - target.top;
        }
      };
      radio.checked = true;
      radio.focus();
      assert.equal(app.doc.activeElement, radio);
      assert.equal(radio.checked, true);
      assert.equal(
        app.doc.querySelector('[data-action="undo"]').disabled,
        undo,
      );
      for (const container of [group, dialog]) {
        const focused = radio.getBoundingClientRect(),
          visible = container.getBoundingClientRect();
        assert.ok(
          focused.top >= visible.top && focused.bottom <= visible.bottom,
          "Focused selected radio is visible inside each scrolling container",
        );
      }
      assert.equal(
        group.querySelector('[lang="fr-CA"]').textContent,
        "Bonjour à tous., Autre colonne",
      );
      await app.click("dialog button.primary");
      for (let n = 0; n < 100 && !app.downloads.length; n++) await app.tick();
      assert.equal(app.downloads.length, 1);
      const csv = await new Promise((resolve) => {
        const r = new app.w.FileReader();
        r.onload = () => resolve(r.result);
        r.readAsText(app.downloads[0]);
      });
      assert.match(csv, /Bonjour à tous.,Autre colonne/);
    } finally {
      await app.close();
    }
  });

function mindPointerClick(app, button, pointerId) {
  const e = new app.w.MouseEvent("click", { detail: 1, bubbles: true });
  Object.defineProperty(e, "pointerId", { value: pointerId });
  button.dispatchEvent(e);
}
