      if (foreign === "click") {
        const e = new app.w.MouseEvent("click", { detail: 1, bubbles: true });
        Object.defineProperty(e, "pointerId", { value: 42 });
        pin.dispatchEvent(e);
      } else if (foreign !== "control")
        cropPointer(app, pin, foreign, 42, 620, 200);
      assert.equal(
        app.doc.querySelector("#comments-panel"),
        null,
        "Foreign events cannot open the discussion during an owned move",
      );
      assert.equal(
        parseFloat(pin.style.left),
        start + 120,
        "A foreign pointer preserves the draft",
      );
      cropPointer(app, pin, "pointermove", 41, 660, 200);
