test("keys and clipboard actions in the comments panel and on pins leave the selected objects alone", async () => {
  const app = await setup();
  const { doc, w, click, tick } = app;
  try {
    await click('[data-action="new"]');
    const canvas = doc.querySelector("#canvas");
    canvas.getBoundingClientRect = () => ({
      left: 0,
      top: 0,
      width: 1200,
      height: 900,
    });
    dispatchTransfer(
      app,
      "paste",
      transferData({ "text/plain": "Commented note" }),
    );
    const [source] = selectedClipboard(app);
    await click('[data-action="add-comment"]');
    doc.querySelector("#comment-text").value = "Please review";
    await click('#comment-form [type="submit"]');
    const press = (target, key) =>
      target.dispatchEvent(
        new w.KeyboardEvent("keydown", {
          key,
          bubbles: true,
          cancelable: true,
        }),
      );
    const resolve = doc.querySelector("#comment-resolve");
    resolve.focus();
    for (const key of ["ArrowRight", "Delete", "Backspace", "n"])
      press(resolve, key);
    await tick();
    // Copying from the panel leaves the clipboard to the browser.
    const copied = transferData();
    dispatchTransfer(app, "copy", copied, resolve);
    assert.equal(copied.getData(CLIPBOARD_TYPE), "");
    const pin = doc.querySelector(".comment-pin");
    pin.focus();
    for (const key of ["Delete", "Backspace"]) press(pin, key);
    await tick();
    const after = selectedClipboard(app);
    assert.deepEqual(
      after.map((i) => [i.id, i.x, i.y]),
      [[source.id, source.x, source.y]],
    );
    // Outside the panel, the same keys still act on the selection.
    canvas.focus();
    press(canvas, "Delete");
    await tick();
    assert.equal(doc.querySelectorAll("#board-outline [data-id]").length, 0);
  } finally {
    await app.close();
  }
});

