test("Add comment on a chosen frame attaches the comment to the frame", async () => {
  const app = await setup();
  const { doc, click, tick } = app;
  try {
    await rotationFixture(app, [
      item("frame", 0, 0, { w: 600, h: 400, text: "Sprint" }),
      item("note", 100, 100, { text: "Inside" }),
    ]);
    const frame = [...doc.querySelectorAll("#board-outline [data-id]")].find(
      (button) => /Sprint/.test(button.textContent),
    ).dataset.id;
    await click(`#board-outline [data-id="${frame}"]`);
    await click('[data-action="add-comment"]');
    doc.querySelector("#comment-text").value = "On the frame";
    await click('#comment-form [type="submit"]');
    await tick();
    const database = await new Promise((resolve, reject) => {
      const request = app.w.indexedDB.open("whiteboard-v1", 3);
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
    const boards = await new Promise((resolve) => {
      const request = database
        .transaction("boards", "readonly")
        .objectStore("boards")
        .getAll();
      request.onsuccess = () => resolve(request.result);
    });
    database.close();
    const [comment] = boards.find((b) => b.comments?.length).comments;
    assert.equal(comment.anchorId, frame);
  } finally {
    await app.close();
  }
});

