test("the board library switches between cards and a list, and remembers the choice", async () => {
  const app = await setup();
  const { doc, w, click } = app;
  try {
    const grid = () => doc.querySelector("#board-grid");
    assert.equal(grid().classList.contains("is-list"), false, "Cards first");
    assert.equal(
      doc
        .querySelector('[data-action="view-grid"]')
        .getAttribute("aria-pressed"),
      "true",
    );
    await click('[data-action="view-list"]');
    assert.equal(grid().classList.contains("is-list"), true);
    assert.equal(
      doc
        .querySelector('[data-action="view-list"]')
        .getAttribute("aria-pressed"),
      "true",
    );
    assert.equal(
      doc
        .querySelector('[data-action="view-grid"]')
        .getAttribute("aria-pressed"),
      "false",
    );
    assert.equal(w.localStorage.getItem("whiteboard-library-view"), "list");
    // The list keeps each board's buttons and the meta text it describes
    // the board with.
    await click('[data-action="new"]');
    await click('[data-action="home"]');
    assert.equal(grid().classList.contains("is-list"), true, "Still a list");
    const meta = doc.querySelector(".board-card .board-info p");
    assert.match(meta.textContent, /^\d+ objects? · /);
    assert.ok(doc.querySelector(".board-card [data-favorite]"));
    await click('[data-action="view-grid"]');
    assert.equal(grid().classList.contains("is-list"), false);
  } finally {
    await app.close();
  }
});

test("searching the board library announces how many boards match", async () => {
  const app = await setup();
  const { doc, w, click } = app;
  try {
    for (const title of ["Roadmap", "Retro"]) {
      await click('[data-action="new"]');
      doc.querySelector("#board-title").value = title;
      doc.querySelector("#board-title").dispatchEvent(new w.Event("change"));
      await click('[data-action="add-note"]');
      await click('[data-action="finish-text"]');
      await click('[data-action="home"]');
    }
    const status = () => doc.querySelector("#library-results");
    assert.equal(status().getAttribute("role"), "status");
    assert.equal(status().textContent, "", "Nothing is said before a search");
    const search = doc.querySelector("#search");
    for (const [query, said] of [
      ["r", "2 boards found"],
      ["road", "1 board found"],
      ["zzz", "No boards found"],
      ["", ""],
    ]) {
      search.value = query;
      search.dispatchEvent(new w.Event("input"));
      assert.equal(status().textContent, said, query);
    }
  } finally {
    await app.close();
  }
});

