test("the frame tool offers slide, page and screen sizes, and new frames take the one chosen", async () => {
  const app = await setup();
  const { doc, w, click, tick } = app;
  const press = (name) =>
    doc.querySelector("#canvas").dispatchEvent(
      new w.KeyboardEvent("keydown", {
        key: name,
        code: `Key${name.toUpperCase()}`,
        bubbles: true,
        cancelable: true,
      }),
    );
  const frames = async () =>
    (await storedBoards(app))
      .find((b) => b.items.some((i) => i.type === "frame"))
      ?.items.filter((i) => i.type === "frame")
      .map((i) => [i.w, i.h]);
  try {
    await click('[data-action="new"]');
    assert.equal(doc.querySelector("#frame-formats")?.hidden ?? true, true);
    await click('[data-action="tool-frame"]');
    const panel = doc.querySelector("#frame-formats");
    assert.equal(panel.hidden, false);
    assert.equal(panel.getAttribute("role"), "radiogroup");
    assert.equal(
      panel.previousElementSibling,
      doc.querySelector(".canvas-wrap .left-rail"),
      "It comes right after the tool rail in the Tab order",
    );
    assert.equal(panel.getAttribute("aria-label"), "Frame format");
    assert.equal(
      panel.querySelector('[aria-checked="true"]').dataset.frameFormat,
      "custom",
      "Frames keep their usual size until a format is chosen",
    );
    assert.deepEqual(
      [...panel.querySelectorAll("[data-frame-format]")].map((b) =>
        b.textContent.trim(),
      ),
      [
        "Custom",
        "Slide 16:9",
        "Slide 4:3",
        "Square 1:1",
        "A4",
        "Letter",
        "Phone",
        "Tablet",
        "Desktop",
      ],
    );
    await click('#frame-formats [data-frame-format="16:9"]');
    assert.equal(
      doc
        .querySelector('#frame-formats [data-frame-format="16:9"]')
        .getAttribute("aria-checked"),
      "true",
    );
    assert.equal(
      doc.activeElement.dataset.frameFormat,
      "16:9",
      "The keyboard stays on the choice",
    );
    assert.deepEqual(
      [...panel.querySelectorAll("[data-frame-format]")]
        .filter((b) => b.tabIndex === 0)
        .map((b) => b.dataset.frameFormat),
      ["16:9"],
      "One Tab stop",
    );
    // The arrow keys move to the next format and choose it.
    doc.activeElement.dispatchEvent(
      new w.KeyboardEvent("keydown", { key: "ArrowDown", bubbles: true }),
    );
    assert.equal(doc.activeElement.dataset.frameFormat, "4:3");
    assert.equal(doc.activeElement.getAttribute("aria-checked"), "true");
    doc.activeElement.dispatchEvent(
      new w.KeyboardEvent("keydown", { key: "ArrowUp", bubbles: true }),
    );
    assert.equal(doc.activeElement.dataset.frameFormat, "16:9");
    await click('[data-action="tool-select"]');
    assert.equal(doc.querySelector("#frame-formats").hidden, true);
    press("f");
    await tick();
    await new Promise((r) => setTimeout(r, 400));
    assert.deepEqual(await frames(), [[1280, 720]]);
    // The choice is kept on this device for the next frames.
    assert.equal(
      JSON.parse(w.localStorage.getItem("whiteboard-last-style")).frame.format,
      "16:9",
    );
    await click('[data-action="tool-frame"]');
    await click('#frame-formats [data-frame-format="custom"]');
    await click('[data-action="tool-select"]');
    press("f");
    await tick();
    await new Promise((r) => setTimeout(r, 400));
    assert.deepEqual((await frames())[1], [420, 320]);
  } finally {
    await app.close();
  }
});

test("fill colours and text style open in popovers that stay open across a redraw", async () => {
  const app = await setup();
  const { doc, w, click, tick } = app;
  try {
    await rotationFixture(app, [item("note", 0, 0, { text: "A" })]);
    const id = doc.querySelector("#board-outline [data-id]").dataset.id;
    await click(`#board-outline [data-id="${id}"]`);
    const toggle = doc.querySelector("#fill-options");
    const pop = doc.querySelector("#fill-popover");
    assert.equal(pop.hidden, true, "Colours start closed");
    assert.equal(toggle.getAttribute("aria-controls"), "fill-popover");
    await click("#fill-options");
    assert.equal(doc.querySelector("#fill-popover").hidden, false);
    assert.equal(toggle.getAttribute("aria-expanded"), "true");
    const swatch = doc.querySelectorAll("#fill-popover [data-color]")[1];
    const color = swatch.dataset.color;
    await click(`#fill-popover [data-color="${color}"]`);
    assert.equal(selectedClipboard(app)[0].color, color);
    const reopened = doc.querySelector("#fill-popover");
    assert.equal(reopened.hidden, false, "Still open after the redraw");
    // The current colour is the pressed one, for screen readers too.
    assert.deepEqual(
      [...reopened.querySelectorAll("[aria-pressed=true]")].map(
        (b) => b.dataset.color,
      ),
      [color],
    );
    assert.equal(
      doc.querySelector("#fill-options").style.getPropertyValue("--swatch"),
      color,
      "The button shows the new colour",
    );
    reopened.dispatchEvent(
      new w.KeyboardEvent("keydown", { key: "Escape", bubbles: true }),
    );
    assert.equal(doc.querySelector("#fill-popover").hidden, true);
    assert.equal(doc.activeElement, doc.querySelector("#fill-options"));
    // Opening the text style popover closes the colours; the rarer text
    // settings live in it.
    await click("#fill-options");
    await click("#text-style-options");
    assert.equal(doc.querySelector("#fill-popover").hidden, true);
    const style = doc.querySelector("#text-style-popover");
    assert.equal(style.hidden, false);
    for (const control of ["#format-underline", "#text-align", "#text-color"])
      assert.ok(style.querySelector(control), control);
    // Another selection starts with every popover closed.
    await click('[data-action="add-note"]');
    await click('[data-action="finish-text"]');
    await tick();
    assert.equal(
      doc.querySelector("#text-style-popover")?.hidden ?? true,
      true,
    );
  } finally {
    await app.close();
  }
});

test("Escape closes a colour or text style popover opened by mouse before it clears the selection", async () => {
  const app = await setup();
  const { doc, w } = app;
  try {
    await rotationFixture(app, [item("note", 0, 0, { text: "A" })]);
    const id = doc.querySelector("#board-outline [data-id]").dataset.id;
    await app.click(`#board-outline [data-id="${id}"]`);
    const escape = (target) =>
      target.dispatchEvent(
        new w.KeyboardEvent("keydown", {
          key: "Escape",
          bubbles: true,
          cancelable: true,
        }),
      );
    const selected = () =>
      doc
        .querySelector(`#board-outline [data-id="${id}"]`)
        .getAttribute("aria-pressed");
    for (const [toggleId, popId, focus] of [
      ["#fill-options", "#fill-popover", "#fill-options"],
      ["#text-style-options", "#text-style-popover", "#canvas"],
    ]) {
      // A mouse click opens the popover and leaves focus on its button.
      const toggle = doc.querySelector(toggleId);
      toggle.dispatchEvent(
        new w.MouseEvent("click", { bubbles: true, detail: 1 }),
      );
      await app.tick();
      assert.equal(doc.querySelector(popId).hidden, false, popId);
      const target = doc.querySelector(focus);
      target.focus();
      escape(target);
      assert.equal(doc.querySelector(popId)?.hidden ?? true, true, popId);
      assert.equal(
        selected(),
        "true",
        `Escape on ${focus} keeps the selection`,
      );
      assert.equal(doc.activeElement, target, "Focus stays where it was");
    }
    escape(doc.querySelector("#canvas"));
    assert.equal(selected(), "false", "A second Escape clears the selection");
  } finally {
    await app.close();
  }
});

test("selection popovers open upward when the toolbar sits too low for them below", async () => {
  const app = await setup();
  const { doc, w } = app;
  try {
    // The canvas spans 0 to 900px; each popover is 120px tall.
    await rotationFixture(app, [item("note", 0, 0, { text: "A" })]);
    Object.defineProperty(w.HTMLElement.prototype, "offsetHeight", {
      configurable: true,
      get() {
        return this.classList.contains("selection-popover") ? 120 : 0;
      },
    });
    const id = doc.querySelector("#board-outline [data-id]").dataset.id;
    await app.click(`#board-outline [data-id="${id}"]`);
    const panel = doc.querySelector("#selection-tools");
    const opensAbove = async (top) => {
      panel.getBoundingClientRect = () => ({
        left: 100,
        right: 600,
        top,
        bottom: top + 46,
        width: 500,
        height: 46,
      });
      doc
        .querySelector("#fill-options")
        .dispatchEvent(new w.MouseEvent("click", { bubbles: true, detail: 1 }));
      await app.tick();
      const pop = doc.querySelector("#fill-popover");
      assert.equal(pop.hidden, false);
      const above = pop.classList.contains("is-above");
      doc
        .querySelector("#fill-options")
        .dispatchEvent(new w.MouseEvent("click", { bubbles: true, detail: 1 }));
      await app.tick();
      return above;
    };
    assert.equal(await opensAbove(760), true, "Near the bottom it opens up");
    assert.equal(await opensAbove(300), false, "With room below it opens down");
  } finally {
    await app.close();
  }
});

