test("the floating selection toolbar stays clear of the getting-started offer", async () => {
  const app = await setup();
  const { doc, w } = app;
  try {
    await rotationFixture(app, [item("note", 0, 0, { text: "A" })]);
    const offer = doc.querySelector("#tour-offer");
    assert.ok(offer, "A new visitor is offered the tour");
    const panel = doc.querySelector("#selection-tools");
    for (const [key, value] of [
      ["offsetWidth", 500],
      ["offsetHeight", 46],
    ])
      Object.defineProperty(panel, key, { configurable: true, value });
    const id = doc.querySelector("#board-outline [data-id]").dataset.id;
    const place = async () => {
      await app.click(`#board-outline [data-id="${id}"]`);
      const [, x, y] = panel.style.transform.match(/(-?\d+)px, (-?\d+)px/);
      return { x: Number(x), y: Number(y) };
    };
    const before = await place();
    // The offer covers the bottom 10px of where the toolbar sits.
    const top = before.y + 36;
    offer.getBoundingClientRect = () => ({
      left: before.x + 100,
      right: before.x + 400,
      top,
      bottom: top + 52,
      width: 300,
      height: 52,
    });
    const after = await place();
    assert.ok(after.y + 46 <= top - 12, `${after.y + 46} is above ${top}`);
    assert.equal(after.x, before.x);
  } finally {
    await app.close();
  }
});

