test("viewers see no resize or connector endpoint handles", async () => {
  const env = environment();
  const note = item("note", 30, 30, { text: "Shared thought" });
  const line = item("arrow", 300, 30, { w: 200, h: 100 });
  const initial = {
    version: 1,
    id: crypto.randomUUID(),
    title: "Team canvas",
    items: [note, line],
  };
  const seed = new SharedDocument();
  seed.commit(initial);
  await env.service.call(owner, {
    op: "create",
    room: initial.id,
    update: encode(seed.update()),
  });
  seed.destroy();
  const { token } = await env.service.call(owner, {
    op: "invite",
    room: initial.id,
    role: "viewer",
  });
  const app = await setup(env.sdk(viewer));
  try {
    await app.click('[data-action="join-shared"]');
    app.doc.querySelector("#join-link").value =
      `https://whiteboard.test/#server=https%3A%2F%2Fwhiteboard-test.puter.work&board=${initial.id}&invite=${token}`;
    app.doc
      .querySelector("#join-link")
      .closest("form")
      .dispatchEvent(
        new app.w.Event("submit", { bubbles: true, cancelable: true }),
      );
    for (let n = 0; n < 200 && app.doc.querySelector("#join-link"); n++)
      await app.tick();
    await app.tick();
    assert.ok(
      app.doc.querySelector(".editor").classList.contains("shared-viewer"),
    );
    const context = app.doc.querySelector("#canvas").getContext("2d");
    const prototype = Object.getPrototypeOf(context);
    const { fillRect, arc } = prototype;
    const painted = [];
    prototype.fillRect = function (...args) {
      painted.push(["square", this.fillStyle]);
      return fillRect.apply(this, args);
    };
    prototype.arc = function (...args) {
      painted.push(["circle", this.fillStyle]);
      return arc.apply(this, args);
    };
    try {
      for (const target of [note, line]) {
        painted.length = 0;
        await app.click(`#board-outline [data-id="${target.id}"]`);
        assert.equal(
          app.doc
            .querySelector(`#board-outline [data-id="${target.id}"]`)
            .getAttribute("aria-pressed"),
          "true",
        );
        // Handles are white squares and circles drawn over the selection.
        assert.deepEqual(
          painted.filter(([, fill]) => /^#fff/i.test(fill)),
          [],
          target.type,
        );
      }
    } finally {
      Object.assign(prototype, { fillRect, arc });
    }
  } finally {
    await app.close();
  }
});

test("Quick connect joins a shown mind-map child and passes over a folded one", async () => {
  for (const collapsed of [false, true]) {
    const app = await setup();
    const { doc, w, click, tick } = app;
    try {
      await click('[data-action="new"]');
      const canvas = doc.querySelector("#canvas");
      canvas.getBoundingClientRect = () => ({
        left: 0,
        top: 0,
        width: 1400,
        height: 800,
      });
      const map = { direction: "right", auto: false, line: "curved" };
      const source = item("rect", 0, 0, { w: 200, h: 160, text: "Source" });
      const root = item("note", -700, 0, {
        w: 200,
        h: 160,
        text: "Root",
        mindMap: { ...map, parent: null },
        mindCollapsed: collapsed,
      });
      const child = item("note", 280, 0, {
        w: 200,
        h: 160,
        text: "Child",
        mindMap: { ...map, parent: root.id },
        mindCollapsed: false,
      });
      dispatchTransfer(
        app,
        "drop",
        transferData(clipboardFormats([source, root, child])),
        canvas,
        { clientX: 400, clientY: 300 },
      );
      await tick();
      const sourceId = allClipboard(app).find((i) => i.text === "Source").id;
      await click(`#board-outline [data-id="${sourceId}"]`);
      const port = doc.querySelector('[data-quick-direction="right"]');
      port.dispatchEvent(new w.MouseEvent("pointerenter"));
      assert.equal(
        port.querySelector('[role="tooltip"]').textContent,
        collapsed ? "Add connected object" : "Connect to Sticky note: Child",
      );
      port.dispatchEvent(new w.MouseEvent("pointerleave"));
      port.click();
      await tick();
      const after = allClipboard(app);
      const line = after.find((i) => i.type === "arrow");
      const childId = after.find((i) => i.text === "Child").id;
      assert.ok(line, "A connection was made");
      if (collapsed) assert.notEqual(line.endId, childId);
      else assert.equal(line.endId, childId);
      assert.equal(after.length, collapsed ? 5 : 4);
    } finally {
      await app.close();
    }
  }
});

