test("Tab order reaches the top navigation row before the tool rail, as they are laid out", async () => {
  const app = await setup();
  const { doc, w, click } = app;
  try {
    await click('[data-action="new"]');
    const order = [
      "#board-title",
      "#canvas",
      '.canvas-navigation [data-action="comments"]',
      '.left-rail [data-action="tool-select"]',
      '.canvas-bottom [data-action="fit"]',
    ].map((selector) => doc.querySelector(selector));
    for (let n = 1; n < order.length; n++)
      assert.ok(
        order[n - 1].compareDocumentPosition(order[n]) &
          w.Node.DOCUMENT_POSITION_FOLLOWING,
        `${order[n - 1].dataset.action || order[n - 1].id} comes before ${order[n].dataset.action || order[n].id}`,
      );
  } finally {
    await app.close();
  }
});

test("redrawing the board leaves the top navigation row's hidden buttons untouched", async () => {
  const app = await setup();
  const { doc, w, click } = app;
  try {
    await click('[data-action="new"]');
    await app.tick();
    // The row is measured again on every change to a button's hidden state,
    // so a redraw that changes nothing must not touch one.
    const changed = [];
    const watch = new w.MutationObserver((records) =>
      changed.push(...records.map((r) => r.target.id || r.target.className)),
    );
    watch.observe(doc.querySelector(".canvas-navigation"), {
      subtree: true,
      attributeFilter: ["hidden"],
    });
    await click('[data-action="zoom-in"]');
    await click('[data-action="zoom-out"]');
    await app.tick();
    watch.disconnect();
    assert.deepEqual(changed, []);
  } finally {
    await app.close();
  }
});

test("the top navigation row stacks under the header when the board tag and its buttons do not fit beside it", async () => {
  const app = await setup();
  const { doc, w, click } = app;
  // JSDOM lays nothing out; give the chrome the sizes a browser measures.
  const measures = [];
  w.ResizeObserver = class {
    constructor(callback) {
      measures.push(callback);
    }
    observe() {}
    disconnect() {}
  };
  const size = (el, props) => {
    for (const [key, value] of Object.entries(props))
      Object.defineProperty(el, key, { configurable: true, value });
  };
  try {
    await click('[data-action="new"]');
    const editor = doc.querySelector(".editor");
    size(doc.querySelector(".editor-heading"), { offsetWidth: 339 });
    size(doc.querySelector(".editor-actions"), { offsetWidth: 411 });
    for (const b of doc.querySelectorAll(".canvas-navigation > *"))
      size(b, { offsetWidth: 38 });
    const tag = doc.querySelector(".board-tag");
    const label = tag.querySelector("span");
    assert.ok(label, "The tag's words sit in their own element");
    assert.equal(tag.title, tag.textContent, "The tag names itself in full");
    // The label is cut to 100 of its 160 pixels.
    size(tag, { offsetWidth: 140 });
    size(label, { scrollWidth: 160, clientWidth: 100 });
    const stacked = (width) => {
      size(editor, { clientWidth: width });
      measures.at(-1)();
      return editor.classList.contains("chrome-stacked");
    };
    // The buttons alone fit at 1280px, but not with the tag beside them.
    assert.equal(stacked(1280), true);
    assert.equal(stacked(1440), false);
    const participants = doc.querySelector(".canvas-top > .participants");
    participants.hidden = false;
    size(participants, { offsetWidth: 140 });
    assert.equal(stacked(1440), true, "The participants button counts too");
  } finally {
    await app.close();
  }
});

test("Escape on the board closes the object link picker before it clears the selection", async () => {
  const app = await setup();
  const { doc, w, click } = app;
  try {
    await click('[data-action="new"]');
    await click('[data-action="add-note"]');
    await click('[data-action="finish-text"]');
    await click("#board-outline button");
    await click('[data-action="object-link"]');
    assert.ok(doc.querySelector("#object-links-panel"));
    const canvas = doc.querySelector("#canvas");
    canvas.focus();
    canvas.dispatchEvent(
      new w.KeyboardEvent("keydown", { key: "Escape", bubbles: true }),
    );
    await app.tick();
    assert.equal(doc.querySelector("#object-links-panel"), null);
    assert.equal(
      doc.querySelector("#selection-tools").hidden,
      false,
      "The selection stays for a second Escape to clear",
    );
    canvas.dispatchEvent(
      new w.KeyboardEvent("keydown", { key: "Escape", bubbles: true }),
    );
    await app.tick();
    assert.equal(doc.querySelector("#selection-tools").hidden, true);
  } finally {
    await app.close();
  }
});

for (const locale of ["en", "fr"])
  test(`selected summary keeps its displayed scope after a collaborator deletes the selection in ${locale}`, async () => {
    const chosen = item("note", 0, 0, { text: "Chosen short source." }),
      other = item("note", 300, 0, {
        text: "Other visible notes that were not chosen.",
      }),
      room = "selected-summary-scope-" + locale;
    const shared = await sharedEditors(room, [chosen, other]);
    try {
      const [a, b] = shared.apps,
        requests = [];
      b.w.puter.ai = {
        chat: async (...args) => {
          requests.push(args);
          return "Controlled summary.";
        },
      };
      b.doc.querySelector("#language").value = locale;
      b.doc.querySelector("#language").dispatchEvent(new b.w.Event("change"));
      await b.tick();
      await b.click(`#board-outline [data-id="${chosen.id}"]`);
      await b.click('[data-action="ai"]');
      const dialog = b.doc.querySelector("dialog[open]"),
        button = dialog.querySelector('[data-ai="summarize"]'),
        label =
          locale === "fr" ? "Les objets sélectionnés" : "The selected objects";
      assert.equal(button.querySelector("small").textContent, label);
      await a.click(`#board-outline [data-id="${chosen.id}"]`);
      await a.click('[data-action="delete"]');
      await shared.until(
        () => !b.doc.querySelector(`#board-outline [data-id="${chosen.id}"]`),
        "Remote deletion reached the actual editor while the AI dialog stayed open.",
      );
      assert.equal(dialog.open, true);
      assert.equal(button.querySelector("small").textContent, label);
      const source = (await storedSharedBoard(b, room)).items;
      assert.equal(source.length, 1);
      assert.equal(source[0].text, other.text);
      await b.click('[data-ai="summarize"]');
      assert.equal(
        requests.length,
        0,
        "A selected-object action must not send the other board content when its selected source disappears.",
      );
      assert.equal(dialog.querySelector("#ai-summary"), null);
      assert.deepEqual((await storedSharedBoard(b, room)).items, source);
    } finally {
      await shared.close();
    }
  });

for (const [locale, draft] of [
  ["en", "Description typed while waiting."],
  ["fr", ""],
])
  test(`pending image description keeps the author's ${locale} draft through Save, Undo and reopening`, async () => {
    const src = createCanvas(4, 4).toDataURL();
    class BlobImage extends NativeImage {
      set src(value) {
        super.src = value === "blob:test" ? src : value;
      }
      get src() {
        return super.src;
      }
    }
    let release, request;
    const app = await setup(
      {
        env: "web",
        auth: {
          isSignedIn: () => true,
          getUser: async () => ({ username: "local-description-fixture" }),
        },
        ai: {
          chat: (...args) => {
            request = args;
            return new Promise((resolve) => (release = resolve));
          },
        },
      },
      { imageClass: BlobImage, preferences: { "whiteboard-language": locale } },
    );
    const { doc, w, click } = app;
    try {
      w.fetch = async (url) => {
        assert.match(url, /^data:image\/(png|jpeg);base64,/);
        return new Response(Buffer.from(url.split(",")[1], "base64"), {
          headers: { "Content-Type": url.match(/^data:([^;]+);/)[1] },
        });
      };
      await rotationFixture(app, [
        item("image", 0, 0, {
          src,
          w: 4,
          h: 4,
          alt: "Saved description.",
          lang: "fr-CA",
        }),
      ]);
      const original = selectedClipboard(app)[0];
      await click('[data-action="commands"]');
      paletteQuery(app, "Alternative text");
      await click('[data-command="alt-text"]');
      const field = doc.querySelector("#alt-text"),
        suggest = doc.querySelector("#alt-suggest");
      await click("#alt-suggest");
      const requestedDeadline = Date.now() + 3000;
      while (!release && Date.now() < requestedDeadline) await app.tick();
      assert.ok(
        release,
        "The actual image-description request reached the local AI handler.",
      );
      assert.match(request[0], /in fr-CA\./);
      assert.equal(suggest.disabled, true);
      field.value = draft;
      field.dispatchEvent(new w.Event("input", { bubbles: true }));
      release(' "Suggested description." ');
      const reviewedDeadline = Date.now() + 3000;
      while (suggest.disabled && Date.now() < reviewedDeadline)
        await app.tick();
      assert.equal(suggest.disabled, false);
      assert.equal(
        field.value,
        draft,
        "The later reply must keep the user's changed draft.",
      );
      assert.equal(field.lang, "fr-CA");
      assert.equal(
        doc.querySelector("#alt-count").textContent,
        `${draft.length} / 1000`,
      );
      assert.match(
        doc.querySelector("#alt-status").textContent,
        locale === "fr" ? /conservée/ : /kept/,
      );
      assert.ok(
        doc
          .querySelector(`#board-outline [data-id="${original.id}"]`)
          .textContent.includes("Saved description."),
      );
      doc
        .querySelector("#alt-form")
        .dispatchEvent(new w.Event("submit", { cancelable: true }));
      await app.tick();
      assert.equal(doc.querySelector("#alt-form"), null);
      const expected = { ...original };
      if (draft) expected.alt = draft;
      else delete expected.alt;
      assert.deepEqual(allClipboard(app), [expected]);
      await click('[data-action="undo"]');
      assert.deepEqual(allClipboard(app), [original]);
      await click('[data-action="redo"]');
      assert.deepEqual(allClipboard(app), [expected]);
      await click('[data-action="home"]');
      await click("[data-open]");
      assert.deepEqual(allClipboard(app), [expected]);
      assert.equal(doc.documentElement.lang, locale);
    } finally {
      release?.(' "Suggested description." ');
      await app.close();
    }
  });

