for (const locale of ["en", "fr"])
  for (const change of ["replacement", "movement"])
    test(`alternative description handles remote image ${change} without losing drafts in ${locale}`, async () => {
      const original = {
        ...cropFixture(),
        x: 0,
        y: 0,
        alt: "Old description",
        lang: "fr-CA",
      };
      const replacement = { ...replacementFixture(), x: 500, y: 0 };
      const bytes = [original.src, replacement.src];
      const objects = await Promise.all(
        [original, replacement].map(async (i) => ({
          ...i,
          src: `asset:${await hash(i.src)}`,
        })),
      );
      const room = `alt-source-${locale}-${change}`;
      const shared = await sharedEditors(room, objects, 2, bytes);
      try {
        const [a, b] = shared.apps;
        b.doc.querySelector("#language").value = locale;
        b.doc.querySelector("#language").dispatchEvent(new b.w.Event("change"));
        await b.tick();
        await b.click(`#board-outline [data-id="${original.id}"]`);
        await b.click('[data-action="commands"]');
        paletteQuery(b, "Alternative text");
        await b.click('[data-command="alt-text"]');
        const dialog = b.doc.querySelector("dialog[open]"),
          field = dialog.querySelector("#alt-text");
        const draft = "Description of the original image.";
        field.value = draft;
        field.dispatchEvent(new b.w.Event("input", { bubbles: true }));
        await a.click(`#board-outline [data-id="${original.id}"]`);
        if (change === "replacement") {
          await chooseBoardReplacement(a, replacement.id);
          await a.click("#replacement-apply");
        } else {
          a.doc.querySelector("#canvas").dispatchEvent(
            new a.w.KeyboardEvent("keydown", {
              key: "ArrowRight",
              bubbles: true,
              cancelable: true,
            }),
          );
        }
        await shared.until(async () => {
          const photo = (await storedSharedBoard(b, room))?.items.find(
            (i) => i.id === original.id,
          );
          return change === "replacement"
            ? photo?.src === replacement.src
            : photo?.x === 1;
        }, "The remote change reached the actual editor while its description dialog stayed open");
        const before = await storedSharedBoard(b, room);
        assert.equal(dialog.open, true);
        dialog.querySelector("#alt-form").requestSubmit();
        await b.tick();
        if (change === "replacement") {
          assert.equal(
            dialog.open,
            true,
            "The stale draft stays available to copy.",
          );
          assert.equal(field.value, draft);
          assert.equal(field.lang, "fr-CA");
          assert.match(
            dialog.querySelector("#alt-status").textContent,
            locale === "fr" ? /changé/ : /changed/,
          );
          assert.deepEqual(
            (await storedSharedBoard(b, room)).items,
            before.items,
          );
          dialog.close();
          await b.click('[data-action="commands"]');
          paletteQuery(b, "Alternative text");
          await b.click('[data-command="alt-text"]');
          b.doc.querySelector("#alt-text").value =
            "Description of the replacement.";
          b.doc.querySelector("#alt-form").requestSubmit();
          await shared.until(
            async () =>
              (await storedSharedBoard(a, room))?.items.find(
                (i) => i.id === original.id,
              )?.alt === "Description of the replacement.",
            "Reopening permits an explicit description of the current image",
          );
        } else {
          await shared.until(
            async () =>
              (await storedSharedBoard(a, room))?.items.find(
                (i) => i.id === original.id,
              )?.alt === draft,
            "The description is merged over the collaborator's movement",
          );
          assert.equal(dialog.isConnected, false);
          assert.equal(
            (await storedSharedBoard(a, room)).items.find(
              (i) => i.id === original.id,
            ).x,
            1,
          );
          await b.click('[data-action="undo"]');
          await shared.until(
            async () =>
              (await storedSharedBoard(a, room))?.items.find(
                (i) => i.id === original.id,
              )?.alt === "Old description",
            "Undo restores only the local description",
          );
          assert.equal(
            (await storedSharedBoard(a, room)).items.find(
              (i) => i.id === original.id,
            ).x,
            1,
          );
        }
      } finally {
        await shared.close();
      }
    });

for (const locale of ["en", "fr"])
  for (const shape of ["uncropped", "rectangle", "ellipse"])
    test(`AI image description sends only the visible ${shape} content in ${locale}`, async () => {
      const image = cropFixture();
      image.alt = "Saved description.";
      image.lang = "fr-CA";
      if (shape !== "uncropped") {
        image.w = 200;
        image.h = 120;
        image.crop = { x: 0, y: 0, w: 0.5, h: 0.5, sourceAspect: 400 / 240 };
        if (shape === "ellipse") image.crop.mask = "ellipse";
      }
      validateBoard({ ...board("Visible description"), items: [image] });
      class BlobImage extends NativeImage {
        set src(value) {
          super.src = value === "blob:test" ? image.src : value;
        }
        get src() {
          return super.src;
        }
      }
      let request;
      const app = await setup(
        {
          env: "web",
          auth: {
            isSignedIn: () => true,
            getUser: async () => ({ username: "visible-description-fixture" }),
          },
          ai: {
            chat: (...args) => {
              request = args;
              return Promise.resolve("Description of the visible content.");
            },
          },
        },
        {
          imageClass: BlobImage,
          preferences: { "whiteboard-language": locale },
        },
      );
      try {
        app.w.fetch = async (url) => {
          assert.match(url, /^data:image\/(png|jpeg);base64,/);
          // Keep Blob and File in the app's realm, as the browser does.
          // JSDOM otherwise stringifies a host Blob inside its File.
          return {
            blob: async () =>
              new app.w.Blob([Buffer.from(url.split(",")[1], "base64")], {
                type: url.match(/^data:([^;]+);/)[1],
              }),
          };
        };
        await rotationFixture(app, [image]);
        const original = allClipboard(app);
        await app.click('[data-action="commands"]');
        paletteQuery(app, "Alternative text");
        await app.click('[data-command="alt-text"]');
        await app.click("#alt-suggest");
        const deadline = Date.now() + 3000;
        while (
          (!request || app.doc.querySelector("#alt-suggest").disabled) &&
          Date.now() < deadline
        )
          await app.tick();
        assert.ok(request, "The actual app sends an image file to AI.");
        assert.match(request[0], /in fr-CA\./);
        const bytes = await new Promise((resolve, reject) => {
          const reader = new app.w.FileReader();
          reader.onload = () => resolve(reader.result);
          reader.onerror = reject;
          reader.readAsDataURL(request[1]);
        });
        const decoded = await new Promise((resolve, reject) => {
          const img = new NativeImage();
          img.onload = () => resolve(img);
          img.onerror = reject;
          img.src = bytes;
        });
        assert.deepEqual(
          [decoded.width, decoded.height],
          shape === "uncropped" ? [400, 240] : [200, 120],
          "The AI image must use the visible source rectangle.",
        );
        const raster = createCanvas(decoded.width, decoded.height),
          ctx = raster.getContext("2d");
        ctx.drawImage(decoded, 0, 0);
        const pixel = (x, y) => [...ctx.getImageData(x, y, 1, 1).data];
        assert.deepEqual(pixel(50, 30), [255, 0, 0, 255]);
        if (shape === "uncropped") {
          assert.deepEqual(pixel(300, 60), [0, 255, 0, 255]);
          assert.deepEqual(pixel(100, 180), [0, 0, 255, 255]);
          assert.deepEqual(pixel(300, 180), [255, 255, 0, 255]);
        } else {
          assert.deepEqual(pixel(100, 60), [255, 0, 0, 255]);
          assert.deepEqual(
            pixel(2, 2),
            shape === "ellipse" ? [255, 255, 255, 255] : [255, 0, 0, 255],
            "Masked-out content must stay out of the image sent to AI.",
          );
        }
        assert.equal(
          app.doc.querySelector("#alt-text").value,
          "Description of the visible content.",
        );
        app.doc.querySelector("#alt-form").closest("dialog").close();
        await app.tick();
        assert.deepEqual(allClipboard(app), original);
      } finally {
        await app.close();
      }
    });

