test("opening boards does not pile up document listeners for the Preferences popover", async () => {
  const a = await setup();
  try {
    // Listeners a board adds and removes again are fine; what counts is
    // what stays behind once the board is left.
    const live = new Set();
    const original = a.doc.addEventListener.bind(a.doc),
      remove = a.doc.removeEventListener.bind(a.doc);
    a.doc.addEventListener = (type, fn, ...rest) => {
      if (type === "pointerdown") live.add(fn);
      return original(type, fn, ...rest);
    };
    a.doc.removeEventListener = (type, fn, ...rest) => {
      if (type === "pointerdown") live.delete(fn);
      return remove(type, fn, ...rest);
    };
    for (let n = 0; n < 3; n++) {
      await a.click('[data-action="new"]');
      assert.ok(a.doc.querySelector("details.preferences"));
      await a.click('[data-action="home"]');
    }
    assert.equal(live.size, 0, "each board opened left a document listener");
  } finally {
    await a.close();
  }
});

