test("a creation tool chosen from the keyboard adds its object, as its letter does", async () => {
  const a = await setup();
  try {
    await a.click('[data-action="new"]');
    const { doc, w } = a;
    const count = () => doc.querySelectorAll("#board-outline [data-id]").length;
    const press = (selector, key, up = key === " ") => {
      const button = doc.querySelector(selector);
      button.focus();
      button.dispatchEvent(
        new w.KeyboardEvent("keydown", {
          key,
          bubbles: true,
          cancelable: true,
        }),
      );
      if (!up) button.click();
      button.dispatchEvent(
        new w.KeyboardEvent("keyup", { key, bubbles: true, cancelable: true }),
      );
      if (up) button.click();
    };
    // A mouse click arms the tool for a click on the board.
    await a.click('[data-action="tool-note"]');
    assert.equal(count(), 0);
    assert.equal(
      doc
        .querySelector('[data-action="tool-note"]')
        .getAttribute("aria-pressed"),
      "true",
    );
    // Enter on Sticky note adds one and opens it for typing.
    press('[data-action="tool-note"]', "Enter");
    await a.tick();
    assert.equal(count(), 1);
    assert.equal(doc.activeElement, doc.querySelector("#canvas-text-editor"));
    doc.querySelector("#canvas").focus();
    await a.tick();
    // Space on Rectangle adds one, selected, with the board focused so the
    // arrow keys move it.
    press('[data-action="tool-rect"]', " ");
    await a.tick();
    assert.equal(count(), 2);
    assert.equal(doc.activeElement, doc.querySelector("#canvas"));
    assert.equal(
      doc
        .querySelector('[data-action="tool-select"]')
        .getAttribute("aria-pressed"),
      "true",
    );
    // Tools that draw between points are only chosen.
    press('[data-action="tool-arrow"]', "Enter");
    await a.tick();
    assert.equal(count(), 2);
    assert.equal(
      doc
        .querySelector('[data-action="tool-arrow"]')
        .getAttribute("aria-pressed"),
      "true",
    );
    // A key pressed elsewhere does not make a later click the keyboard's.
    press('[data-action="tool-select"]', "Enter");
    await a.tick();
    doc.querySelector('[data-action="tool-ellipse"]').click();
    await a.tick();
    assert.equal(count(), 2);
  } finally {
    await a.close();
  }
});

// A board with one note, a measured canvas, and pointer helpers for
// gesture tests. The view starts at (110, 85) at 100%.
async function gestureBoard(a) {
  const { doc, w } = a;
  await a.click('[data-action="new"]');
  const canvas = doc.querySelector("#canvas");
  canvas.getBoundingClientRect = () => ({
    left: 0,
    top: 0,
    width: 1000,
    height: 800,
    right: 1000,
    bottom: 800,
  });
  const captures = new Set();
  canvas.setPointerCapture = (id) => captures.add(id);
  canvas.hasPointerCapture = (id) => captures.has(id);
  canvas.releasePointerCapture = (id) => captures.delete(id);
  const pointer = (type, x, y, extra = {}) => {
    const e = new w.MouseEvent(type, {
      bubbles: true,
      cancelable: true,
      clientX: x,
      clientY: y,
      button: 0,
      ...extra,
    });
    Object.defineProperty(e, "pointerId", { value: extra.pointerId ?? 1 });
    Object.defineProperty(e, "pointerType", {
      value: extra.pointerType ?? "mouse",
    });
    canvas.dispatchEvent(e);
    return e;
  };
  const key = (name, options = {}) =>
    canvas.dispatchEvent(
      new w.KeyboardEvent("keydown", {
        key: name,
        bubbles: true,
        cancelable: true,
        ...options,
      }),
    );
  const selected = () =>
    [...doc.querySelectorAll('#board-outline [aria-pressed="true"]')].map(
      (el) => el.dataset.id,
    );
  const items = () => {
    const data = transferData();
    dispatchTransfer(a, "copy", data);
    const text = data.getData(CLIPBOARD_TYPE);
    return text ? JSON.parse(text).items : [];
  };
  await a.click('[data-action="toggle-snapping"]');
  key("n");
  key("Escape");
  key("a", { ctrlKey: true });
  const [note] = items();
  assert.ok(note, "the board holds a note");
  key("Escape");
  const view = { x: 110, y: 85 };
  return { canvas, pointer, key, selected, items, note, view };
}

test("a window resize during a pan keeps what was panned so far", async () => {
  const a = await setup();
  try {
    const { pointer, key, selected, note, view } = await gestureBoard(a);
    const at = (dx, dy) => ({
      x: view.x + note.x + note.w / 2 + dx,
      y: view.y + note.y + note.h / 2 + dy,
    });
    pointer("pointerdown", 500, 500, { button: 2 });
    pointer("pointermove", 600, 600, { button: 2 });
    a.w.dispatchEvent(new a.w.Event("resize"));
    pointer("pointerup", 600, 600, { button: 2 });
    await a.tick();
    // The note now sits 100 px further right and down on the screen.
    let p = at(100, 100);
    pointer("pointerdown", p.x, p.y);
    pointer("pointerup", p.x, p.y);
    assert.deepEqual(selected(), [note.id], "the view kept the pan");
    key("Escape");
    // Just outside the note where it now sits.
    p = at(100 - note.w / 2 - 10, 100 - note.h / 2 - 10);
    pointer("pointerdown", p.x, p.y);
    pointer("pointerup", p.x, p.y);
    assert.deepEqual(selected(), []);
  } finally {
    await a.close();
  }
});

test("a finger moves an unlocked selected object even when a locked one is selected too", async () => {
  const a = await setup();
  try {
    const { pointer, key, selected, items, note, view } = await gestureBoard(a);
    const at = (i) => ({
      x: view.x + i.x + i.w / 2,
      y: view.y + i.y + i.h / 2,
    });
    // A second note, beside the first, moved 300 to the right and locked.
    key("n");
    key("Escape");
    key("a", { ctrlKey: true });
    let other = items().find((i) => i.id !== note.id);
    key("Escape");
    let q = at(other);
    pointer("pointerdown", q.x, q.y);
    pointer("pointerup", q.x, q.y);
    assert.deepEqual(selected(), [other.id]);
    const start = other.x;
    key("ArrowRight", { shiftKey: true });
    for (let n = 0; n < 29; n++)
      key("ArrowRight", { shiftKey: true, repeat: true });
    await a.tick(400);
    key("l", { ctrlKey: true, shiftKey: true });
    await a.tick();
    other = items().find((i) => i.id !== note.id);
    assert.equal(other.locked, true);
    assert.equal(other.x, start + 300);
    key("Escape");
    const p = at(note);
    pointer("pointerdown", p.x, p.y);
    pointer("pointerup", p.x, p.y);
    q = at(other);
    pointer("pointerdown", q.x, q.y, { shiftKey: true });
    pointer("pointerup", q.x, q.y, { shiftKey: true });
    assert.deepEqual(new Set(selected()), new Set([note.id, other.id]));
    const touch = { pointerType: "touch", pointerId: 7 };
    pointer("pointerdown", p.x, p.y, touch);
    pointer("pointermove", p.x + 50, p.y, touch);
    pointer("pointermove", p.x + 100, p.y, touch);
    pointer("pointerup", p.x + 100, p.y, touch);
    await a.tick();
    key("Escape");
    key("a", { ctrlKey: true });
    const moved = items().find((i) => i.id === note.id);
    assert.equal(
      moved.x,
      note.x + 100,
      "the finger moved the note, not the view",
    );
  } finally {
    await a.close();
  }
});

