test("a right-click selects what is under it and opens a menu of its commands; a right-drag still pans", async () => {
  const app = await setup();
  const { doc, w, tick } = app;
  try {
    const { canvas, selected } = await rotationFixture(app, [
      item("note", 0, 0, { w: 200, h: 160, text: "First" }),
      item("note", 400, 0, { w: 200, h: 160, text: "Second" }),
    ]);
    const target = selected.find((i) => i.text === "Second");
    const at = (p) => {
      const v = renderedView(app);
      return [v.x + p.x * v.z, v.y + p.y * v.z];
    };
    const right = (type, [x, y]) =>
      canvasPointer(app, type, 9, x, y, { pointerType: "mouse", button: 2 });
    const menu = () => doc.querySelector("#context-menu");
    const commands = () =>
      [...menu().querySelectorAll('[role="menuitem"]')].map(
        (b) => b.dataset.command,
      );
    // A drag with the right button moves the view and opens nothing.
    const start = renderedView(app);
    right("pointerdown", [900, 700]);
    right("pointermove", [960, 730]);
    right("pointerup", [960, 730]);
    assert.equal(renderedView(app).x, start.x + 60);
    assert.equal(menu(), null);
    // Right-clicking one of several selected objects keeps them all.
    const second = at({ x: target.x + 100, y: target.y + 80 });
    right("pointerdown", second);
    right("pointerup", second);
    await tick();
    assert.equal(menu().getAttribute("role"), "menu");
    assert.equal(selectedClipboard(app).length, 2);
    // On the empty board the selection goes and the board's menu opens.
    right("pointerdown", [1100, 800]);
    right("pointerup", [1100, 800]);
    await tick();
    assert.equal(doc.querySelector("#selection-tools").hidden, true);
    assert.ok(commands().includes("select-all"));
    assert.ok(!commands().includes("delete"));
    // Escape closes it and hands the keyboard back to the board.
    menu().dispatchEvent(
      new w.KeyboardEvent("keydown", { key: "Escape", bubbles: true }),
    );
    assert.equal(menu(), null);
    assert.equal(doc.activeElement, canvas);
    // A still right-click on an unselected note selects it alone.
    right("pointerdown", second);
    right("pointerup", second);
    await tick();
    assert.deepEqual(
      selectedClipboard(app).map((i) => i.text),
      ["Second"],
    );
    for (const id of ["clipboard:copy", "duplicate", "delete", "front", "lock"])
      assert.ok(commands().includes(id), id);
    assert.ok(!commands().includes("select-all"));
    // Choosing a command runs it and closes the menu.
    menu().querySelector('[data-command="duplicate"]').click();
    await tick();
    assert.equal(menu(), null);
    assert.equal(doc.activeElement, canvas);
    assert.equal(doc.querySelectorAll("#board-outline [data-id]").length, 3);
  } finally {
    await app.close();
  }
});

