test("the context menu opens from the keyboard and pastes where it was opened", async () => {
  const app = await setup();
  const { doc, w, tick } = app;
  try {
    const { canvas, key } = await rotationFixture(app, [
      item("note", 0, 0, { w: 200, h: 160, text: "Copied" }),
    ]);
    const fragment = clipboardFormats([
      item("note", 0, 0, { w: 200, h: 100, text: "Pasted" }),
    ]);
    const blob = (type, value) => ({ text: async () => value, type });
    w.navigator.clipboard = {
      read: async () => [
        {
          types: ["text/html", "text/plain"],
          getType: async (type) => blob(type, fragment[type]),
        },
      ],
    };
    // Shift+F10 opens the selection's menu with its first command focused,
    // and the arrow keys move through the commands.
    key("F10", { shiftKey: true, cancelable: true });
    await tick();
    const menu = doc.querySelector("#context-menu");
    assert.equal(doc.activeElement, menu.querySelector('[role="menuitem"]'));
    doc.activeElement.dispatchEvent(
      new w.KeyboardEvent("keydown", { key: "ArrowDown", bubbles: true }),
    );
    assert.equal(
      doc.activeElement,
      menu.querySelectorAll('[role="menuitem"]')[1],
    );
    // A letter typed in the menu runs no board shortcut.
    doc.activeElement.dispatchEvent(
      new w.KeyboardEvent("keydown", { key: "n", bubbles: true }),
    );
    assert.equal(doc.querySelectorAll("#board-outline [data-id]").length, 1);
    menu.dispatchEvent(
      new w.KeyboardEvent("keydown", { key: "Escape", bubbles: true }),
    );
    // Paste from the board's menu centres the content on the press.
    const v = renderedView(app);
    const point = { x: 900, y: 700 };
    canvasPointer(app, "pointerdown", 4, point.x, point.y, {
      pointerType: "mouse",
      button: 2,
    });
    canvasPointer(app, "pointerup", 4, point.x, point.y, {
      pointerType: "mouse",
      button: 2,
    });
    await tick();
    doc.querySelector('[data-command="clipboard:paste"]').click();
    for (let n = 0; n < 5; n++) await tick();
    assert.equal(doc.querySelectorAll("#board-outline [data-id]").length, 2);
    const placed = selectedClipboard(app)[0];
    assert.equal(placed.text, "Pasted");
    assert.equal(placed.x + placed.w / 2, (point.x - v.x) / v.z);
    assert.equal(placed.y + placed.h / 2, (point.y - v.y) / v.z);
    assert.equal(canvas, doc.querySelector("#canvas"));
  } finally {
    await app.close();
  }
});

test("menu Paste after this tab's menu Copy works when reading the clipboard is refused", async () => {
  const app = await setup();
  const { doc, w, tick } = app;
  try {
    const { selected } = await rotationFixture(app, [
      item("note", 0, 0, { w: 200, h: 160, text: "Copied" }),
    ]);
    const [note] = selected;
    const v = renderedView(app);
    let external = null;
    w.ClipboardItem = class {
      constructor(data) {
        this.data = data;
      }
    };
    Object.defineProperty(w.navigator, "clipboard", {
      configurable: true,
      value: {
        write: async () => {},
        // The browser refuses to read the clipboard unless the page was
        // allowed to; here it is allowed only while external text is set.
        read: async () => {
          if (external === null)
            throw new w.DOMException(
              "Read permission denied.",
              "NotAllowedError",
            );
          return [
            {
              types: ["text/plain"],
              getType: async () => ({ text: async () => external }),
            },
          ];
        },
      },
    });
    const menu = async (command, x, y) => {
      for (const type of ["pointerdown", "pointerup"])
        canvasPointer(
          app,
          type,
          4,
          v.x + (note.x + x) * v.z,
          v.y + (note.y + y) * v.z,
          {
            pointerType: "mouse",
            button: 2,
          },
        );
      await tick();
      doc.querySelector(`[data-command="${command}"]`).click();
      for (let n = 0; n < 5; n++) await tick();
    };
    const texts = () =>
      allClipboard(app)
        .map((i) => i.text)
        .sort();
    const toast = doc.querySelector("#toast");
    await menu("clipboard:copy", 100, 80);
    await menu("clipboard:paste", 600, 400);
    assert.deepEqual(texts(), ["Copied", "Copied"]);
    assert.doesNotMatch(toast.textContent, /did not allow/);
    // Content the browser lets the page read still wins.
    external = "Elsewhere";
    await menu("clipboard:paste", 600, 700);
    assert.deepEqual(texts(), ["Copied", "Copied", "Elsewhere"]);
    external = null;
    // A copy of something else in the page, or leaving the window, where
    // anything may be copied, forgets the board's copy.
    dispatchTransfer(
      app,
      "copy",
      transferData(),
      doc.querySelector("#board-title"),
    );
    await menu("clipboard:paste", 900, 400);
    assert.equal(allClipboard(app).length, 3);
    assert.match(toast.textContent, /did not allow access to the clipboard/);
    await menu("clipboard:copy", 100, 80);
    w.dispatchEvent(new w.Event("blur"));
    await menu("clipboard:paste", 900, 700);
    assert.equal(allClipboard(app).length, 3);
  } finally {
    await app.close();
  }
});

test("a resting pointer outlines the object a click would select", async () => {
  const app = await setup();
  const { doc, w, tick } = app;
  try {
    const { canvas, selected } = await rotationFixture(app, [
      item("note", 0, 0, { w: 200, h: 160, text: "Note", groupId: "g" }),
      item("note", 240, 0, { w: 200, h: 160, text: "Member", groupId: "g" }),
      item("rect", 0, 400, { w: 100, h: 50 }),
    ]);
    const outline = doc.querySelector("#hover-outline");
    const v = renderedView(app);
    const hover = (p) =>
      canvasPointer(app, "pointermove", 3, v.x + p.x * v.z, v.y + p.y * v.z, {
        pointerType: "mouse",
        buttons: 0,
      });
    const note = selected.find((i) => i.text === "Note"),
      rect = selected.find((i) => i.type === "rect");
    // Everything dropped is selected, so nothing is outlined yet.
    hover({ x: rect.x + 50, y: rect.y + 25 });
    assert.equal(outline.hidden, true);
    canvasPointer(app, "pointerdown", 3, 1150, 880, { pointerType: "mouse" });
    canvasPointer(app, "pointerup", 3, 1150, 880, { pointerType: "mouse" });
    await tick();
    hover({ x: rect.x + 50, y: rect.y + 25 });
    assert.equal(outline.hidden, false);
    assert.equal(outline.style.width, `${100 * v.z}px`);
    assert.equal(outline.style.height, `${50 * v.z}px`);
    // A grouped note outlines the whole group, as a click selects it.
    hover({ x: note.x + 100, y: note.y + 80 });
    assert.equal(outline.hidden, false);
    assert.equal(outline.style.width, `${440 * v.z}px`);
    // The empty board, and leaving the canvas, outline nothing.
    hover({ x: rect.x + 400, y: rect.y + 400 });
    assert.equal(outline.hidden, true);
    hover({ x: rect.x + 50, y: rect.y + 25 });
    canvas.dispatchEvent(new w.MouseEvent("pointerleave"));
    assert.equal(outline.hidden, true);
    // Once selected, an object shows its selection instead.
    hover({ x: rect.x + 50, y: rect.y + 25 });
    canvasPointer(
      app,
      "pointerdown",
      3,
      v.x + (rect.x + 50) * v.z,
      v.y + (rect.y + 25) * v.z,
      { pointerType: "mouse" },
    );
    canvasPointer(
      app,
      "pointerup",
      3,
      v.x + (rect.x + 50) * v.z,
      v.y + (rect.y + 25) * v.z,
      { pointerType: "mouse" },
    );
    await tick();
    assert.equal(outline.hidden, true);
  } finally {
    await app.close();
  }
});

test("Page Up and Page Down change layer order and L picks the connection line", async () => {
  const app = await setup();
  const { doc } = app;
  try {
    const { key } = await rotationFixture(app, [
      item("note", 0, 0, { text: "Bottom" }),
      item("note", 40, 40, { text: "Top" }),
    ]);
    // The outline reads the board's layout, not its layers; the change of
    // layer is said instead.
    const said = async () => {
      await new Promise((r) => setTimeout(r, 80));
      return doc.querySelector("#board-announcer").textContent;
    };
    [...doc.querySelectorAll("#board-outline [data-id]")]
      .find((b) => b.textContent.endsWith("Bottom"))
      .click();
    // The selection is said first.
    await new Promise((r) => setTimeout(r, 350));
    key("PageUp", { cancelable: true });
    assert.equal(await said(), "Brought to front");
    key("PageDown", { cancelable: true });
    assert.equal(await said(), "Sent to back");
    key("Escape");
    key("l");
    assert.equal(
      doc
        .querySelector('[data-action="tool-arrow"]')
        .getAttribute("aria-pressed"),
      "true",
    );
  } finally {
    await app.close();
  }
});

test("Tab or Ctrl/Cmd+D while typing on a sticky note goes on to a new one beside it", async () => {
  const app = await setup();
  const { doc, w, click, tick } = app;
  try {
    await click('[data-action="new"]');
    await click('[data-action="add-note"]');
    const editor = () => doc.querySelector("#canvas-text-editor");
    const press = (key, extra = {}) => {
      const event = new w.KeyboardEvent("keydown", {
        key,
        bubbles: true,
        cancelable: true,
        ...extra,
      });
      editor().dispatchEvent(event);
      return event;
    };
    const type = (text) => {
      editor().value = text;
      editor().dispatchEvent(new w.Event("input", { bubbles: true }));
    };
    type("One");
    assert.equal(press("Tab").defaultPrevented, true);
    await tick();
    type("Two");
    // Ctrl/Cmd+D keeps going too, rather than bookmarking the page.
    assert.equal(
      press("d", { ctrlKey: true, code: "KeyD" }).defaultPrevented,
      true,
    );
    await tick();
    type("Three");
    press("Tab", { shiftKey: true });
    await tick();
    press("Escape");
    await tick();
    doc.querySelector("#canvas").dispatchEvent(
      new w.KeyboardEvent("keydown", {
        key: "a",
        ctrlKey: true,
        bubbles: true,
        cancelable: true,
      }),
    );
    const notes = selectedClipboard(app).sort((a, b) => a.x - b.x);
    // Shift+Tab from the third went left, past the first, to a free spot.
    assert.deepEqual(
      notes.map((i) => i.text),
      ["", "One", "Two", "Three"],
    );
    const [left, one, two, three] = notes;
    assert.equal(two.x - one.x, one.w + 24);
    assert.equal(three.x - two.x, one.w + 24);
    assert.equal(one.x - left.x, one.w + 24);
    assert.ok(
      notes.every((i) => i.y === one.y && i.w === one.w && i.h === one.h),
    );
  } finally {
    await app.close();
  }
});

test("holding Shift while moving keeps the move horizontal or vertical", async () => {
  const app = await setup();
  const { doc, w } = app;
  try {
    const { pointer, selected } = await rotationFixture(app, [
      item("note", 0, 0, { w: 200, h: 160, text: "Straight" }),
    ]);
    const [note] = selected;
    const at = (x, y) => ({ x: note.x + x, y: note.y + y });
    pointer("pointerdown", at(100, 80));
    pointer("pointermove", at(200, 110), { shiftKey: true });
    pointer("pointerup", at(200, 110), { shiftKey: true });
    let [moved] = selectedClipboard(app);
    assert.equal(moved.y, note.y);
    assert.ok(Math.abs(moved.x - note.x - 100) <= 8);
    // Pressing Shift partway through straightens the move at once.
    pointer("pointerdown", at(moved.x - note.x + 100, 80));
    pointer("pointermove", at(moved.x - note.x + 130, 280));
    doc.querySelector("#canvas").dispatchEvent(
      new w.KeyboardEvent("keydown", {
        key: "Shift",
        shiftKey: true,
        bubbles: true,
        cancelable: true,
      }),
    );
    const before = moved;
    pointer("pointerup", at(moved.x - note.x + 130, 280), { shiftKey: true });
    [moved] = selectedClipboard(app);
    assert.equal(moved.x, before.x);
    assert.ok(Math.abs(moved.y - before.y - 200) <= 8);
  } finally {
    await app.close();
  }
});

