test("a collaborator's drag repaints the board only where this view can see it", async () => {
  const near = item("rect", 100, 100, { w: 160, h: 100, text: "Near" }),
    far = item("rect", 20000, 20000, { w: 160, h: 100, text: "Far" });
  const shared = await sharedEditors("previews-in-view", [near, far]);
  const [a, b] = shared.apps;
  const pointer = (app, type, p) => {
    const v = renderedView(app);
    canvasPointer(app, type, 1, v.x + p.x * v.z, v.y + p.y * v.z, {
      pointerType: "mouse",
    });
  };
  try {
    await shared.until(() => {
      pointer(b, "pointermove", { x: 50, y: 50 });
      return !!a.doc.querySelector(".participant-cursor");
    }, "Presence linked");
    // A looks at Near only.
    await a.click(`#board-outline [data-id="${near.id}"]`);
    a.doc.querySelector("#canvas").dispatchEvent(
      new a.w.KeyboardEvent("keydown", {
        key: "2",
        code: "Digit2",
        altKey: true,
        bubbles: true,
        cancelable: true,
      }),
    );
    a.doc
      .querySelector("#canvas")
      .dispatchEvent(
        new a.w.KeyboardEvent("keydown", { key: "Escape", bubbles: true }),
      );
    const v = renderedView(a);
    assert.ok(v.x + near.x * v.z < 1000 && v.x + far.x * v.z > 1000);
    const ctx = a.doc.querySelector("#canvas").getContext("2d");
    let repaints = 0;
    const clear = ctx.clearRect;
    ctx.clearRect = function (...args) {
      repaints++;
      return clear.apply(this, args);
    };
    const drag = async (target, from) => {
      await b.click(`#board-outline [data-id="${target.id}"]`);
      repaints = 0;
      pointer(b, "pointerdown", from);
      for (let n = 1; n <= 8; n++) {
        pointer(b, "pointermove", { x: from.x + n * 10, y: from.y + n * 5 });
        await new Promise((r) => setTimeout(r, 120));
      }
      const seen = repaints;
      pointer(b, "pointerup", { x: from.x + 80, y: from.y + 40 });
      await new Promise((r) => setTimeout(r, 300));
      return seen;
    };
    assert.equal(await drag(far, { x: 20080, y: 20050 }), 0);
    assert.ok((await drag(near, { x: 180, y: 150 })) > 0);
  } finally {
    await shared.close();
  }
});

