test("board access in the Participants dialog is searched and shown fifty people at a time", async () => {
  const room = "participants-many";
  const shared = await sharedEditors(room, [item("note", 0, 0, { text: "A" })]);
  const [a] = shared.apps;
  try {
    const exec = a.w.puter.workers.exec;
    const members = [
      { uuid: "owner-id", username: "Owner", role: "owner" },
      ...Array.from({ length: 120 }, (_, n) => ({
        uuid: `member-${n}`,
        username: `Member ${String(n).padStart(3, "0")}`,
        role: n % 10 ? "editor" : "removed",
      })),
    ];
    a.w.puter.workers.exec = (url, options) =>
      JSON.parse(options.body).op === "members"
        ? Promise.resolve(new Response(JSON.stringify({ members })))
        : exec(url, options);
    await a.click('[data-action="participants"]');
    const rows = () =>
      a.doc.querySelectorAll("#participant-list .participant-row");
    await shared.until(() => rows().length === 50, "The first fifty");
    const count = a.doc.querySelector("#access-count");
    // What a search finds is read out once, as a whole.
    assert.equal(count.getAttribute("role"), "status");
    assert.equal(count.getAttribute("aria-live"), "polite");
    assert.equal(count.getAttribute("aria-atomic"), "true");
    // Removed people stay out unless asked for.
    assert.match(count.textContent, /109 people/);
    await a.click("#access-next");
    await a.click("#access-next");
    assert.equal(rows().length, 9);
    assert.equal(a.doc.querySelector("#access-next").disabled, true);
    const search = a.doc.querySelector("#access-search");
    search.value = "member 011";
    search.dispatchEvent(new a.w.Event("input", { bubbles: true }));
    assert.equal(rows().length, 1);
    assert.equal(a.doc.querySelector(".access-pages").hidden, true);
    search.value = "member 010";
    search.dispatchEvent(new a.w.Event("input", { bubbles: true }));
    assert.equal(rows().length, 0);
    assert.match(count.textContent, /No one matches/);
    await a.click("#access-removed");
    assert.equal(rows().length, 1);
    a.w.puter.workers.exec = exec;
    a.doc.querySelector("dialog").close();
    for (let n = 0; n < 10; n++) await a.tick();
  } finally {
    await shared.close();
  }
});

test("a role change still saving stays shown, and unavailable, after the list is searched", async () => {
  const shared = await sharedEditors("participants-pending", [
    item("note", 0, 0, { text: "A" }),
  ]);
  const [a] = shared.apps;
  try {
    const exec = a.w.puter.workers.exec;
    const members = [
      { uuid: "owner-id", username: "Owner", role: "owner" },
      ...Array.from({ length: 60 }, (_, n) => ({
        uuid: `member-${n}`,
        username: `Member ${String(n).padStart(3, "0")}`,
        role: "editor",
      })),
    ];
    const roles = [];
    let finish;
    a.w.puter.workers.exec = (url, options) => {
      const body = JSON.parse(options.body);
      if (body.op === "members")
        return Promise.resolve(new Response(JSON.stringify({ members })));
      if (body.op === "role") {
        roles.push(body.role);
        return new Promise(
          (r) => (finish = () => r(new Response(JSON.stringify({})))),
        );
      }
      return exec(url, options);
    };
    await a.click('[data-action="participants"]');
    const select = () =>
      a.doc.querySelector(
        '#participant-list [aria-label="Access for Member 001"]',
      );
    await shared.until(() => select(), "The member is listed");
    select().value = "viewer";
    select().dispatchEvent(new a.w.Event("change", { bubbles: true }));
    await a.tick();
    // The list is searched while the change is saving: the row shown anew
    // keeps the choice made, and cannot be changed again meanwhile.
    const search = a.doc.querySelector("#access-search");
    search.value = "member 001";
    search.dispatchEvent(new a.w.Event("input", { bubbles: true }));
    assert.equal(select().value, "viewer");
    assert.equal(select().disabled, true);
    select().dispatchEvent(new a.w.Event("change", { bubbles: true }));
    assert.deepEqual(roles, ["viewer"]);
    finish();
    await shared.until(() => !select().disabled, "The change is saved");
    assert.equal(select().value, "viewer");
    a.w.puter.workers.exec = exec;
    a.doc.querySelector("dialog").close();
    for (let n = 0; n < 10; n++) await a.tick();
  } finally {
    await shared.close();
  }
});

