test("the participants button says how many more people there are, shortened past a thousand", async () => {
  const shared = await sharedEditors("participant-overflow", [
    item("note", 0, 0, { text: "A" }),
  ]);
  const [a] = shared.apps;
  const button = () => a.doc.querySelector(".participants");
  let extra = 498;
  try {
    // Check-ins answer with a roster of many more people.
    const exec = a.w.puter.workers.exec;
    a.w.puter.workers.exec = async (url, options) => {
      const response = await exec(url, options);
      if (JSON.parse(options.body).op !== "presence" || !response.ok)
        return response;
      const body = await response.json();
      const [first] = body.roster;
      body.roster.push(
        ...Array.from({ length: extra }, (_, n) => ({
          ...first,
          session: `extra-${n}`,
          user: `extra-user-${n}`,
          username: `Person ${n}`,
        })),
      );
      return new Response(JSON.stringify(body));
    };
    const more = () =>
      button().querySelector(".participant-face.more")?.dataset.initials;
    a.w.dispatchEvent(new a.w.Event("online"));
    await shared.until(
      () => button().textContent.startsWith("500 "),
      "Everyone is counted",
    );
    // Alice sees three faces of the 499 others, and how many more.
    assert.equal(more(), "+496");
    extra = 1200;
    a.w.dispatchEvent(new a.w.Event("online"));
    await shared.until(
      () => button().textContent.startsWith("1202 "),
      "A larger room is counted",
    );
    assert.equal(more(), "+1.2K");
  } finally {
    await shared.close();
  }
});

test("icon buttons show a styled tooltip with their shortcut soon after a mouse rests on them", async () => {
  const app = await setup();
  const { doc, w, click } = app;
  try {
    await click('[data-action="new"]');
    const button = doc.querySelector('[data-action="tool-note"]');
    const over = (type, target, related = null) => {
      const event = new w.MouseEvent(type, {
        bubbles: true,
        relatedTarget: related,
      });
      Object.defineProperty(event, "pointerType", { value: "mouse" });
      target.dispatchEvent(event);
    };
    over("pointerover", button);
    const tip = () => doc.querySelector(".ui-tooltip");
    assert.ok(!tip() || tip().hidden, "Not at once");
    await new Promise((r) => setTimeout(r, 350));
    assert.equal(tip().hidden, false);
    assert.equal(tip().querySelector("span").textContent, "Sticky note");
    assert.equal(tip().querySelector("kbd").textContent, "N");
    // The browser's own tooltip stays away while it shows, and comes back.
    assert.equal(button.hasAttribute("title"), false);
    over("pointerout", button, doc.body);
    assert.equal(tip().hidden, true);
    assert.equal(button.getAttribute("title"), "Sticky note (N)");
    // Moving straight on to the next button shows its tooltip at once.
    const pan = doc.querySelector('[data-action="tool-hand"]');
    over("pointerover", pan);
    await new Promise((r) => setTimeout(r, 0));
    assert.equal(tip().querySelector("span").textContent, "Pan");
    over("pointerout", pan, doc.body);
  } finally {
    await app.close();
  }
});

