test("colour swatches show only for objects that have a fill, and change only those", async () => {
  const app = await setup();
  const { doc } = app;
  try {
    const { selected } = await rotationFixture(app, [
      item("text", 0, 0, { text: "Heading" }),
      item("frame", 0, 200, { w: 300, h: 200, text: "Frame" }),
      item("note", 400, 0, { text: "Note", color: "#f6e7a4" }),
    ]);
    const pick = async (text) =>
      [...doc.querySelectorAll("#board-outline [data-id]")]
        .find((b) => b.textContent.endsWith(text))
        .click();
    for (const text of ["Heading", "Frame"]) {
      await pick(text);
      assert.equal(
        doc.querySelector("#selection-tools [data-color]"),
        null,
        text,
      );
    }
    await pick("Note");
    assert.ok(doc.querySelector("#selection-tools [data-color]"));
    // With everything selected, a colour leaves the text and frame alone.
    doc.querySelector("#canvas").dispatchEvent(
      new app.w.KeyboardEvent("keydown", {
        key: "a",
        ctrlKey: true,
        bubbles: true,
        cancelable: true,
      }),
    );
    await app.tick();
    doc.querySelector('#selection-tools [data-color="#d8e8cf"]')?.click() ??
      doc.querySelectorAll("#selection-tools [data-color]")[1].click();
    const after = new Map(selectedClipboard(app).map((i) => [i.type, i]));
    assert.equal(
      after.get("text").color,
      selected.find((i) => i.type === "text").color,
    );
    assert.equal(
      after.get("frame").color,
      selected.find((i) => i.type === "frame").color,
    );
    assert.notEqual(after.get("note").color, "#f6e7a4");
  } finally {
    await app.close();
  }
});

