test("the share dialog shows the same invitation link each time it opens until it is reset", async () => {
  const shared = await sharedEditors("share-same-link", [
    item("note", 0, 0, { text: "A" }),
  ]);
  const [a] = shared.apps;
  const invites = () =>
    shared.env.calls.filter((c) => c.op === "invite").length;
  const open = async () => {
    await a.click('[data-action="share"]');
    await confirmShare(a);
    await shared.until(
      () => a.doc.querySelector("#share-link")?.value,
      "The link is ready",
    );
    return a.doc.querySelector("#share-link").value;
  };
  try {
    const before = invites();
    const first = await open();
    a.doc.querySelector("dialog").close();
    const second = await open();
    assert.equal(second, first);
    assert.equal(invites(), before + 1);
    await a.click("#revoke-invites");
    await shared.until(
      () =>
        a.doc.querySelector("#share-link").value &&
        a.doc.querySelector("#share-link").value !== first,
      "Reset makes a new link",
    );
    a.doc.querySelector("dialog").close();
    const third = await open();
    assert.notEqual(third, first);
    a.doc.querySelector("dialog").close();
    // Links reset from elsewhere, as another device, are not shown again,
    // and Copy pressed while that is being checked makes one link.
    await shared.env.service.call(owner, {
      op: "revoke-invite",
      room: "share-same-link",
    });
    const made = invites();
    a.doc.querySelector('[data-action="share"]').click();
    while (!a.doc.querySelector("#copy-share"))
      await new Promise((r) => setTimeout(r, 0));
    a.doc.querySelector("#copy-share").click();
    await shared.until(
      () => a.doc.querySelector("#share-link")?.value,
      "The link is ready",
    );
    for (let n = 0; n < 10; n++) await a.tick();
    const fourth = a.doc.querySelector("#share-link").value;
    assert.notEqual(fourth, third);
    assert.equal(invites(), made + 1);
    a.doc.querySelector("dialog").close();
    for (let n = 0; n < 10; n++) await a.tick();
  } finally {
    await shared.close();
  }
});

