test("Fit shows a board of any size, zooming out past 15% without drawing unreadable text", async () => {
  const app = await setup();
  const { doc, click } = app;
  try {
    await rotationFixture(app, [
      item("note", 0, 0, { text: "West" }),
      item("note", 30000, 20000, { text: "East" }),
    ]);
    await click('[data-action="fit"]');
    const v = renderedView(app);
    assert.ok(v.z < 0.15 && v.z >= 0.01, `${v.z}`);
    for (const p of [
      { x: 0, y: 0 },
      { x: 30190, y: 20160 },
    ]) {
      const x = v.x + p.x * v.z,
        y = v.y + p.y * v.z;
      assert.ok(x >= 0 && x <= 1200 && y >= 0 && y <= 900, `${x},${y}`);
    }
    // Nothing is set as text that would be a few pixels tall.
    const ctx = doc.querySelector("#canvas").getContext("2d");
    const written = [];
    const fillText = ctx.fillText;
    ctx.fillText = function (text, ...rest) {
      written.push(text);
      return fillText.call(this, text, ...rest);
    };
    await click('[data-action="zoom-out"]');
    assert.ok(!written.some((t) => /West|East/.test(t)), written.join("|"));
    // Close enough to read, the text is drawn again.
    written.length = 0;
    const west = [...doc.querySelectorAll("#board-outline [data-id]")].find(
      (b) => b.textContent.endsWith("West"),
    );
    await click(`#board-outline [data-id="${west.dataset.id}"]`);
    doc.querySelector("#canvas").dispatchEvent(
      new app.w.KeyboardEvent("keydown", {
        key: "2",
        code: "Digit2",
        altKey: true,
        bubbles: true,
        cancelable: true,
      }),
    );
    assert.ok(renderedView(app).z >= 0.15);
    assert.ok(
      written.some((t) => /West/.test(t)),
      written.join("|"),
    );
    ctx.fillText = fillText;
  } finally {
    await app.close();
  }
});

