test("a frame is outlined while objects are dragged into it", async () => {
  const app = await setup();
  const { doc } = app;
  try {
    const { pointer, selected } = await rotationFixture(app, [
      item("frame", 0, 0, { w: 600, h: 400, text: "Target" }),
      item("note", 800, 0, { text: "Joining" }),
    ]);
    const frame = selected.find((i) => i.type === "frame"),
      note = selected.find((i) => i.type === "note");
    await app.click(`#board-outline [data-id="${note.id}"]`);
    const ctx = doc.querySelector("#canvas").getContext("2d");
    const rects = [];
    const strokeRect = ctx.strokeRect;
    ctx.strokeRect = function (...args) {
      rects.push(args.join(","));
      return strokeRect.apply(this, args);
    };
    const outlined = () =>
      rects.includes([frame.x, frame.y, frame.w, frame.h].join(","));
    const from = { x: note.x + 50, y: note.y + 50 };
    pointer("pointerdown", from);
    // Still outside the frame: nothing is outlined.
    pointer("pointermove", { x: from.x + 20, y: from.y });
    assert.equal(outlined(), false);
    pointer("pointermove", {
      x: frame.x + 300 - (note.x + 95 - from.x),
      y: frame.y + 200,
    });
    assert.equal(outlined(), true);
    pointer("pointerup", {
      x: frame.x + 300 - (note.x + 95 - from.x),
      y: frame.y + 200,
    });
    rects.length = 0;
    await app.tick();
    assert.equal(outlined(), false, "Not after the drop");
    ctx.strokeRect = strokeRect;
  } finally {
    await app.close();
  }
});

test("a finger on a selected shape small on screen moves it rather than resizing it", async () => {
  const app = await setup();
  try {
    const { selected } = await rotationFixture(app, [
      item("rect", 0, 0, { w: 190, h: 160, text: "Drag me" }),
    ]);
    for (let n = 0; n < 8; n++) await app.click('[data-action="zoom-out"]');
    const v = renderedView(app);
    const [shape] = selected;
    // 10 px below its top edge, a third of the way across.
    const sx = v.x + (shape.x + shape.w * 0.3) * v.z,
      sy = v.y + shape.y * v.z + 10;
    canvasPointer(app, "pointerdown", 7, sx, sy, { pointerType: "touch" });
    for (let k = 1; k <= 5; k++)
      canvasPointer(app, "pointermove", 7, sx + 8 * k, sy + 8 * k, {
        pointerType: "touch",
      });
    canvasPointer(app, "pointerup", 7, sx + 40, sy + 40, {
      pointerType: "touch",
    });
    await app.tick();
    const [after] = selectedClipboard(app);
    assert.equal(after.w, shape.w);
    assert.equal(after.h, shape.h);
    assert.ok(after.x > shape.x && after.y > shape.y, "It moved");
  } finally {
    await app.close();
  }
});

test("a slide shows what its frame holds without the frame's outline or title", async () => {
  const app = await setup();
  const { doc, click } = app;
  try {
    const frame = item("frame", 0, 0, { w: 600, h: 400, text: "Agenda" });
    await rotationFixture(app, [
      frame,
      item("note", 100, 100, { text: "Point one", parentId: frame.id }),
    ]);
    await click('[data-action="present"]');
    const written = [];
    const proto = Object.getPrototypeOf(
      doc.createElement("canvas").getContext("2d"),
    );
    const fillText = proto.fillText;
    proto.fillText = function (text, ...rest) {
      written.push(text);
      return fillText.call(this, text, ...rest);
    };
    try {
      await click("#start-presentation");
    } finally {
      proto.fillText = fillText;
    }
    assert.ok(
      written.some((t) => /Point one/.test(t)),
      written.join("|"),
    );
    assert.ok(!written.some((t) => /Agenda/.test(t)), written.join("|"));
    assert.match(doc.querySelector("#slide-count").textContent, /Agenda/);
  } finally {
    await app.close();
  }
});

test("resizing a frame takes in what it comes to cover and lets go of what it leaves", async () => {
  const app = await setup();
  try {
    const frame = item("frame", 0, 0, { w: 600, h: 400, text: "Area" });
    const { selected } = await rotationFixture(app, [
      frame,
      item("note", 100, 100, { text: "Inside", parentId: frame.id }),
      item("note", 700, 100, { text: "Outside" }),
    ]);
    await app.click('[data-action="toggle-snapping"]');
    const placed = selected.find((i) => i.type === "frame");
    const parentOf = (text) =>
      allClipboard(app).find((i) => i.text === text).parentId;
    assert.equal(parentOf("Outside"), undefined);
    await app.click(`#board-outline [data-id="${placed.id}"]`);
    const v = renderedView(app);
    const drag = (from, to) => {
      const at = (p) => [v.x + p.x * v.z, v.y + p.y * v.z];
      canvasPointer(app, "pointerdown", 5, ...at(from), {
        pointerType: "mouse",
      });
      canvasPointer(app, "pointermove", 5, ...at(to), { pointerType: "mouse" });
      canvasPointer(app, "pointerup", 5, ...at(to), { pointerType: "mouse" });
    };
    const corner = { x: placed.x + placed.w, y: placed.y + placed.h };
    drag(corner, { x: corner.x + 400, y: corner.y });
    assert.equal(parentOf("Outside"), placed.id);
    assert.equal(parentOf("Inside"), placed.id);
    // Back to its size, the note it no longer covers leaves it.
    await app.click(`#board-outline [data-id="${placed.id}"]`);
    drag({ x: corner.x + 400, y: corner.y }, corner);
    assert.equal(parentOf("Outside"), undefined);
    assert.equal(parentOf("Inside"), placed.id);
  } finally {
    await app.close();
  }
});

test("during a vote, a participant's click on a note casts a vote rather than selecting it", async () => {
  const note = item("note", 100, 100, { text: "Vote for me" });
  const shared = await sharedEditors("click-to-vote", [note]);
  const [a, b] = shared.apps;
  try {
    await a.click('.canvas-navigation [data-action="facilitation"]');
    await a.click("#fac-tab-vote");
    a.doc.querySelector("#fac-vote-hidden").checked = false;
    a.doc
      .querySelector("#fac-vote-form")
      .dispatchEvent(new a.w.Event("submit", { cancelable: true }));
    await shared.until(
      () => b.doc.querySelector('[data-fac-vote="add"]'),
      "Bob can vote",
    );
    const v = renderedView(b);
    const at = [v.x + (note.x + 95) * v.z, v.y + (note.y + 80) * v.z];
    canvasPointer(b, "pointerdown", 1, ...at, { pointerType: "mouse" });
    canvasPointer(b, "pointerup", 1, ...at, { pointerType: "mouse" });
    await b.tick();
    assert.equal(b.doc.querySelector("#selection-tools").hidden, true);
    await shared.until(
      () =>
        /1 participant has voted/.test(
          a.doc.querySelector("#fac-tabpanel").textContent,
        ),
      "Bob's click is his vote",
    );
    // The facilitator's own click still selects, to arrange the board.
    const va = renderedView(a);
    canvasPointer(
      a,
      "pointerdown",
      1,
      va.x + (note.x + 95) * va.z,
      va.y + (note.y + 80) * va.z,
      { pointerType: "mouse" },
    );
    canvasPointer(
      a,
      "pointerup",
      1,
      va.x + (note.x + 95) * va.z,
      va.y + (note.y + 80) * va.z,
      { pointerType: "mouse" },
    );
    await a.tick();
    assert.equal(selectedClipboard(a)[0]?.id, note.id);
    await new Promise((r) => setTimeout(r, 300));
  } finally {
    await shared.close();
  }
});

