test("leaving a board mid-presentation ends it without moving the next board's view, and Shift reverses only Space", async () => {
  const app = await setup();
  const { doc, w, click, tick } = app;
  try {
    // Board B, then back to the library, then board A with frames.
    await click('[data-action="new"]');
    const before = renderedView(app);
    await click('[data-action="home"]');
    await rotationFixture(app, [
      item("frame", 0, 0, { w: 400, h: 300, text: "One", order: 0 }),
      item("frame", 600, 0, { w: 400, h: 300, text: "Two", order: 1 }),
      item("frame", 1200, 0, { w: 400, h: 300, text: "Three", order: 2 }),
    ]);
    await click('[data-action="present"]');
    await click("#start-presentation");
    const count = () => doc.querySelector("#slide-count").textContent;
    const key = (key, extra = {}) =>
      doc.querySelector("#slide-canvas").dispatchEvent(
        new w.KeyboardEvent("keydown", {
          key,
          bubbles: true,
          cancelable: true,
          ...extra,
        }),
      );
    key("ArrowRight", { shiftKey: true });
    assert.match(count(), /^2 \/ 3/);
    key(" ", { shiftKey: true });
    assert.match(count(), /^1 \/ 3/);
    // Back twice reaches board B.
    w.history.back();
    for (let n = 0; n < 40 && !doc.querySelector(".library"); n++) await tick();
    w.history.back();
    for (let n = 0; n < 40 && !doc.querySelector("#canvas"); n++) await tick();
    await new Promise((r) => setTimeout(r, 700));
    assert.equal(doc.querySelector("dialog[open]"), null);
    assert.deepEqual(renderedView(app), before);
  } finally {
    await app.close();
  }
});

