test("a presentation ends when the facilitator hides every frame it shows", async () => {
  const env = environment();
  env.service.now = () => Date.now();
  const quiz = item("frame", 0, 0, { w: 400, h: 300, text: "Quiz answers" }),
    open = item("frame", 600, 0, { w: 400, h: 300, text: "Open frame" });
  const initial = {
    version: 1,
    id: crypto.randomUUID(),
    title: "Hidden while presented",
    items: [
      quiz,
      open,
      item("note", 20, 60, { text: "Answer key: 42", parentId: quiz.id }),
    ],
  };
  const seed = new SharedDocument();
  seed.commit(initial);
  await env.service.call(owner, {
    op: "create",
    room: initial.id,
    update: encode(seed.update()),
  });
  seed.destroy();
  const { token } = await env.service.call(owner, {
    op: "invite",
    room: initial.id,
    role: "editor",
  });
  const app = await setup(env.sdk(collaborator));
  const until = async (fn, message) => {
    const deadline = Date.now() + 8000;
    while (!fn() && Date.now() < deadline) await app.tick();
    assert.ok(fn(), message);
  };
  const outline = () => app.doc.querySelector("#slide-outline")?.textContent;
  const hide = (ids) =>
    commitAs(env.service, owner, initial.id, (b) => {
      b.workshop = ids ? { settings: { hide: ids } } : undefined;
      if (!ids) delete b.workshop;
    });
  try {
    await joinLink(app, initial.id, token);
    await until(() => app.doc.querySelector("#canvas"), "Joined");
    // Hiding one of two frames leaves the other to present.
    await app.click('[data-action="present"]');
    await app.click("#start-presentation");
    assert.match(outline(), /Answer key/);
    await hide([quiz.id]);
    await until(
      () => outline() === "Frame: Open frame",
      "The hidden frame leaves the presentation",
    );
    await app.click("#slide-exit");
    await hide(null);
    await until(
      () =>
        /Answer key/.test(app.doc.querySelector("#board-outline").textContent),
      "The frame is shown again",
    );
    // Hiding the only frame presented ends the presentation.
    await app.click('[data-action="present"]');
    app.doc.querySelector(`.slide-choices input[value="${open.id}"]`).checked =
      false;
    await app.click("#start-presentation");
    assert.match(outline(), /Answer key: 42/);
    await hide([quiz.id]);
    await until(
      () => !app.doc.querySelector(".presentation-dialog[open]"),
      "The presentation ends",
    );
    assert.match(
      app.doc.querySelector("#toast").textContent,
      /presented frames are no longer available/,
    );
    assert.doesNotMatch(app.doc.body.textContent, /Answer key/);
  } finally {
    await app.close();
  }
});

test("a shared board that could not connect tries again, at once when back online, unless access was refused", async () => {
  const env = environment();
  env.service.now = () => Date.now();
  const initial = {
    version: 1,
    id: crypto.randomUUID(),
    title: "Outage",
    items: [item("note", 200, 160, { text: "Here" })],
  };
  const seed = new SharedDocument();
  seed.commit(initial);
  await env.service.call(owner, {
    op: "create",
    room: initial.id,
    update: encode(seed.update()),
  });
  seed.destroy();
  const { token } = await env.service.call(owner, {
    op: "invite",
    room: initial.id,
    role: "editor",
  });
  const app = await setup(env.sdk(collaborator));
  const saveState = () => app.doc.querySelector("#save-state")?.textContent;
  const until = async (fn, message) => {
    const deadline = Date.now() + 8000;
    while (!fn() && Date.now() < deadline) await app.tick();
    assert.ok(fn(), message);
  };
  const call = env.service.call.bind(env.service);
  let refusal = null,
    joins = 0;
  env.service.call = async (user, input) => {
    if (input.op === "join") {
      joins++;
      if (refusal) throw Object.assign(Error(refusal.message), refusal);
    }
    return call(user, input);
  };
  try {
    await joinLink(app, initial.id, token);
    await until(() => /Saved/.test(saveState()), "Joined");
    await app.click('[data-action="home"]');
    refusal = { message: "Try again later.", status: 503 };
    await app.click("[data-open]");
    await until(
      () => /Cannot reach the shared board/.test(saveState()),
      "The outage",
    );
    refusal = null;
    app.w.dispatchEvent(new app.w.Event("online"));
    await until(
      () => /Saved/.test(saveState()),
      "Connected again once back online",
    );
    await app.click('[data-action="add-note"]');
    assert.doesNotMatch(
      app.doc.querySelector("#toast").textContent,
      /read-only/,
    );
    // Access refused is not tried again.
    await app.click('[data-action="home"]');
    refusal = {
      message: "You no longer have access to this board.",
      status: 403,
    };
    await app.click("[data-open]");
    await until(() => /Could not connect/.test(saveState()), "Refused");
    const tried = joins;
    app.w.dispatchEvent(new app.w.Event("online"));
    await new Promise((r) => setTimeout(r, 300));
    assert.equal(joins, tried);
  } finally {
    env.service.call = call;
    await app.close();
  }
});

