test("on a phone, opening a discussion shows its pin below the Comments panel", async () => {
  const app = await setup(),
    { doc, click } = app;
  try {
    await click('[data-action="new"]');
    doc.querySelector("#canvas").getBoundingClientRect = () => ({
      left: 0,
      top: 0,
      right: 390,
      bottom: 754,
      width: 390,
      height: 754,
    });
    dispatchTransfer(
      app,
      "paste",
      transferData({ "text/plain": "Review target" }),
    );
    await click('[data-action="add-comment"]');
    doc.querySelector("#comment-text").value = "Review";
    await click('#comment-form [type="submit"]');
    const id = doc.querySelector("[data-thread]").dataset.thread;
    // The panel spans the top of the canvas, as Find on board does.
    const box = { left: 12, top: 64, right: 378, bottom: 516 };
    doc.querySelector("#comments-panel").getBoundingClientRect = () => ({
      ...box,
      width: box.right - box.left,
      height: box.bottom - box.top,
    });
    await click(`[data-thread="${id}"]`);
    const pin = doc.querySelector(`[data-comment="${id}"]`),
      x = parseFloat(pin.style.left),
      y = parseFloat(pin.style.top);
    assert.ok(y - 17 > box.bottom && y + 17 < 754, `pin centred at y ${y}`);
    assert.ok(x - 17 > 0 && x + 17 < 390, `pin centred at x ${x}`);
    // With too little room below a taller panel, it is centred as if the
    // panel were closed, ready for when it is.
    box.bottom = 700;
    await click(`[data-thread="${id}"]`);
    assert.equal(parseFloat(pin.style.top), 754 / 2);
  } finally {
    await app.close();
  }
});

