test("opening a Puter card for a board another tab keeps newer here opens that copy instead of writing over it", async () => {
  const remote = board("Remote plan");
  remote.updated = 1000;
  const files = new Map([
    [
      "whiteboard/catalog.json",
      JSON.stringify([{ id: remote.id, title: remote.title }]),
    ],
    [`whiteboard/${remote.id}.json`, JSON.stringify(remote)],
  ]);
  const puter = {
    env: "web",
    auth: {
      isSignedIn: () => true,
      signIn: async () => {},
      getUser: async () => ({ uuid: "u1", username: "alice" }),
    },
    fs: {
      async read(path) {
        if (!files.has(path)) throw { code: "subject_does_not_exist" };
        return new Blob([files.get(path)]);
      },
      async readdir() {
        return [];
      },
      async write(path, value) {
        files.set(path, typeof value === "string" ? value : await value.text());
        return { path };
      },
    },
  };
  const indexedDB = new IDBFactory();
  const app = await setup(puter, { indexedDB });
  try {
    const { doc, tick } = app;
    const waitFor = async (fn, what) => {
      for (let n = 0; n < 200 && !fn(); n++) await tick();
      assert.ok(fn(), what);
    };
    await waitFor(
      () => doc.querySelector("[data-open-cloud]"),
      "The board in Puter has a card",
    );
    // Another tab opens the board and edits it before its upload.
    const edited = structuredClone(remote);
    edited.title = "Edited in another tab";
    edited.updated = 5000;
    edited.items.push(item("note", 0, 0, { text: "Unsynced idea" }));
    const db = await new Promise((resolve, reject) => {
      const r = indexedDB.open("whiteboard-v1", 3);
      r.onsuccess = () => resolve(r.result);
      r.onerror = () => reject(r.error);
    });
    await new Promise((resolve, reject) => {
      const tx = db.transaction("boards", "readwrite");
      tx.objectStore("boards").put(edited);
      tx.oncomplete = resolve;
      tx.onerror = () => reject(tx.error);
    });
    await app.click("[data-open-cloud]");
    await waitFor(
      () =>
        doc.querySelector("#board-title")?.value === "Edited in another tab",
      "The newer copy on this device opens",
    );
    const stored = await new Promise((resolve, reject) => {
      const tx = db.transaction("boards", "readonly"),
        r = tx.objectStore("boards").get(remote.id);
      tx.oncomplete = () => resolve(r.result);
      tx.onerror = () => reject(tx.error);
    });
    db.close();
    assert.equal(stored.items.length, 1, "The other tab's edit is kept");
  } finally {
    await app.close();
  }
});

test("deleting a shared board permanently removes what its sessions kept on this device", async () => {
  const indexedDB = new IDBFactory();
  const shared = board("Team plan");
  shared.shared = { server: "https://wb.test", room: "room-a" };
  shared.deletedAt = Date.now();
  const other = board("Other team");
  other.shared = { server: "https://wb.test", room: "room-b" };
  const open = () =>
    new Promise((resolve, reject) => {
      const r = indexedDB.open("whiteboard-v1", 3);
      r.onupgradeneeded = () => {
        r.result.createObjectStore("boards", { keyPath: "id" });
        r.result
          .createObjectStore("revisions", { keyPath: "id" })
          .createIndex("boardId", "boardId");
        r.result.createObjectStore("templates", { keyPath: "id" });
        r.result
          .createObjectStore("collaboration", { keyPath: "id" })
          .createIndex("scope", "scope");
      };
      r.onsuccess = () => resolve(r.result);
      r.onerror = () => reject(r.error);
    });
  const run = (db, store, mode, fn) =>
    new Promise((resolve, reject) => {
      const tx = db.transaction(store, mode),
        r = fn(tx.objectStore(store));
      tx.oncomplete = () => resolve(r?.result);
      tx.onerror = () => reject(tx.error);
    });
  let db = await open();
  await run(db, "boards", "readwrite", (s) => {
    s.put(shared);
    return s.put(other);
  });
  await run(db, "collaboration", "readwrite", (s) => {
    for (const [room, user] of [
      ["room-a", "u1"],
      ["room-a", "u2"],
      ["room-b", "u1"],
    ]) {
      const scope = `https://wb.test|${room}|${user}`;
      s.put({ id: `${scope}|snapshot`, scope });
      s.put({ id: `${scope}|asset:abc`, scope });
    }
  });
  db.close();
  const app = await setup(undefined, { indexedDB });
  try {
    await app.click('[data-filter="trash"]');
    await app.click("[data-open]");
    await app.click("#purge-board");
    await app.click("#confirm-purge");
    db = await open();
    const ids = await run(db, "collaboration", "readonly", (s) =>
      s.getAllKeys(),
    );
    db.close();
    assert.deepEqual(ids.sort(), [
      "https://wb.test|room-b|u1|asset:abc",
      "https://wb.test|room-b|u1|snapshot",
    ]);
  } finally {
    await app.close();
  }
});

test("following a board address reads only that board, not the whole library", async () => {
  const indexedDB = new IDBFactory();
  const app = await setup(undefined, { indexedDB });
  const getAll = IDBObjectStore.prototype.getAll;
  let libraryReads = 0;
  try {
    // Another tab makes a board after this one read the library.
    const made = board("Made in another tab");
    made.items.push(item("note", 0, 0, { text: "Hello" }));
    const db = await new Promise((resolve, reject) => {
      const r = indexedDB.open("whiteboard-v1", 3);
      r.onsuccess = () => resolve(r.result);
      r.onerror = () => reject(r.error);
    });
    await new Promise((resolve, reject) => {
      const tx = db.transaction("boards", "readwrite");
      tx.objectStore("boards").put(made);
      tx.oncomplete = resolve;
      tx.onerror = () => reject(tx.error);
    });
    db.close();
    IDBObjectStore.prototype.getAll = function (...args) {
      if (this.name === "boards") libraryReads++;
      return getAll.apply(this, args);
    };
    app.w.location.hash = `local=${made.id}`;
    for (
      let n = 0;
      n < 200 && app.doc.querySelector("#board-title")?.value !== made.title;
      n++
    )
      await app.tick();
    assert.equal(app.doc.querySelector("#board-title")?.value, made.title);
    assert.equal(libraryReads, 0);
  } finally {
    IDBObjectStore.prototype.getAll = getAll;
    await app.close();
  }
});

test("a board file is exported compactly and a large export can be imported again", async () => {
  const app = await setup();
  try {
    const { doc, w } = app;
    await app.click('[data-action="new"]');
    await app.click('[data-action="add-note"]');
    await app.click('[data-action="export"]');
    doc.querySelector("#export-format").value = "json";
    doc
      .querySelector("dialog form")
      .dispatchEvent(new w.Event("submit", { cancelable: true }));
    for (let n = 0; n < 40 && !app.downloads.length; n++) await app.tick();
    const text = await new Promise((resolve) => {
      const r = new w.FileReader();
      r.onload = () => resolve(r.result);
      r.readAsText(app.downloads.pop());
    });
    assert.equal(text, JSON.stringify(JSON.parse(text)), "No indentation");
    await app.click('[data-action="home"]');
    let fileInput;
    const nativeClick = w.HTMLInputElement.prototype.click;
    w.HTMLInputElement.prototype.click = function () {
      if (this.type === "file") fileInput = this;
      else nativeClick.call(this);
    };
    const importFile = async (size) => {
      await app.click('[data-action="import"]');
      const file = new w.File([text], "big.json", { type: "application/json" });
      Object.defineProperty(file, "size", { value: size });
      file.text = async () => text;
      Object.defineProperty(fileInput, "files", { value: [file] });
      fileInput.dispatchEvent(new w.Event("change"));
      for (let n = 0; n < 40 && !doc.querySelector("#canvas"); n++)
        await app.tick();
    };
    // Larger than the old limit, as a board with many pictures can be.
    await importFile(200 * 1024 * 1024);
    assert.ok(doc.querySelector("#canvas"), "The large file is imported");
    await app.click('[data-action="home"]');
    await importFile(600 * 1024 * 1024);
    assert.equal(doc.querySelector("#canvas"), null);
    assert.equal(
      doc.querySelector("#toast").textContent,
      "Choose a file smaller than 500 MB.",
    );
  } finally {
    await app.close();
  }
});

test("a shared board's images that have not downloaded are fetched or reported before they leave the board", async () => {
  const env = environment();
  env.service.now = () => Date.now();
  const data = "data:image/png;base64,AA==";
  const asset = await hash(data);
  const picture = item("image", 100, 100, {
    w: 40,
    h: 40,
    src: "asset:" + asset,
  });
  const initial = {
    version: 1,
    id: crypto.randomUUID(),
    title: "Pictures",
    items: [picture],
  };
  const seed = new SharedDocument();
  seed.commit(initial);
  await env.service.call(owner, {
    op: "create",
    room: initial.id,
    update: encode(seed.update()),
  });
  seed.destroy();
  await env.service.call(owner, {
    op: "asset.put",
    room: initial.id,
    asset,
    data,
  });
  const invite = await env.service.call(owner, {
    op: "invite",
    room: initial.id,
    role: "editor",
  });
  const sdk = env.sdk(collaborator),
    exec = sdk.workers.exec;
  // Downloads fail until the network comes back.
  let unavailable = true;
  sdk.workers.exec = async (url, options) =>
    JSON.parse(options.body).op === "asset.get" && unavailable
      ? new Response(JSON.stringify({ message: "Unavailable" }), {
          status: 503,
        })
      : exec(url, options);
  const app = await setup(sdk);
  const { doc, w } = app;
  const until = async (fn, message) => {
    const deadline = Date.now() + 8000;
    while (!fn() && Date.now() < deadline) await app.tick();
    assert.ok(fn(), message);
  };
  const exportJSON = async () => {
    app.downloads.length = 0;
    await app.click('[data-action="export"]');
    doc.querySelector("#export-format").value = "json";
    doc
      .querySelector("dialog form")
      .dispatchEvent(new w.Event("submit", { cancelable: true }));
    await until(
      () => app.downloads.length || !doc.querySelector("#export-error").hidden,
      "The export finishes",
    );
    if (!app.downloads.length)
      return doc.querySelector("#export-error").textContent;
    return JSON.parse(
      await new Promise((resolve) => {
        const r = new w.FileReader();
        r.onload = () => resolve(r.result);
        r.readAsText(app.downloads.pop());
      }),
    );
  };
  const duplicate = async () => {
    await app.click("[data-more]");
    await app.click("#copy-board");
  };
  const waiting =
    "Some images or files have not downloaded from the shared board yet. Try again in a moment.";
  try {
    await app.click('[data-action="join-shared"]');
    doc.querySelector("#join-link").value =
      `https://whiteboard.test/#server=https%3A%2F%2Fwhiteboard-test.puter.work&board=${initial.id}&invite=${invite.token}`;
    doc
      .querySelector("#join-link")
      .closest("form")
      .dispatchEvent(new w.Event("submit", { cancelable: true }));
    await until(
      () => !doc.querySelector("#join-link") && doc.querySelector("#canvas"),
      "Joined the shared board",
    );
    for (let n = 0; n < 10; n++) await app.tick();
    assert.equal(await exportJSON(), waiting);
    doc.querySelector("dialog[open]")?.close();
    await app.click(`#board-outline [data-id="${picture.id}"]`);
    const copied = transferData();
    dispatchTransfer(app, "copy", copied);
    assert.equal(copied.getData(CLIPBOARD_TYPE), "");
    assert.equal(doc.querySelector("#toast").textContent, waiting);
    await app.click('[data-action="home"]');
    // Away from the board, this device has nothing of the image to copy.
    await duplicate();
    assert.equal(doc.querySelectorAll(".board-card").length, 1);
    assert.equal(
      doc.querySelector("#toast").textContent,
      "Some images or files of this shared board are not on this device yet. Open the board to download them, then try again.",
    );
    doc.querySelector("dialog[open]")?.close();
    // Once the network is back, the export downloads the image itself.
    unavailable = false;
    await app.click("[data-open]");
    await until(() => doc.querySelector("#canvas"), "Opened again");
    const exported = await exportJSON();
    assert.equal(exported.items[0].src, data);
    validateBoard(exported);
    await app.click('[data-action="home"]');
    await duplicate();
    await until(
      () => doc.querySelectorAll(".board-card").length === 2,
      "Duplicated",
    );
  } finally {
    await app.close();
  }
});

test("a shape's border is set thicker, dashed or dotted from a toolbar popover in one undo step", async () => {
  const app = await setup();
  const { doc, w, click, tick } = app;
  try {
    await rotationFixture(app, [
      item("rect", 0, 0, { w: 200, h: 100, text: "Scope" }),
      item("ellipse", 260, 0, { w: 160, h: 100, lineStyle: "dotted" }),
      item("note", 480, 0, { text: "No border" }),
    ]);
    const change = async (selector, value) => {
      const input = doc.querySelector(selector);
      assert.ok(input, selector);
      input.value = value;
      input.dispatchEvent(new w.Event("change", { bubbles: true }));
      await tick();
    };
    const shapes = () =>
      allClipboard(app).filter((i) => ["rect", "ellipse"].includes(i.type));
    // All three are selected: the shapes' strokes differ.
    const toggle = doc.querySelector("#border-options");
    assert.ok(toggle, "A border button for the shapes");
    assert.equal(toggle.getAttribute("aria-label"), "Border");
    assert.equal(toggle.getAttribute("aria-controls"), "border-popover");
    assert.equal(doc.querySelector("#border-popover").hidden, true);
    // From the keyboard, the first setting takes focus.
    toggle.dispatchEvent(
      new w.MouseEvent("click", { bubbles: true, detail: 0 }),
    );
    await tick();
    assert.equal(doc.querySelector("#border-popover").hidden, false);
    assert.equal(doc.activeElement, doc.querySelector("#border-lineStyle"));
    assert.equal(doc.querySelector("#border-lineStyle").value, "");
    assert.equal(
      doc.querySelector("#border-lineStyle").selectedOptions[0].textContent,
      "Mixed",
    );
    assert.equal(doc.querySelector("#border-lineWidth").value, "1");
    await change("#border-lineStyle", "dashed");
    assert.deepEqual(
      shapes().map((i) => i.lineStyle),
      ["dashed", "dashed"],
    );
    // The popover stays open on the same setting after the redraw.
    assert.equal(doc.querySelector("#border-popover").hidden, false);
    assert.equal(doc.querySelector("#border-lineStyle").value, "dashed");
    await change("#border-lineWidth", "6");
    assert.deepEqual(
      shapes().map((i) => i.lineWidth),
      [6, 6],
    );
    const note = allClipboard(app).find((i) => i.type === "note");
    assert.equal(note.lineWidth, undefined, "Sticky notes have no border");
    await click('[data-action="undo"]');
    assert.deepEqual(
      shapes().map((i) => [i.lineStyle, i.lineWidth]),
      [
        ["dashed", undefined],
        ["dashed", undefined],
      ],
    );
    await click('[data-action="undo"]');
    assert.deepEqual(
      shapes().map((i) => i.lineStyle),
      [undefined, "dotted"],
    );
    // Back to the usual border, the fields are cleared, not stored.
    await click('[data-action="redo"]');
    allClipboard(app);
    await tick();
    await change("#border-lineStyle", "solid");
    assert.ok(shapes().every((i) => !("lineStyle" in i)));
    const audit = await axe.run(doc.querySelector("#selection-tools"), {
      rules: { "color-contrast": { enabled: false } },
    });
    assert.deepEqual(
      audit.violations.map((v) => v.id),
      [],
    );
    // A sticky note alone has no border to set.
    const noteId = note.id;
    await click(`#board-outline [data-id="${noteId}"]`);
    assert.equal(doc.querySelector("#border-options"), null);
    await change("#language", "fr");
    const rect = shapes()[0];
    await click(`#board-outline [data-id="${rect.id}"]`);
    assert.equal(
      doc.querySelector("#border-options").getAttribute("aria-label"),
      "Bordure",
    );
  } finally {
    await app.close();
  }
});
